    // ---- 这一页的零件 ----------------------------------------------------

    /** 一组的小标题：中文 + 拉丁小字，和冲印页的 section 头同一套。 */
    // ------------------------------------------------------------------ 屏幕方向

    private static final String[] ORIENT_IDS = {"auto", "portrait", "landscape"};
    private static final String[] ORIENT_NAMES = {"跟随系统", "锁定竖屏", "锁定横屏"};

    private String orientationPref() {
        final String v = getSharedPreferences("ui", MODE_PRIVATE).getString("orientation", "auto");
        return v == null ? "auto" : v;
    }

    private String orientationValue() {
        final String v = orientationPref();
        return ORIENT_NAMES["portrait".equals(v) ? 1 : "landscape".equals(v) ? 2 : 0];
    }

    /**
     * 把偏好交给系统。
     *
     * <p>**这是给自己用的旋钮，不是系统的。** 手机上「自动旋转」关着的人
     * 永远看不到横屏布局；这里能把横屏按住，也能反过来把竖屏钉死。
     * `SENSOR_LANDSCAPE` 允许左右两个横，`PORTRAIT` 只给正的竖。
     */
    private void applyOrientationPref() {
        final String v = orientationPref();
        final int want = "portrait".equals(v)
                ? android.content.pm.ActivityInfo.SCREEN_ORIENTATION_PORTRAIT
                : "landscape".equals(v)
                        ? android.content.pm.ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE
                        : android.content.pm.ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED;
        try { setRequestedOrientation(want); } catch (Throwable ignored) { }
    }

    /** 0 = 尺子（默认），1 = 轨道。 */
    private int sliderStylePref() {
        return getSharedPreferences("ui", MODE_PRIVATE).getInt("slider_style", 0);
    }

    private String sliderStyleValue() {
        return sliderStylePref() == DialBar.STYLE_TRACK ? "轨道" : "尺子";
    }

    private void showSliderStyleSheet() {
        final int cur = sliderStylePref();
        final String[] names = {
                "尺子 · 刻度在固定指针下滑动",
                "轨道 · 拇指跟手，刻度印在下面",
        };
        for (int i = 0; i < names.length; ++i) {
            if (i == cur) names[i] = names[i] + "  \u00b7 现在";
        }
        showActionSheet("滑杆样式",
                "所有滑杆和刻度盘都用这一套。\n"
                        + "尺子是原来的样子；轨道在下面印一排刻度，偶数位带数字。",
                names, which -> {
                    if (which < 0 || which >= 2) return;
                    getSharedPreferences("ui", MODE_PRIVATE).edit()
                            .putInt("slider_style", which).apply();
                    DialBar.setStyle(which);
                    // **已经建好的那些 bar 只在 onDraw 里读这个静态值**，所以
                    // 换一下 + 重画一遍就够了，不用重建任何一页。
                    invalidateDialBars(uiRoot);
                    if (settingsOpen) fillSettings();
                });
    }

    /** 让所有已经建好的滑杆按新的样子重画一遍。 */
    private static void invalidateDialBars(View v) {
        if (v == null || v.getVisibility() != View.VISIBLE) return;
        if (v instanceof DialBar) { v.invalidate(); return; }
        if (v instanceof android.view.ViewGroup) {
            final android.view.ViewGroup g = (android.view.ViewGroup) v;
            for (int i = 0; i < g.getChildCount(); ++i) invalidateDialBars(g.getChildAt(i));
        }
    }

    private void showOrientationSheet() {
        final String cur = orientationPref();
        int active = 0;
        for (int i = 0; i < ORIENT_IDS.length; ++i) if (ORIENT_IDS[i].equals(cur)) active = i;
        final String note = "横屏：照片在左，参数在右一栏，页签在栏顶。\n"
                + "「锁定」只影响这个 app，不动系统自己的自动旋转开关。";
        final String[] names = new String[ORIENT_NAMES.length];
        for (int i = 0; i < names.length; ++i) {
            names[i] = i == active ? ORIENT_NAMES[i] + "  \u00b7 现在" : ORIENT_NAMES[i];
        }
        showActionSheet("屏幕方向", note, names, which -> {
            if (which < 0 || which >= ORIENT_IDS.length) return;
            getSharedPreferences("ui", MODE_PRIVATE).edit()
                    .putString("orientation", ORIENT_IDS[which]).apply();
            applyOrientationPref();
            if (settingsOpen) fillSettings();
        });
    }

    private void settingsGroup(String title) {
        final TextView t = mixedLabel(title, 8.5f, UI_MUTED);
        t.setLetterSpacing(0.10f);
        t.setPadding(dp(16), dp(26), dp(16), dp(7));
        settingsBody.addView(t, new LinearLayout.LayoutParams(-1, -2));
    }

    private void settingsAdd(View row) {
        settingsBody.addView(row, new LinearLayout.LayoutParams(-1, -2));
    }

    /** 行与行之间的发丝线，左边留 16 dp —— 系统设置的做法。 */
    private void settingsRule() {
        final View v = new View(this);
        v.setBackgroundColor(UI_LINE);
        final LinearLayout.LayoutParams lp =
                new LinearLayout.LayoutParams(-1, Math.max(1, Math.round(dp(0.6f))));
        lp.leftMargin = dp(16);
        settingsBody.addView(v, lp);
    }

    /** 按下时的一层极淡的墨：这个 app 没有 Ripple，这是同一件事的最小实现。 */
    private android.graphics.drawable.Drawable settingsPress() {
        final android.graphics.drawable.StateListDrawable d =
                new android.graphics.drawable.StateListDrawable();
        d.addState(new int[]{android.R.attr.state_pressed},
                new android.graphics.drawable.ColorDrawable(darkTheme ? 0x14FFFFFF : 0x0A000000));
        d.addState(new int[0], new android.graphics.drawable.ColorDrawable(0x00000000));
        return d;
    }

    /** 一行：标题、可选副标题、可选右侧值、可选箭头。 */
    private LinearLayout settingsRow(String title, String sub, String value,
                                     boolean chevron, Runnable tap) {
        final LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setGravity(android.view.Gravity.CENTER_VERTICAL);
        row.setPadding(dp(16), dp(11), dp(16), dp(11));
        row.setBackground(settingsPress());
        row.setMinimumHeight(dp(52));

        final LinearLayout text = new LinearLayout(this);
        text.setOrientation(LinearLayout.VERTICAL);
        text.addView(mixedLabel(title, 11f, UI_INK));
        if (sub != null && !sub.isEmpty()) {
            final TextView s = mixedLabel(sub, 8.5f, UI_MUTED);
            s.setPadding(0, dp(3), 0, 0);
            s.setLineSpacing(dp(1), 1f);
            text.addView(s);
        }
        row.addView(text, new LinearLayout.LayoutParams(0, -2, 1f));

        if (value != null && !value.isEmpty()) {
            final TextView v = mixedLabel(value, 9f, UI_MUTED);
            v.setGravity(android.view.Gravity.END);
            v.setPadding(dp(12), 0, 0, 0);
            row.addView(v, new LinearLayout.LayoutParams(-2, -2));
        }
        if (chevron) {
            final TextView c = label("\u203a", 15f, UI_LINE, tfBody);
            c.setPadding(dp(7), 0, 0, 0);
            row.addView(c);
        }
        if (tap != null) {
            row.setOnClickListener(v -> tap.run());
        } else {
            row.setClickable(false);
        }
        return row;
    }

    /** 一行：标题左、平台开关右。整行都能点。 */
    private LinearLayout settingsSwitch(String title, String sub, boolean on,
                                        java.util.function.Consumer<Boolean> set) {
        final LinearLayout row = settingsRow(title, sub, null, false, null);
        final SettingsSwitch sw = new SettingsSwitch(this);
        sw.setOn(on);
        sw.setContentDescription(title);
        sw.setOnClickListener(v -> { sw.setOn(!sw.isOn()); set.accept(sw.isOn()); });
        row.setOnClickListener(v -> { sw.setOn(!sw.isOn()); set.accept(sw.isOn()); });
        row.setClickable(true);
        row.addView(sw, new LinearLayout.LayoutParams(dp(46), dp(28)));
        return row;
    }

    /** 一行带着勾的选项（主题、以后别的「选一个」）。 */
    private LinearLayout settingsCheckRow(String title, String sub, boolean checked, Runnable tap) {
        final LinearLayout row = settingsRow(title, sub, null, false, tap);
        final CheckMark tick = new CheckMark(this);
        tick.setVisibility(checked ? View.VISIBLE : View.INVISIBLE);
        row.addView(tick, new LinearLayout.LayoutParams(dp(16), dp(16)));
        return row;
    }

    /**
     * **开关是自己画的。** 平台 `android.widget.Switch` 在这套主题下带一个
     * 48 dp 的最小高度：手柄被拉成 48 dp 的大圆点，整行也比别人高 18 dp。
     * 46 x 28 dp、轨道 17、手柄 24 是系统设置里那枚开关的比例；颜色读
     * UI_BLUE / UI_LINE，两套配色自动对。160 ms 出缓动，不回弹。
     */
    private final class SettingsSwitch extends View {
        private final android.graphics.Paint p =
                new android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG);
        private final android.graphics.RectF r = new android.graphics.RectF();
        private boolean on;
        private float pos, fromPos;
        private long animAt;

        SettingsSwitch(android.content.Context c) { super(c); setClickable(true); }
        boolean isOn() { return on; }

        void setOn(boolean v) {
            if (on == v) return;
            fromPos = pos;
            on = v;
            animAt = android.os.SystemClock.uptimeMillis();
            invalidate();
        }

        @Override protected void onDraw(android.graphics.Canvas c) {
            final float w = getWidth(), h = getHeight();
            if (w <= 0f || h <= 0f) return;
            if (animAt != 0L) {
                final float u = Math.min(1f, (android.os.SystemClock.uptimeMillis() - animAt) / 160f);
                final float e = 1f - (1f - u) * (1f - u);
                pos = fromPos + ((on ? 1f : 0f) - fromPos) * e;
                if (u >= 1f) { pos = on ? 1f : 0f; animAt = 0L; }
                else postInvalidateOnAnimation();
            } else {
                pos = on ? 1f : 0f;
            }
            final float tr = h * 0.60f, ty = (h - tr) * 0.5f;
            r.set(0f, ty, w, ty + tr);
            p.setStyle(android.graphics.Paint.Style.FILL);
            p.setColor(on ? ((UI_BLUE & 0x00FFFFFF) | 0x73000000) : UI_LINE);
            c.drawRoundRect(r, tr * 0.5f, tr * 0.5f, p);
            final float d = h * 0.86f, rad = d * 0.5f;
            final float cx = rad + (w - d) * pos, cy = h * 0.5f;
            p.setColor(on ? UI_BLUE : (darkTheme ? 0xFF7A736A : 0xFFFFFFFF));
            c.drawCircle(cx, cy, rad, p);
            if (!on) {
                p.setStyle(android.graphics.Paint.Style.STROKE);
                p.setStrokeWidth(Math.max(1f, rad * 0.09f));
                p.setColor(darkTheme ? 0x33FFFFFF : 0x22000000);
                c.drawCircle(cx, cy, rad - p.getStrokeWidth() * 0.5f, p);
            }
        }
    }

    /**
     * 一个勾。
     *
     * <p>`\u2713` 在两个内置字体里都不一定有；缺字时系统会去回退字体里找，
     * 找到一个粗细、大小都不属于这套界面的勾。两条线是十一行代码，而且它跟片边
     * 页那支笔、跟按钮的描边都是同一种画法。
     */
    private static final class CheckMark extends View {
        private final Paint pen = new Paint(Paint.ANTI_ALIAS_FLAG);
        CheckMark(android.content.Context c) { super(c); }
        @Override protected void onDraw(android.graphics.Canvas c) {
            final float w = getWidth(), h = getHeight();
            pen.setStyle(Paint.Style.STROKE);
            pen.setStrokeCap(Paint.Cap.ROUND);
            pen.setStrokeJoin(Paint.Join.ROUND);
            pen.setStrokeWidth(Math.max(2f, w * 0.13f));
            pen.setColor(UI_BLUE);
            final Path p = new Path();
            p.moveTo(w * 0.14f, h * 0.54f);
            p.lineTo(w * 0.40f, h * 0.80f);
            p.lineTo(w * 0.88f, h * 0.22f);
            c.drawPath(p, pen);
        }
    }

    /** 只读的一条：小字标题在上，值在下，可长按复制。 */
    private void settingsInfo(String key, String value) {
        final LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.VERTICAL);
        box.setPadding(dp(16), dp(10), dp(16), dp(10));
        box.addView(mixedLabel(key, 8.5f, UI_MUTED));
        final TextView v = mixedLabel(value == null ? "?" : value, 10f, UI_INK);
        v.setPadding(0, dp(3), 0, 0);
        v.setLineSpacing(dp(2), 1f);
        v.setTextIsSelectable(true);
        box.addView(v);
        settingsBody.addView(box, new LinearLayout.LayoutParams(-1, -2));
    }

    private View licenceBlock(String title, String body) {
        final LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.VERTICAL);
        box.setPadding(dp(16), dp(14), dp(16), dp(6));
        box.addView(mixedLabel(title, 10f, UI_INK));
        final TextView b = mixedLabel(body, 8.5f, UI_MUTED);
        b.setPadding(0, dp(4), 0, 0);
        b.setLineSpacing(dp(2.5f), 1f);
        b.setTextIsSelectable(true);
        box.addView(b);
        return box;
    }

    // ---- 设置里几行要用到的值 --------------------------------------------

    /**
     * HDR 那一行的第二行。
     *
     * <p>`hdrPreviewRowText()` 是给动作单用的，它以「HDR 屏幕预览：」开头 ——
     * 放进设置页就会变成「HDR 屏幕预览 / HDR 屏幕预览：开」的自言自语。这里
     * 只留值，和别的行同一套写法。
     */
    private String hdrDetailLine() {
        if (!hdrDisplaySupported()) return "这台屏幕不支持，画布走 SDR";
        if (android.os.Build.VERSION.SDK_INT < 26) return "系统版本不支持";
        if (!hdrPreviewPref()) return "关 · 画布走 SDR";
        return String.format(java.util.Locale.US, "开 · 屏幕 %.1f 档 · 提亮 +%.1f 档",
                hdrHeadroomStops(), hdrFloor());
    }

    private String themeValue() {
        final boolean dark = getSharedPreferences("ui", MODE_PRIVATE).getBoolean("dark", false);
        return (dark ? "暗黑 \u00b7 黑橙" : "蓝白") + (dark != darkTheme ? " \u00b7 待生效" : "");
    }

    private String presetCountLine() {
        final int n = presetList().length();
        return n == 0 ? "还没有" : n + " 套";
    }

    private String deviceReportLine() {
        final String last = DeviceReport.lastAnswer(this);
        return "每周一次，只报机型和 GPU" + (last == null || last.isEmpty() ? "" : " \u00b7 " + last);
    }

    private String debugSummaryLine() {
        final int mp = debugPixelCapMp(), sim = debugStorageLimitMib(), band = debugBandCap();
        if (mp == 0 && sim == 0 && band == 0) return "按设备自动";
        final StringBuilder b = new StringBuilder();
        b.append(mp == 0 ? "像素上限按设备" : "像素上限 " + mp + " MP");
        if (sim > 0) b.append(" \u00b7 绑定 ").append(sim).append(" MiB");
        if (band > 0) b.append(" \u00b7 分带 ").append(band >= 100000000 ? "无" : (band / 1000000) + "M");
        return b.toString();
    }

    /** 主题换了但界面还是旧的一套：保存进度，然后让这个 Activity 自己重建。 */
    private void relaunchForTheme() {
        try { saveLookIntoFrames(); } catch (Throwable ignored) { }
        try { saveSessionState(); } catch (Throwable ignored) { }
        try {
            recreate();
        } catch (Throwable t) {
            showInAppToast("重建失败，请手动重新打开：" + t);
        }
    }

    /** 动作单时代那个分支，搬到这里；设置页关掉之后仍然给出同一张对话框。 */
    private void uploadRecentSteps() {
        final String ring = CrashTrail.snapshot(this);
        final String head = "user-report\n" + reportHead()
                + "steps=" + DebugSink.ringSize() + "\n";
        new Thread(() -> {
            final boolean ok = DebugSink.report("steps", head,
                    ring.isEmpty() ? "(这次还没有记录)" : ring);
            runOnUiThread(() -> showTextDialog(
                    ok ? "已上传最近的步骤" : "上传失败",
                    "记录号 " + DebugSink.REF + "\n\n"
                    + (ring.isEmpty() ? "(这次还没有记录)" : ring)
                    + (ok ? "\n已经上传，不用再发给我了。"
                          : "\n网络没通，请把这段复制发给我。"),
                    false));
        }, "SpektraLab-report").start();
    }

    private static final String REPO = "https://github.com/SAINTTaiYi/SpektraLab-Android";

    private void openRepo() { openUrl(REPO); }

    private void openUrl(String url) {
        try {
            startActivity(new android.content.Intent(android.content.Intent.ACTION_VIEW,
                    android.net.Uri.parse(url)));
        } catch (Throwable t) {
            copyToClipboard("SpektraLab 仓库", "https://github.com/SAINTTaiYi/SpektraLab-Android");
            showInAppToast("已复制仓库地址");
        }
    }

    /** Reads assets/resources/stock_catalog.json (generated from the engine's profiles). */
    private void loadStockCatalog() {
        try (InputStream in = getAssets().open("resources/stock_catalog.json")) {
            byte[] buf = new byte[in.available()];
            int off = 0, n;
            while (off < buf.length && (n = in.read(buf, off, buf.length - off)) > 0) off += n;
            org.json.JSONObject root = new org.json.JSONObject(new String(buf, java.nio.charset.StandardCharsets.UTF_8));
            filmTargetPrints.clear();
            readStocks(root.optJSONArray("films"), filmIds, filmLabels, filmTypes, filmTargetPrints);
            readStocks(root.optJSONArray("prints"), printIds, printLabels, null, null);
        } catch (Throwable t) {
            // **Not `Log.w`.** Everything else in the app goes through DebugSink's
            // ring buffer, which is what a report uploads; a bare logcat line is
            // invisible to the one person who needs it.
            DebugSink.text("catalog", "the film catalogue did not load: " + t);
        }
        if (filmIds.isEmpty()) { filmIds.add("kodak_portra_400"); filmLabels.add("Kodak Portra 400"); }
        if (printIds.isEmpty()) { printIds.add("kodak_portra_endura"); printLabels.add("Kodak Portra Endura"); }

        loadFotuCatalog();

        rebuildBrandRow();
        rebuildFilmCards();
        refreshPaperLabel();
    }

    /**
     * The second engine's catalogue: 47 stocks, read from its own asset.
     *
     * <p>The whole thing is wrapped: {@code FotuFilm}'s static block loads two
     * native libraries, and a launch must not depend on them. If either fails
     * the shelf simply has no fotufilm tab, and the first engine -- the one
     * every existing user came for -- starts exactly as before.
     */
    private void loadFotuCatalog() {
        // **The launcher's debris.** Every render of a fotufilm frame used to
        // leave its JPEG in the cache dir -- one per slider release, one to
        // three megabytes each. Nothing before this build ever removed them,
        // so the sweep runs once per launch, before any render can be in
        // flight, and only on files this feature owns.
        try {
            final java.io.File[] stale = getCacheDir().listFiles();
            if (stale != null) {
                for (java.io.File f : stale) {
                    final String n = f.getName();
                    // Both writers: a TIFF left behind is thirty megabytes,
                    // not three, so a crash mid-export is worth sweeping.
                    if (n.startsWith("fotu-") && (n.endsWith(".jpg") || n.endsWith(".tif")))
                        f.delete();
                }
            }
        } catch (Throwable ignored) { }
        try {
            fotuIds.clear();
            fotuNames.clear();
            fotuSubs.clear();
            fotuKinds.clear();
            fotuStocks.clear();
            FOTU_BRAND.clear();
            FOTU_TECH.clear();
            for (FotuFilm.Stock stock : FotuFilm.readCatalog(this)) {
                fotuIds.add(stock.id);
                fotuNames.add(stock.name);
                fotuSubs.add(stock.subtitle);
                fotuKinds.add(stock.kindMark());
                fotuStocks.put(stock.id, stock);
                FOTU_BRAND.put(FotuFilm.PREFIX + stock.id, stock.brand);
                FOTU_TECH.put(FotuFilm.PREFIX + stock.id,
                        stock.reflection ? "INSTANT"
                                : stock.reversal ? "COLOUR REVERSAL"
                                : stock.monochrome ? "BLACK & WHITE FILM"
                                : "COLOUR NEGATIVE");
            }
            DebugSink.text("fotufilm", "catalog " + fotuIds.size() + " stocks");
        } catch (Throwable t) {
            // 0 stocks: no second-engine card exists, `brandCount` counts none
            // of them and the shelf is exactly the first engine's.
            fotuIds.clear();
            fotuNames.clear();
            fotuKinds.clear();
            fotuStocks.clear();
            try { DebugSink.textNow("fotufilm", "second engine unavailable: " + t); }
            catch (Throwable ignored) { }
        }
    }

    private static void readStocks(org.json.JSONArray array, List<String> ids, List<String> labels,
                                   List<String> types, java.util.Map<String, String> targets) {
        if (array == null) return;
        for (int i = 0; i < array.length(); i++) {
            org.json.JSONObject o = array.optJSONObject(i);
            if (o == null) continue;
            String id = o.optString("id");
            if (id.isEmpty()) continue;
            String name = o.optString("name", id);
            StringBuilder label = new StringBuilder(name);
            String type = o.optString("type", "");
            String use = o.optString("use", "");
            if ("positive".equals(type)) label.append(" · 反转");
            // A silver stock is a `negative` in this catalogue like any other,
            // so without this the four black-and-white films wear "· 负片"
            // and nothing says which ones they are. "Black and white" is the
            // only label a user looks for them by.
            else if (isMonochromeStock(id)) label.append(" · 黑白");
            else if ("negative".equals(type)) label.append(" · 负片");
            if ("cine".equals(use)) label.append(" · 电影");
            ids.add(id);
            labels.add(label.toString());
            if (types != null) types.add(type);
            if (targets != null) {
                final String target = o.optString("targetPrint", "");
                if (!target.isEmpty()) targets.put(id, target);
            }
        }
    }

    private int getStatusBarHeight() {
        int result = 0;
        int resourceId = getResources().getIdentifier("status_bar_height", "dimen", "android");
        if (resourceId > 0) result = getResources().getDimensionPixelSize(resourceId);
        return result;
    }

    /**
     * Tap: the gallery, which is where phone photos and JPEGs are.
     *
     * Three intents, in the order the user expects them, and the first one this
     * ROM can actually resolve wins: the system Photo Picker (13+), then
     * `GET_CONTENT image/*` (every Android before 13), then the document
     * picker (every Android, period).
     *
     * The chain is not belt-and-braces. A launch that cannot be resolved throws
     * `ActivityNotFoundException`, and an uncaught throw inside a click handler
     * does not show an error -- it kills the process. That is exactly the
     * report "一选导入就自动退回桌面了" on a Honor/HarmonyOS phone: no message,
     * because there was nothing left alive to show one. Those ROMs ship without
     * the AOSP Photo Picker activity (it lives in the MediaProvider module, and
     * an HMS build does not have it) while the `ACTION_PICK_IMAGES` intent
     * still resolves to the chooser's fallback -- so the check has to be at the
     * launch, and it has to have somewhere to go next.
     */
    private void pickImage() {
        java.util.List<Intent> chain = new ArrayList<>();
        if (android.os.Build.VERSION.SDK_INT >= 33) {
            final Intent multi = new Intent(android.provider.MediaStore.ACTION_PICK_IMAGES);
            multi.putExtra(android.provider.MediaStore.EXTRA_PICK_IMAGES_MAX, 50);
            chain.add(multi);
        }
        chain.add(new Intent(Intent.ACTION_GET_CONTENT)
                .addCategory(Intent.CATEGORY_OPENABLE).setType("image/*"));
        if (!launchFirstResolvable(chain, 1)) {
            showInAppToast("本机没有相册选择器；请改用「RAW / JPEG / HEIC」那一项");
        }
    }

    /**
     * Launch the first intent this ROM resolves, and never let the launch itself
     * kill the process. False when none of them is available.
     */
    private boolean launchFirstResolvable(java.util.List<Intent> chain, int requestCode) {
        for (Intent intent : chain) {
            try {
                // **Do not gate on `resolveActivity`.** Android 11's package
                // visibility rules hide every storage picker from an app that
                // has not declared it in `<queries>`, and `resolveActivity`
                // then answers null for the system picker that
                // `startActivityForResult` would have opened. That is
                // "本机没有相册选择器" / "本机没有可用的文件选择器" on a phone whose
                // gallery and file manager are both fine. Launch it; an
                // ActivityNotFoundException falls through to the next
                // candidate, and everything else is caught below.
                //
                // The grant has to be asked for as persistable *before* the
                // picker runs; `onActivityResult` then either keeps it or
                // copies the file. Without this flag there is nothing to take.
                intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION
                        | Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);
                if (requestCode == 1) intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true);
                Probe.log("picker", "try " + intent.getAction());
                startActivityForResult(intent, requestCode);
                Probe.log("picker", "ok " + intent.getAction());
                try { DebugSink.text("picker", "launched " + intent.getAction()); }
                catch (Throwable ignored) { }
                return true;
            } catch (android.content.ActivityNotFoundException missing) {
                // This ROM has no handler for this action; try the next one.
                Probe.log("picker", "missing " + intent.getAction());
                try { DebugSink.text("picker", "unresolvable " + intent.getAction()); }
                catch (Throwable ignored) { }
            } catch (Throwable t) {
                // A provider that vanished between the check and the launch, a
                // SecurityException, or a picker that throws from its own
                // onCreate. Next one.
                try { DebugSink.text("picker", intent.getAction() + " failed: " + t); }
                catch (Throwable ignored) { }
            }
        }
        return false;
    }

    /**
     * Documents, for RAW. Sony's .ARW and several other RAW containers are
     * typed application/octet-stream by the storage layer, so a picker filtered
     * to image/* hides them completely -- which the user reads, correctly, as
     * "this app cannot import RAW". Asking for any file fixes that, but Android
     * then routes to Files rather than Photos, which is why it is its own
     * entry instead of replacing the gallery.
     *
     * **The same entry is the answer for a HEIC that the gallery will not
     * show.** The MIME list below names the HEIF types explicitly as well as
     * `image/*`, because several storage layers do not map `.heic` to an image
     * type at all -- a downloaded one then appears nowhere in a picker filtered
     * to images, which is what "下载后没法导入" describes.
     */
    private void pickRawFile() {
        final String[] types = {
                "image/*",
                "image/heic", "image/heif", "image/x-heic", "image/x-heif", "image/x-cfif",
                "application/octet-stream",
                "image/x-sony-arw", "image/x-canon-cr2", "image/x-canon-cr3",
                "image/x-nikon-nef", "image/x-adobe-dng", "image/x-panasonic-rw2",
                "image/x-panasonic-raw", "image/x-olympus-orf", "image/x-fuji-raf",
                "image/x-pentax-pef", "image/x-samsung-srw", "image/x-sigma-x3f"
        };
        java.util.List<Intent> chain = new ArrayList<>();
        Intent documents = new Intent(Intent.ACTION_OPEN_DOCUMENT);
        documents.addCategory(Intent.CATEGORY_OPENABLE);
        documents.setType("*/*");
        documents.putExtra(Intent.EXTRA_MIME_TYPES, types);
        chain.add(documents);
        Intent content = new Intent(Intent.ACTION_GET_CONTENT);
        content.addCategory(Intent.CATEGORY_OPENABLE);
        content.setType("*/*");
        content.putExtra(Intent.EXTRA_MIME_TYPES, types);
        chain.add(content);
        if (!launchFirstResolvable(chain, 1)) {
            showInAppToast("本机没有可用的文件选择器");
        }
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode != 1) return;
        if (resultCode != RESULT_OK) return;          // the user cancelled
        // RESULT_OK with no URI happens on ROMs whose picker cannot hand back a
        // stream for the item (a cloud-only photo, a broken provider). Doing
        // nothing there is what "下载后没法导入" looks like from the outside: the
        // tap simply has no effect and nothing is said.
        // **A multi-selection arrives as a ClipData**, a single one as `data`.
        // Both are collected here; one URI keeps the old path exactly (and its
        // "copy to our directory" fallback), several go through the queue.
        final java.util.ArrayList<Uri> picked = new java.util.ArrayList<>();
        if (data != null) {
            final android.content.ClipData clip = data.getClipData();
            if (clip != null && clip.getItemCount() > 0) {
                for (int i = 0; i < clip.getItemCount(); ++i) {
                    final Uri u = clip.getItemAt(i).getUri();
                    if (u != null) picked.add(u);
                }
            } else if (data.getData() != null) {
                picked.add(data.getData());
            }
        }
        if (picked.isEmpty()) {
            try { DebugSink.text("picker", "RESULT_OK with no data"); } catch (Throwable ignored) { }
            showInAppToast("没有拿到图片（选择器返回空）。请点「导入」→「从文件管理器选择」再试一次");
            return;
        }
        if (picked.size() == 1) {
            importPicked(picked.get(0));
            return;
        }
        startBatchImport(picked);
    }

    /**
     * Take the picker's grant, or make one of our own.
     *
     * <p>A `content://` URI from a picker is a **grant**, not a path, and the
     * grant is usually for this process only. ColorOS's file manager
     * (`com.android.fileexplorer.provider.FileExplorerFileProvider`) refuses
     * to make it persistable at all, so the restore-from-background path --
     * new in 1.4.0g -- reopened a URI the system no longer honours and
     * surfaced as `SecurityException` under [E-9000]. Copying the bytes into
     * `filesDir/import/` is the only thing that survives a restart no matter
     * which provider the user went through.
     */
    private void importPicked(Uri uri) {
        CrashTrail.mark(this, "import:picked");
        // **A re-pick repairs a chip, it does not import a photograph.**
        // Without this the frame the user chose to re-link was still removed by
        // `loadImage`'s dead-grant branch, and every one of the seventy-four
        // "照片已不可访问" reports ended with the picture -- and its look --
        // gone for good.
        final int repair = repickFrame;
        if (repair >= 0) {
            repickFrame = -1;
            repairFrame(uri, repair);
            return;
        }
        // A pick from ＋ is a new photograph, never a chip coming back.
        reopenToOriginal = false;
        boolean persisted = false;
        try {
            getContentResolver().takePersistableUriPermission(
                    uri, Intent.FLAG_GRANT_READ_URI_PERMISSION);
            persisted = true;
        } catch (Throwable ignored) {
            // The provider declined. Expected for GET_CONTENT and for the
            // ColorOS file manager; not an error the user should see.
        }
        if (persisted) { loadImage(uri); return; }

        showInAppToast("正在把照片复制到应用目录…");
        new Thread(() -> {
            final Uri copy = privateCopy(uri);
            runOnUiThread(() -> {
                if (copy == null) {
                    showErrorDialog("导入失败", "读取或复制这个文件失败了。请换「从相册选择」再试一次。");
                    return;
                }
                loadImage(copy);
            });
        }, "import-copy").start();
    }

    /** A copy of the picked file inside the app's own storage. Null on any
     *  failure; the caller reports it rather than importing a URI that will
     *  not open next time. */
    private Uri privateCopy(Uri src) {
        try {
            final String name = getFileName(src);
            final java.io.File dir = new java.io.File(getFilesDir(), "import");
            if (!dir.isDirectory() && !dir.mkdirs()) return null;
            final java.io.File dst = new java.io.File(dir,
                    System.currentTimeMillis() + "_" + (name == null ? "photo" : name));
            try (InputStream in = getContentResolver().openInputStream(src);
                 java.io.FileOutputStream out = new java.io.FileOutputStream(dst)) {
                if (in == null) return null;
                final byte[] buf = new byte[1 << 16];
                copyStream(in, out, buf);
            }
            try { DebugSink.text("import", "copied " + name + " -> " + dst.getName()
                    + " (" + dst.length() + " bytes)"); } catch (Throwable ignored) { }
            return Uri.fromFile(dst);
        } catch (Throwable t) {
            try { DebugSink.text("import", "copy failed: " + t); } catch (Throwable ignored) { }
            return null;
        }
    }

    /**
     * Point an existing chip at a newly picked copy of the same file.
     *
     * <p>Always copies: taking a fresh grant would fail again the next time the
     * process dies, which is exactly what the user just lived through. The chip
     * keeps its position, its name and its look.
     */
    private void repairFrame(Uri uri, int index) {
        showInAppToast("正在把照片复制到应用目录…");
        new Thread(() -> {
            final Uri copy = privateCopy(uri);
            runOnUiThread(() -> {
                if (copy == null) {
                    showErrorDialog("导入失败", "读取或复制这个文件失败了。请换「从相册选择」再试一次。");
                    return;
                }
                if (index < 0 || index >= frames.size()) return;
                final Frame f = frames.get(index);
                f.uri = copy;
                final String n = getFileName(copy);
                if (n != null) f.name = n;
                currentFrame = index;
                rebuildFrameChips();
                try { DebugSink.text("import", "repaired frame " + index + " -> " + copy); }
                catch (Throwable ignored) { }
                reopenToOriginal = f.original;
                loadImage(copy, index);
            });
        }, "import-repair").start();
    }

    /** Can this URI still be opened? A restored frame's grant may be gone. */
    private boolean canReadUri(Uri uri) {
        if (uri == null) return false;
        try (InputStream in = getContentResolver().openInputStream(uri)) {
            return in != null;
        } catch (Throwable t) {
            return false;
        }
    }

    /**
     * Lift a bitmap into the engine's float buffer, a band of rows at a time.
     *
     * <p>The loop this replaces asked for one row per `getPixels` and one row
     * per JNI call -- 16,320 of each on a 200 MP import, all of it on the UI
     * thread. That is the ANR the release survey caught: `import:decoded
     * 12288x16320`, then five seconds of nothing (SL-261121-C907). Both calls
     * take a height and a count, so a band is one call each and the bytes land
     * in the same place -- `getPixels` is row-major with `stride == width`, and
     * `nativeFillRow` writes `count` contiguous pixels from `pixelOffset`.
     *
     * <p>64 rows keeps the scratch at 3 MB for a 12,288-wide frame; larger
     * bands buy nothing because the cost is `getPixels` itself.
     */
    private static void liftRows(Bitmap from, long dst, int w, int h) {
        if (from == null || dst == 0 || w <= 0 || h <= 0) return;
        final int band = Math.max(1, Math.min(h, 64));
        final int[] scratch = new int[w * band];
        for (int y = 0; y < h; y += band) {
            final int n = Math.min(band, h - y);
            from.getPixels(scratch, 0, w, 0, y, w, n);
            SpektraLabEngine.fillRow(dst, (long) y * w, scratch, w * n);
        }
    }

    private void loadImage(Uri uri) {
        loadImage(uri, -1);
    }

    /**
     * @param reopenIndex the chip this load belongs to, or -1 for a new
     *        photograph.
     *
     * <p>**It travels as an argument because it used to be a field.** A decode
     * takes seconds, and `reopeningFrame` was a single flag shared by every
     * load in flight; the first one to finish consumed it and the next read
     * "false" and appended a *second* chip for a picture that already had one.
     * Reported as "本来导了三张，现在分别点进去之后变成四张，位置也不一样"
     * (SL-261111-D598: `frames=11 -> 12`, `current=7 -> 11`, two threads
     * decoding the same RAF).
     */
    private void loadImage(Uri uri, int reopenIndex) {
        CrashTrail.mark(this, "import:load " + uri);
        // **The plate waits for the decode, not for the picker.** It used to go
        // up here, before the two questions this method can ask -- the size
        // sheet and "this file will not open" -- and both of those `return`.
        // Nothing took the plate down, so the wave sat over a canvas with no
        // photograph and the 选择照片 card underneath it: "导入选项不显示",
        // reported with a 59 MP re-import of one of our own exports
        // (SL-261118-F773). A RAW raises its own, in `loadRawImage`.
        // A render of the previous photograph must not land on this one, and
        // the file path of the previous photograph is not this one's.
        fotuSourcePath = null;
        fotuSourcePathFor = null;
        fotuSourceDead = null;
        fotuGeneration++;
        // Whatever is rendering belongs to the photograph being replaced.
        renderEpoch++;
        // **The previous photograph's dimensions are not this one's.**
        // `originalAspect()` prefers `importedWidth` when it is set, and only
        // the RAW path ever set it. So a RAW followed by a JPEG kept the RAW's
        // shape: on a 6912x4530 raw then a 1280x1708 jpeg, `refreshEdgeFormats`
        // logged `aspect=1.5258` for the *portrait* frame it had just imported,
        // picked the 135 gate, and the render then refused it with
        // "a 1280 x 1708 frame is not the 135 gate's shape" -- E-1305.
        importedWidth = 0;
        importedHeight = 0;
        // A profile belongs to one file. The RAW branch below attaches this
        // frame's; a JPEG has none, and the canvas falls back to plain sRGB.
        sourceToneCurve = null;
        // **The previous frame's gate is not this frame's shape.** A 6x17 chosen
        // for a panorama stayed selected for the next picture, and the render
        // then refused a 1365x1024 frame with "is not the 120_6x17 gate's
        // shape". `refreshEdgeFormats` re-picks from the new aspect a few lines
        // later, so this only clears the stale choice.
        overscanFormat = "135";
        // **The one number that separates the two hypotheses.** A death inside
        // the decode leaves nothing but `import:load` behind, and at that point
        // "this file is corrupt" and "this file is 50 MP and the kernel
        // reclaimed us" look identical. The header costs a few milliseconds and
        // answers it before anything large is allocated.
        try {
            final int[] sz = sniffImageSize(uri);
            final long want = sz == null ? 0L : (long) sz[0] * sz[1] * 12L;
            CrashTrail.mark(this, "import:size "
                    + (sz == null ? "unknown" : sz[0] + "x" + sz[1])
                    + " need=" + (want >> 20) + "MB"
                    + " avail=" + (availableMemoryBytes() >> 20) + "MB");
            try { DebugSink.text("import-size", (sz == null ? "unknown" : sz[0] + "x" + sz[1])
                    + " need=" + (want >> 20) + "MB avail=" + (availableMemoryBytes() >> 20) + "MB"
                    + " native=" + importAtNativeSize); } catch (Throwable ignored) { }
        } catch (Throwable ignored) { }
        // A new photograph starts at the two entry cards, never on a page
        // whose switch belonged to the frame before it.
        CrashTrail.mark(this, "import:page");
        if (edgePageIndex >= 0) openEdgePage(-1);
        // A frame the strip remembers but the system will not open any more:
        // say so in one sentence instead of letting a SecurityException be
        // classified as [E-9000] 未归类.
        if (!canReadUri(uri)) {
            // **A revoked grant is permanent, so the chip goes with it.**
            // Keeping it meant this dialog on every launch -- sixty-six of them
            // in a week, the largest single error in the database -- and the
            // only way out was 「关闭」, which changed nothing. Removed once,
            // here, and the strip is honest afterwards.
            final int dead = currentFrame;
            final boolean ownsIt = dead >= 0 && dead < frames.size()
                    && frames.get(dead).uri.equals(uri);
            if (ownsIt) {
                // **The chip stays, and the way out is one tap.** Removing it
                // on the spot threw away the look with the grant: the file is
                // still on the phone, it is the *permission* that expired.
                showActionSheet("照片已不可访问",
                        "系统收回了文件选择器给的临时授权，这张照片现在读不到了。\n\n"
                        + "「重新选择这个文件」会把它复制到应用自己的目录——胶片、构图、片边和日期都会保留；"
                        + "「从照片栏移除」只去掉这一条，文件本身不动。",
                        new String[]{"重新选择这个文件", "从照片栏移除", "取消"}, which -> {
                            if (which == 0) { repickFrame = dead; pickRawFile(); }
                            else if (which == 1) removeFrame(dead);
                        });
            } else {
                showErrorDialog("照片已不可访问",
                        "这张照片的读取权限已经失效——系统收回了文件选择器给的临时授权。\n\n"
                        + "点「导入」重新选择这张照片；新版本会把文件复制到应用自己的目录，"
                        + "之后切到别的软件回来也不会丢。");
            }
            return;
        }
        CrashTrail.mark(this, "import:canread");
        sourceUri = uri;
        // A different file means a different sensor balance; the previous
        // frame's gains must not be handed to it.
        wbUserMul = null;
        // The frame's own look, stated before any session is built: a chip
        // returns to a photograph *and* to what was done to it; a pick from ＋
        // starts with no film at all.
        // **The frame on screen keeps what was done to it.** An import does
        // not go through `reopenFrame`, which is the only other place that
        // folds the editor's fields back into its Frame -- so the last edits
        // made before a ＋ lived only in memory until the 1.2 s debounce, and
        // a kill in that window lost them.
        if (reopenIndex != currentFrame) saveLookIntoFrames();
        if (reopenIndex >= 0 && reopenIndex < frames.size()) {
            applyLook(frames.get(reopenIndex).look);
        } else {
            // **A reopen with no frame to reopen is a new photograph.** This
            // used to leave the global fields untouched when the index was
            // gone (every chip deleted, then ＋), so the new frame inherited
            // the previous one's print exposure and meter switch -- reported
            // as "重新导入一张还是黑灰", gone after a restart for the obvious
            // reason.
            applyLook(defaultLook());
        }
        if (reopenIndex < 0) {
            // **Belt to `applyLook`'s braces.** `defaultLook()` already says
            // 「no border」, but one abandoned assignment anywhere in that
            // method (it writes fifty fields between here and the border, and
            // most of them repaint panels) is enough to carry the deleted
            // picture's card onto this one. A fresh import is the one moment
            // where the answer is known without asking anything.
            frameTemplate = "";
            pfKind = "none";
            overscanOn = false;
            overscanPair = false;
            lastFotuPlain = null;
            FrameTemplate.forget();
        }
        CrashTrail.mark(this, "import:look");
        try {
            // Check if this is a RAW file by extension
            String fileName = getFileName(uri);
            CrashTrail.markNow(this, "import:name " + fileName);
            final String lower = fileName == null ? "" : fileName.toLowerCase();
            isRawFile = lower.endsWith(".rw2") || lower.endsWith(".raw")
                    || lower.endsWith(".dng") || lower.endsWith(".arw")
                    || lower.endsWith(".nef") || lower.endsWith(".cr2")
                    || lower.endsWith(".cr3") || lower.endsWith(".orf")
                    || lower.endsWith(".raf") || lower.endsWith(".pef")
                    || lower.endsWith(".srw") || lower.endsWith(".x3f")
                    || lower.endsWith(".rwl") || lower.endsWith(".3fr")
                    || lower.endsWith(".mrw") || lower.endsWith(".erf");
            // A RAW container we know of but cannot open still beats decoding
            // its bytes as a JPEG and reporting a mystery.
            final String[] knownButUnsupported = {".heic.raw", ".iiq", ".mos"};
            for (String ext : knownButUnsupported) {
                if (lower.endsWith(ext)) {
                    hideBusy();
                    try { DebugSink.text("import-skip", "extension " + ext + " " + uri); }
                    catch (Throwable ignored) { }
                    showInAppToast("[E-1107] 暂不支持 " + ext + " 格式");
                    return;
                }
            }
            
            if (isRawFile) {
                loadRawImage(uri, reopenIndex);
                return;
            }

            // **Ask before shrinking.** Importing at the negative's own size is
            // the point of a 45 MP camera; a silent downscale is the app making
            // that decision on the user's behalf, and it shows up later as an
            // export that is smaller than the file. The header gives the size
            // without decoding anything, so the question is free.
            // **Ask before shrinking.** The header gives the size without
            // decoding anything, so the question is free -- and the answer
            // belongs to the user, not to a memory estimate.
            if (!importAtNativeSize && !importBudgetAccepted && !suppressBudgetDialog) {
                final int[] full = sniffImageSize(uri);
                if (full != null) {
                    final long area = (long) full[0] * (long) full[1];
                    final int cap = maxImportPixels();
                    if (area > cap || Math.max(full[0], full[1]) > IMPORT_LONG_EDGE) {
                        // A question is not an import: whatever was on the canvas
                        // stays, and no plate is left behind.
                        hideBusy();
                        // The canvas keeps the previous picture, which is the
                        // right thing for a question -- but only if this line
                        // says it was a question. Without it the trail read
                        // "import:name" and then nothing, and 「当前的图片不
                        // 加载」 had no evidence at all.
                        try { DebugSink.text("import-skip", "budget " + full[0] + "x" + full[1]
                                + " cap " + cap + " " + uri); } catch (Throwable ignored) { }
                        showImportBudgetDialog(uri, full[0], full[1], cap, reopenIndex);
                        return;
                    }
                }
            }
            importBudgetAccepted = false;

            // Retire the shelf queue *before* the session it is holding goes
            // away. Its generation is the only thing that makes a card which
            // is already rendering drop its bitmap instead of filing the old
            // photograph's picture under this photograph's films: without this
            // bump the queue wrote last frame's thumbnails into `filmThumbs`,
            // every card then looked right in the map (`containsKey`), and the
            // new queue skipped them forever -- cards showing the previous
            // photo until each one was tapped.
            stopPrefetch();
            // Free the previous frame before decoding: a 20 MP pick wants a
            // ~200 MB direct buffer and the old session still holds its planes
            // (this OOM was 241 MB with 201 MB left in the heap).
            //
            // **Under the render lock.** `stopPrefetch` only bumps a generation
            // -- it does not wait for the thread, which may be inside
            // `renderBegin` on this very session. Closing it from under the GPU
            // is the SIGSEGV this device logs as `vkCmdCopyBuffer` against a
            // destroyed buffer, and it is what tapping an earlier thumbnail
            // while the shelf was still drawing looked like.
            synchronized (renderMutex) {
                if (session != null) { session.close(); session = null; }
            }
            // **The old frame's planes go before the new one asks for its own.**
            // `spk_open` allocates the decoded source while the previous
            // session's pool is still resident. On a 16 GB phone a 32 MP pool
            // plus a 50 MP frame is more than the app's cgroup will hand out,
            // and it surfaces as `cannot allocate Vulkan result pixels` ->
            // E-1003 even though the frame alone would have fit. The export
            // path already trims for exactly this reason.
            try { if (engine != null) engine.trimPool(); } catch (Throwable ignored) { }
            lastRenderedBitmap = null;
            refreshPanelLocks();
            // The plate on the canvas belongs to the frame we just left.
            clearBusyPlate();
            dateText = null;
            setStage(0, null);
            // The white-balance half is RAW-only; tell it which file this is.
            refreshViewPanel();
            sourceBitmap = null;
            // `allocDirect` has no cleaner: dropping the field frees nothing.
            if (sourcePixels != 0) { SpektraLabEngine.freePixels(sourcePixels); sourcePixels = 0; }
            sourcePixelsW = sourcePixelsH = 0;
            // The previous file's unpacked plane is not this frame's problem.
            try { SpektraLabEngine.clearRawCache(); } catch (Throwable ignored) { }
            clearShelfCache();
            // **Retire the previous photograph's fotufilm pass.** Its completion
            // tests `fotuGeneration`, so a bump is what stops a develop that is
            // still inside the kernels from painting the old picture over this
            // one (`epoch` in `renderFotu` is the second lock on the same door).
            // `lastFotuPlain` is dropped so a border recompose cannot redraw it
            // either -- both bitmaps are ordinary managed memory, so dropping the
            // reference is the free.
            ++fotuGeneration;
            fotuPending = false;
            lastFotuPlain = null;
            // **A new photograph gets a new budget.** Six self-healing passes
            // is a lot per photo, and they are spent by the user's own renders
            // cutting a pass short -- carrying that debt into the next import
            // left its cards spinning with no retry left.
            prefetchRetries = 0;
            // The canvas is not a control. `setOriginalVisual` only paints the
            // 原图 button; what CompareView holds is `after` (the last render)
            // and it survives a new session. That was the whole "I changed the
            // photo and the canvas still shows the old one" report: the frame
            // was never dropped, so the next render was the first thing to
            // replace it.
            if (compare != null) compare.clear();
            System.gc();

            // Cap by area, the way the RAW path does. inSampleSize only halves,
            // so one exact scale follows if the sample still overshoots.
            final boolean nativeSize = importAtNativeSize;
            importAtNativeSize = false;                       // one import only
            // **「按原图」 is about the export, not about what the engine
            // holds.** It used to lift every ceiling here, so a 200 MP file
            // opened a 200 MP session: 12 B/px of float is 2.4 GB, beside an
            // 800 MB ARGB bitmap, for a canvas that renders at 2048 and a
            // negative cache that holds the frame again. That is the 4.9-6.5 GB
            // low-memory kills in 1.7.0's first four hours, and a five-second
            // main-thread stall on the way in.
            //
            // The session now takes the device's own budget, and
            // `exportAtNative` sends the export back to the file for its real
            // size -- `exportImage` already re-decodes and opens a fresh
            // session for exactly that (the `bigger` branch). Same promise,
            // a tenth of the frame.
            exportAtNative = nativeSize;
            // A cap the last render failure handed us (see offerSmallerImport):
            // one import's worth, then back to the device's own answer.
            final int forcedCap = pendingCapPixels;
            pendingCapPixels = 0;
            e1001Offered = false;
            // An explicit "render smaller" from the failure sheet outranks the
            // native default: the user asked for that one.
            final int capPixels = forcedCap > 0 ? forcedCap : maxImportPixels();
            final int edgeCap = IMPORT_LONG_EDGE;
            // The cleanup above (shelf queue, session close, gc) is its own
            // stretch; without this mark a death there would still be reported
            // as `import:look` and blamed on the decoder.
            showBusy("READING");
            CrashTrail.mark(this, "import:decoding");
            sourceBitmap = decodeImport(uri, capPixels, edgeCap);
            if (sourceBitmap == null) {
                // The old message here was "无法解码图片", which gave the user
                // nothing to act on. A HEIC/HEIF this phone's decoder refuses is
                // the common case, so the dialog carries the way out instead of
                // describing it.
                showActionSheet("[E-1107] 这张图本机解不开",
                        "多半是 HEIC/HEIF 或 10-bit 的图（三星、iPhone 默认存这种）。\n"
                                + "换「从文件选择」再试一次，读不到的话请先另存为 JPEG。",
                        new String[]{"从文件选择", "取消"}, which -> {
                            if (which == 0) pickRawFile();
                        });
                // The decode ran and gave nothing back; the plate does not owe
                // the user a reason to stare at it.
                hideBusy();
                return;
            }
            sourceBitmap = applyExifRotation(uri, sourceBitmap);
            // **Where the import actually is.** `import:load` covers everything
            // from the pick to the session, which is a fifty-line stretch with
            // a 200 MB bitmap and a 600 MB direct buffer in it; when the system
            // reclaims the process mid-way the trail cannot tell a bad file
            // from a decoder that handed back 50 MP it could not then convert.
            CrashTrail.mark(this, "import:decoded " + sourceBitmap.getWidth() + "x"
                    + sourceBitmap.getHeight());
            final long area = (long) sourceBitmap.getWidth() * sourceBitmap.getHeight();
            final int longEdge = Math.max(sourceBitmap.getWidth(), sourceBitmap.getHeight());
            // Three ceilings in three units, and the strictest wins: area is
            // quadratic in the scale, the long edge is linear, and the third is
            // what this phone can actually hold -- the import's float buffer is
            // 12 B/px, which is 240 MB at 20 MP and the largest single
            // allocation the app makes. Asking before taking it is what turns
            // an OutOfMemoryError (an Error, so the old `catch (Exception)`
            // never saw it and the process died) into a smaller import.
            double k = 1.0;
            // **Nothing is scaled when the user asked for the original.** The
            // memory test below used to run even with `nativeSize`, so "force
            // original" still came back smaller -- the one place where the
            // suggestion was a ceiling in disguise.
            final long availBytes = availableMemoryBytes();
            if (!nativeSize) {
                if (area > capPixels) k = Math.min(k, Math.sqrt((double) capPixels / (double) area));
                if (longEdge > edgeCap) k = Math.min(k, (double) edgeCap / longEdge);
                // **No third ceiling from free RAM.** `capPixels` already came
                // from the pixel budget, and that budget is now derived from
                // total RAM rather than whatever happened to be free. Applying
                // `availMem - 128 MB` *again*, here, is what made two imports of
                // one file land on different sizes. The float buffer is malloc'd
                // and its failure has an honest message (`导入这张图需要 N MB`),
                // so the guess is not needed.
            }
            if (k < 1.0) {
                final int nw = Math.max(1, (int) Math.round(sourceBitmap.getWidth() * k));
                final int nh = Math.max(1, (int) Math.round(sourceBitmap.getHeight() * k));
                Bitmap scaled = Bitmap.createScaledBitmap(sourceBitmap, nw, nh, true);
                if (scaled != sourceBitmap) sourceBitmap.recycle();
                sourceBitmap = scaled;
                try { DebugSink.text("import-scale", "k=" + k + " -> " + nw + "x" + nh
                        + " avail=" + availBytes); } catch (Throwable ignored) { }
            }
            sourceWidth = sourceBitmap.getWidth();
            sourceHeight = sourceBitmap.getHeight();
            // The JPEG path sets these too, so nothing has to infer a shape from
            // whatever the last raw happened to be.
            importedWidth = sourceWidth;
            importedHeight = sourceHeight;
            refreshEdgeFormats();

            // Convert a row at a time: a full int[] of 20 MP would be another
            // 80 MB on the Java heap next to the direct buffer.
            rawFilePath = null;
            // 12 bytes a pixel, outside the Java heap, and the largest single
            // allocation this app makes: 240 MB at 20 MP, 600 MB at 50. The
            // engine takes float32 only (the Metal zero-copy door is refused by
            // the Vulkan backend), so it cannot be made smaller -- but it can be
            // made *legible*: an OutOfMemoryError here is caught and explained,
            // and only a kernel reclaim leaves the trail without this mark.
            final long pixelBytes = (long) sourceWidth * sourceHeight * 3L * 4L;
            CrashTrail.mark(this, "import:pixels " + (pixelBytes >> 20) + "MB avail="
                    + (availableMemoryBytes() >> 20) + "MB");
            try { DebugSink.text("import-pixels", sourceWidth + "x" + sourceHeight
                    + " need=" + (pixelBytes >> 20) + "MB avail="
                    + (availableMemoryBytes() >> 20) + "MB"); } catch (Throwable ignored) { }
            // **malloc, not allocateDirect.** The runtime caps direct-buffer
            // memory at the heap growth limit (512 MB on the phone that
            // reported this), and a 50 MP frame is 576 MB of float32, so the
            // old call was refused with 4.3 GB free -- and the message blamed
            // the device. This one asks for memory that exists.
            try {
                sourcePixels = SpektraLabEngine.allocPixels(pixelBytes);
            } catch (Throwable oom) {
                throw new IllegalStateException("导入这张图需要 " + (pixelBytes >> 20)
                        + " MB 内存，本机现在给不出来（可用 "
                        + (availableMemoryBytes() >> 20) + " MB）。"
                        + "\n\n点「导入」再选一次，这次选「缩到建议尺寸」。", oom);
            }
            // **A band a call, not a row a call.** One row per `getPixels` and
            // per JNI call was 16,320 of each on a 200 MP import, on the UI
            // thread: the five-second freeze behind SL-261121-C907.
            // **这块暂存是给这个尺寸的。** 引擎只会照着宽高去读，所以尺寸要
            // 跟着缓冲一起记（RAW 导入会把 `sourceWidth/Height` 换成解码器的
            // 尺寸，而那份暂存不是）。
            sourcePixelsW = sourceWidth;
            sourcePixelsH = sourceHeight;
            liftRows(sourceBitmap, sourcePixels, sourceWidth, sourceHeight);
            
            final int pw = Math.max(1, Math.round(sourceWidth * Math.min(1f, 1024f / Math.max(sourceWidth, sourceHeight))));
            final int ph = Math.max(1, Math.round(sourceHeight * Math.min(1f, 1024f / Math.max(sourceWidth, sourceHeight))));
            // **`createScaledBitmap` hands back the source itself when the
            // target size already matches**, and a bitmap straight out of
            // `BitmapFactory` is immutable, so that is the branch every picture
            // whose long edge is at most 1024 takes. The recycle below then left
            // `compare` holding a dead bitmap: the next draw threw
            // "Canvas: trying to use a recycled bitmap", and because the same
            // picture is re-imported by `restoreSessionState` the app died on
            // every launch until its data was cleared.
            Bitmap preview = Bitmap.createScaledBitmap(sourceBitmap, pw, ph, true);
            if (preview == sourceBitmap) {
                preview = sourceBitmap.copy(Bitmap.Config.ARGB_8888, false);
                if (preview == null) preview = sourceBitmap;
            }
            beforeBitmap = preview;
            compare.setBefore(beforeBitmap);
            if (sourceBitmap != beforeBitmap) sourceBitmap.recycle();
            sourceBitmap = null;
            statusText.setText("Local preview");
            setStage(1, getFileName(uri));
            // **Before `rememberFrame`, while we still know which file it is.**
            // The canvas only ever sees the still; if the clip is not taken now
            // it is gone, and the export silently writes a plain JPEG over a
            // live photo -- which is exactly what every version before this one
            // did.
            final LiveClip live = captureLiveClip(uri);
            rememberFrame(uri, reopenIndex);
            if (live != null && currentFrame >= 0 && currentFrame < frames.size()) {
                final Frame f = frames.get(currentFrame);
                f.liveClip = live.path;
                f.liveTsUs = live.tsUs;
                saveSessionState();
            }
            rebuildFilmCards();
            setStep(1);
            
            // Create engine and session
            CrashTrail.mark(this, "import:engine");
            ensureEngine();
            CrashTrail.mark(this, "import:engine-ok");
            synchronized (renderMutex) {
                if (session != null) { session.close(); session = null; }
            }
            session = engine.openSession(sourcePixels, sourceWidth, sourceHeight, 3, pixelBytes);
            CrashTrail.mark(this, "import:session");
            applySessionParams();
            // **The engine has its own copy; this one is 12 B/px of dead
            // weight.** 432 MB at 36 MP, held for the whole life of the
            // session, and the only reader left was the export's last-resort
            // fallback -- which now re-decodes from the file instead. This is
            // the largest single allocation the app makes and the only one it
            // can give back without touching a pixel; the low-memory killer
            // took the process at 2.7 GB with a 36 MP frame open.
            //
            // Small frames keep it: below 4 MP it is 48 MB, and an export that
            // can no longer read its file still has the buffer that way.
            if (session != null && sourcePixels != 0
                    && (long) sourceWidth * sourceHeight > 4_000_000L) {
                SpektraLabEngine.freePixels(sourcePixels);
                sourcePixels = 0;
                sourcePixelsW = sourcePixelsH = 0;
                CrashTrail.mark(this, "import:staging freed");
            }
            lastImportError = null;
            // An import is not a look. The frame lands unrendered with no film
            // chosen; the first render happens when the user picks a stock.
            showingOriginal = true;
            lastRenderedBitmap = null;
            setOriginalVisual(true);
            // **A new photograph has not chosen an engine.** Only a chip coming
            // back keeps the shelf where it was; a fresh import lands neutral,
            // so the switch never reads as a decision made on the user's behalf.
            if (reopenIndex < 0) {
                shelfEngine = "";
                engineNudge = false;
            }
            refreshEngineSwitch();
            rebuildFilmCards();
            final boolean stayOnOriginal = reopenToOriginal;
            reopenToOriginal = false;
            if (filmStock != null && stayOnOriginal) {
                // **Left on 原图, opens on 原图.** The look is still there -- the
                // film card is what the next tap develops -- but re-rendering
                // here is what made a chip jump back onto a film the user had
                // deliberately stepped off.
                showingOriginal = true;
                setOriginalVisual(true);
                updateFilmSelection();
                statusText.setText("ORIGINAL · RAW 原始数据（未调色，选胶片后才成片）");
                if (!batchExportRunning) startPrefetch();
            } else if (filmStock != null) {
                // A chip came back with a look: develop it again rather than
                // making the user re-pick a film that was never unpicked.
                showingOriginal = false;
                updateFilmSelection();
                // **Not while a batch is exporting.** Each frame is opened only
                // to hand it to `exportImage`, which builds its own full-size
                // session; a preview pass here is a second render of the same
                // frame, and it holds `rendering` up long enough that the next
                // parameter touch answers "渲染中". The batch's order is
                // load -> export, with nothing in between.
                if (!batchExportRunning) renderImage();
            } else {
                statusText.setText("未渲染 · 选择胶片开始" + importSizeNote(sourceWidth, sourceHeight));
                // Nothing is going to render, so the plate leaves here.
                hideBusy();
                if (!batchExportRunning) startPrefetch();
                // **The one lock that happened before this photo existed.** The
                // panel was greyed at launch with no bitmap; without this the
                // 发光 page would stay grey until something else re-ran the pass.
                refreshPanelLocks();
                // 同一个理由的第二件事：现在有画面了，开着的辉光要落到它上面。
                refreshGlowForCurrentView();
            }
            // **The queue gets one more chance, after the UI has settled.** The
            // call above declines while a render still holds `rendering`; this
            // is what turns that into a kick instead of a shelf of loaders.
            uiHandler.postDelayed(this::ensureShelfQueue, 600);
        } catch (Throwable t) {
            hideBusy();
            lastImportError = describeImportFailure(t);
            showErrorDialog("导入失败", lastImportError);
            try { DebugSink.text("import-failed", lastImportError); } catch (Throwable ignored) { }
        }
    }

    /**
     * The long edge accepted without asking.
     *
     * It was 4700, from the days when a dispatch past 16,776,960 threads lost
     * its top rows: the long edge was the only number that kept a 3:2 frame
     * under that wall. The wall is gone (chunked dispatches, and every plane
     * is row-banded now), so the edge no longer has to answer for the area --
     * `maxImportPixels()` does, and it is derived from this device's binding
     * range and the memory the phone has free right now.
     *
     * 8000 is where a frame stops being plausible rather than where it stops
     * working: measured on the SM8735 here, 7500 x 5000 (37.5 MP) renders in
     * 32 s with a 2.7 GB pool, 8000 x 5333 (42.7 MP) in 57 s, and 8192 x 5464
     * (44.8 MP) loses the device inside `spk_iir_df_acc`. A 45 MP camera raw
     * is 8256 x 5504, so this lands it at 8000 x 5333 rather than at 4700.
     */
    // 8736 is a 5DS R at full size, 8660 the 50 MP phone class. The old 8000
    // cut both. This is not a memory limit -- the pixel budget is -- it is the
    // point where a decode stops being a photograph and starts being a pano.
    private static final int IMPORT_LONG_EDGE = 12000;
    /** Used when the profile cannot be read at all. */
    private static final int IMPORT_PIXEL_FALLBACK = 16490040;

    private SpektraLabEngine ensureEngine() throws Exception {
        if (engine == null) {
            vkLogFile().delete();
            // **Before the device exists** -- `vulkan_gpu.cpp` reads this once,
            // when it creates the VkDevice. "0" means off (the engine ignores a
            // zero), and writing it every time keeps a previous run's value from
            // outliving the switch that set it.
            final int simMib = debugStorageLimitMib();
            SpektraLabEngine.setEnv("SPEKTRAFILM_STORAGE_LIMIT",
                    simMib > 0 ? String.valueOf((long) simMib * 1024L * 1024L) : "0");
            // The canvas ceiling is the engine's own measured number (42 MP).
            // A tester who has lifted the frame's ceiling needs it lifted too,
            // or the rebate refuses a 51 MP frame for a reason that no longer
            // applies: the canvas bands now. Twice the frame cap, because a
            // rebate canvas is at most ~1.6x the frame.
            // **Striped film chain, on by default.** Measured on a 16.7 MP
            // frame: peak device memory 1354.5 -> 1163.8 MiB (6.8 -> 5.8 whole
            // planes) and 13088 -> 12378 ms, with the output bit-identical
            // (`6a19bb88851e5304` both ways). It is the only lever that has
            // moved the peak at all; the pool trim and its keep budget did not
            // (1144 MiB at best, 1.7%).
            SpektraLabEngine.setEnv("SPK_BAND_ROWS", "512");
            // **The band ceiling, for the seam question only.** A frame wide
            // enough to need 37 bands shows 37 equally spaced lines on one GPU
            // family and none on another; raising this to the device's dispatch
            // wall turns 37 seams into 5. If the lines thin out in proportion,
            // the band boundary is the cause and no picture content is.
            SpektraLabEngine.setEnv("SPK_BAND_CAP",
                    debugBandCap() > 0 ? String.valueOf(debugBandCap()) : "0");
            // **Where a suspended session goes.** `tmpfile()` has no writable
            // home in an Android app process, so without this every suspend is
            // refused and the preview's source -- a whole frame's plane -- stays
            // resident through an export that is already at the ceiling.
            SpektraLabEngine.setEnv("SPK_SCRATCH_DIR", getCacheDir().getAbsolutePath());
            SpektraLabEngine.setEnv("SPK_MAX_CANVAS_PIXELS",
                    debugPixelCapMp() > 0 ? String.valueOf((long) debugPixelCapMp() * 3_000_000L) : "0");
            appliedSimMib = simMib;
            // **The one call that can take the process down before any UI.**
            // `spk_engine_create` builds a VkDevice and uploads every LUT; a
            // driver that refuses it returns null (we report that), but a driver
            // that *faults* leaves nothing at all. Bracketing it is what makes
            // `engine:create` without `engine:created` a diagnosis instead of a
            // mystery.
            CrashTrail.markNow(this, "engine:create sim=" + simMib);
            engine = SpektraLabEngine.create(getResourcesDir(), vkLogFile().getAbsolutePath());
            CrashTrail.markNow(this, "engine:created " + (engine != null));
            // **The probe comes first, and nothing may stop it.** It used to sit
            // after `uploadCapabilities()`, so a throw in any of the uploads left
            // `probe` at its `parse("{}")` default -- `? · 无单缓冲上限` -- and the
            // next call skipped this whole block because `engine` was already
            // set. That is a device reporting 128 MiB letting a 14.8 MP frame
            // in, and the render dying on a binding range.
            // **The second call that has no Java frame in it.** `deviceProfile`
            // is a JNI round trip into `vkGetPhysicalDeviceProperties2`; a
            // driver that faults there leaves a trail that ends at
            // `engine:profile-in` with no `profile-out`, which is a diagnosis
            // rather than the silence that `engine:created true` followed by
            // nothing used to be.
            CrashTrail.markNow(this, "engine:profile-in");
            final String profileJson = engine.deviceProfile();
            CrashTrail.markNow(this, "engine:profile-out " + (profileJson == null ? 0 : profileJson.length()));
            probe = DeviceProbe.parse(profileJson);
            rememberDevice();
            CrashTrail.markNow(this, "engine:probe " + (probe != null && probe.valid));
            try { DebugSink.text("device-profile", probe.describe() + "\n" + engine.deviceProfile()); }
            catch (Throwable ignored) { }
            // A simulated limit is a claim about a device this one is not, so
            // the canary -- which measures the *real* driver and would raise the
            // range back to 2 GiB -- is not run against it.
            if (simMib == 0) startCanaryProbe();
            try { uploadCapabilities(); } catch (Throwable ignored) { }
            CrashTrail.markNow(this, "engine:ready");
        }
        return engine;
    }

    /**
     * Pixels this device will actually render.
     *
     * Every kernel binds a whole plane, a plane is 12 bytes per pixel, and a
     * binding may not exceed the GPU's maxStorageBufferRange: 128 MiB holds
     * 11 MP, 256 MiB holds 22 MP. Importing past that does not degrade, it
     * fails -- "spk_sep_fir_acc: buffer exceeds maxStorageBufferRange" -- which
     * is what a 50 MP DNG did on a phone reporting 128 MiB. Ask the device
     * rather than guess a long edge, and keep the old workgroup cap.
     */
    /** Total physical RAM. Stable across imports; `availMem` is not. */
    private long totalMemoryBytes() {
        try {
            final android.app.ActivityManager am =
                    (android.app.ActivityManager) getSystemService(ACTIVITY_SERVICE);
            final android.app.ActivityManager.MemoryInfo mi = new android.app.ActivityManager.MemoryInfo();
            am.getMemoryInfo(mi);
            return mi.totalMem;
        } catch (Throwable t) {
            return 0;
        }
    }

    private long availableMemoryBytes() {
        try {
            android.app.ActivityManager am =
                    (android.app.ActivityManager) getSystemService(ACTIVITY_SERVICE);
            android.app.ActivityManager.MemoryInfo mi = new android.app.ActivityManager.MemoryInfo();
            am.getMemoryInfo(mi);
            return mi.availMem;
        } catch (Throwable t) {
            return 0;
        }
    }

    /**
     * Pixels of **source** this device will render, from three ceilings.
     *
     * The binding ceiling comes from the engine itself (`spk_max_plane_bytes`,
     * a direct call) and only falls back to the parsed profile -- because the
     * profile is JSON and the JSON can fail to parse, and a failed parse used to
     * read as "no limit". A device whose driver reports the Vulkan minimum
     * (128 MiB = 11.2 MP) then accepted a 14.8 MP import and died at render.
     *
     * `withRebate` divides by the film canvas's growth: the ceiling applies to
     * the **canvas**, not to the source, and the canvas is wider than the frame
     * by the film's own width and by the margin along it. Measured from the
     * engine's gate table (`overscan.cpp`, kFormats) and confirmed against real
     * renders:
     *
     *     135        1.51   (4700x3133 -> 4914x4538)
     *     135 half   1.53
     *     120 645    1.18   (1952x2604 -> 2116x2833, measured)
     *     120 6x9    1.13
     *     135 XPan   1.50
     *
     * 1.6 covers the worst of them with margin. A frame that lands a little
     * small is a picture; one that lands over the limit is a dead end.
     */
    /**
     * Throw the engine away, build a new one, reload the frame.
     *
     * <p>Some failures are not about the parameters. A session that returns a
     * constant colour twice is holding something that no re-sent JSON reaches:
     * a lost device, a buffer that came back aliased, a driver that gave up.
     * The VkDevice is the one object in this app that can be deleted and
     * rebuilt **without changing a single pixel of the result** -- so when the
     * answer is wrong and the request was right, that is the only remaining
     * move.
     *
     * <p>`ensureEngine` already knows how to make one (it is the same call the
     * first import uses, probe and capabilities included), and `loadImage`
     * already knows how to open a session from the frame's own URI -- so this
     * is "forget everything and do it again", not a second implementation.
     *
     * <p>Runs on the caller's thread and blocks for 1–2 s. Only ever reached
     * after two constant frames in a row, which is not a healthy session and
     * not something that happens on a picture that can be fixed.
     *
     * @return true when a reload was started; false when the engine could not
     *         be rebuilt, in which case the caller shows the frame it has.
     */
    private boolean rebuildEngineAndReload(String why) {
        final int idx = currentFrame;
        try {
            synchronized (renderMutex) {
                try { if (session != null) session.close(); } catch (Throwable ignored) { }
                session = null;
                try { if (engine != null) engine.close(); } catch (Throwable ignored) { }
                engine = null;
                deltaSent.clear();
                deltaSession = null;
            }
            SelfHeal.repaired("engine-rebuild", why);
            ensureEngine();
            if (idx < 0 || idx >= frames.size()) return false;
            // **Not `flatStreak = 0` here.** A reload is not a recovery; if the
            // rebuilt engine also returns a constant, the streak must still be
            // past its retry budgets. It is reset by a render that produces a
            // picture, and by nothing else.
            reopenFrameForced(idx);
            return true;
        } catch (Throwable t) {
            SelfHeal.repaired("engine-rebuild-failed", String.valueOf(t));
            try { DebugSink.text("heal", "rebuild failed: " + t); } catch (Throwable ignored) { }
            return false;
        }
    }

    private int maxImportPixels(boolean withRebate) {
        try { ensureEngine(); } catch (Throwable ignored) { }
        probeNow();
        long byBinding = Long.MAX_VALUE;
        try {
            final int byNative = engine == null ? 0 : engine.maxFramePixels();
            if (byNative > 0) byBinding = byNative;
        } catch (Throwable ignored) { }
        // **No fallback to `probe.maxPixelsByBinding()`.** `maxFramePixels()`
        // answers 0 on purpose -- the renderer bands every pass that would
        // otherwise bind a whole plane -- and falling back here silently put
        // the 8.95 MP ceiling back on every 128 MiB device, which is exactly
        // the number that release claimed to have removed.
        // **Total, not free.** `availMem` moves by gigabytes as other apps come
        // and go, so the same JPEG imported at 42 MP one minute and 36 MP the
        // next -- and the export followed. Total RAM is a property of the
        // phone; the reserve below is what keeps the system off the low-memory
        // killer. If a frame still does not fit, it fails with a message that
        // names the allocation instead of quietly shrinking the import.
        final long byMemory = DeviceProbe.maxPixelsByMemory(
                Math.max(availableMemoryBytes(), (long) (totalMemoryBytes() * 0.45)));
        // **No hard 42 MP ceiling.** It was measured on one 12 GB phone while a
        // canvas plane still had to fit a binding; the banded renderer and a
        // larger device both outgrew it. What is left is memory, and the user
        // gets asked before a frame is shrunk -- see `showImportBudgetDialog`.
        long px = Math.min(byBinding, byMemory);
        // The hidden override (long-press the version in 关于) replaces this
        // suggestion outright: it exists so a tester can name a size neither the
        // driver nor the free-memory estimate would pick.
        final int debugMp = debugPixelCapMp();
        if (debugMp > 0) px = (long) debugMp * 1_000_000L;
        // **A rebate does not shrink the import.** This divided the budget by
        // 1.6 whenever the edge was on, on the theory that the canvas is 1.6x
        // the frame. The canvas has been banded since 1.4.1 (memory peaks at
        // 3.70 GB for a 77 MP canvas, measured three times), and what has to
        // fit in a single binding is the *frame*, not the canvas. The only
        // thing this line did was make the same photograph import smaller
        // because a border was switched on.
        // (kept as a no-op so the call sites stay unchanged)
        return (int) Math.min(Math.max(px, 1_000_000L), Integer.MAX_VALUE);
    }

    private int maxImportPixels() {
        return maxImportPixels(overscanOn);
    }

    /**
     * The decoded frame as a bitmap for the screen.
     *
     * <p>Two things are done to it here and nowhere else: the sRGB encoding a
     * display expects (the frame itself is linear working space -- correct for
     * a file, black on a screen), and `ev` stops of lift, which is the exposure
     * the meter is about to give the film. Without the second the "原图" side of
     * every comparison sits three stops under the developed side and reads as a
     * failure rather than as a starting point.
     */
    /**
     * A frame bitmap in {@link #previewSpace}.
     *
     * <p>Assigning a `ColorSpace` is what makes the system colour-manage the
     * bitmap instead of assuming sRGB: on a P3 phone an untagged P3 buffer is
     * shown as if its numbers were sRGB, which desaturates it by exactly the
     * amount the wider gamut was supposed to add.
     */
    private Bitmap newFrameBitmap(int w, int h) {
        final Bitmap bmp = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888);
        final android.graphics.ColorSpace cs = colorSpaceFor(previewSpace);
        if (cs != null && android.os.Build.VERSION.SDK_INT >= 26) bmp.setColorSpace(cs);
        return bmp;
    }

    private static android.graphics.ColorSpace colorSpaceFor(String name) {
        if (android.os.Build.VERSION.SDK_INT < 26) return null;
        if ("Display P3".equals(name))
            return android.graphics.ColorSpace.get(android.graphics.ColorSpace.Named.DISPLAY_P3);
        return null;          // sRGB is what an untagged ARGB_8888 already is
    }

    private Bitmap exportSourceBitmap(SpektraLabEngine.Session source, double ev) {
        Bitmap bitmap = null;
        // **`g_result` is one process-wide buffer, shared by every entry point
        // that fills it and every one that copies out of it.**
        // `nativeRenderBegin` fills it, `nativeExportSource` overwrites it, and
        // `nativeCopyArgbRange` reads it back -- and this method ran outside
        // `renderMutex`, so a canvas render and this export could interleave.
        // The batch-restore path made it concrete: the render asked for
        // 630x1167, this export replaced the buffer with 800x600, and the copy
        // came back `pixel copy incomplete 480000/735210` -- E-9000 right after
        // "批量导出完成". `synchronized` is re-entrant, so callers that already
        // hold the lock are unaffected.
        synchronized (renderMutex) {
        try {
            // **The gain is computed from *this* frame, so the frame has to
            // exist first.**
            //
            // `nativeSetSourceDisplayEv` does not just scale by 2^ev: it samples
            // the current source into p50 and p99.5, puts the median on 18 % and
            // stops before the 99.5th clips. That sampling reads `g_result`,
            // which `exportSource` is what fills. Setting the EV *before* the
            // export therefore measured the previous frame -- or nothing -- and
            // fell back to the raw `2^ev`, which at the +10.2 EV the meter had
            // produced turned the picture into a white sheet: logged as
            // `raw-view export 2048x1363 ev=10.2 mean=254/254/253`, and reported
            // as "导入照片后整张照片爆掉".
            final int[] d = source.exportSource("live");
            if (d != null && d[0] > 0 && d[1] > 0) {
                // The phone's curve wins over the auto-level switch: it is the
                // vendor's own statement, and it already carries the contrast
                // the auto-level was imitating.
                SpektraLabEngine.setSourceToneCurve(sourceToneCurve);
                SpektraLabEngine.setSourceDisplayEv(ev, rawAutoBright);
                final int rw = d[0], rh = d[1];
                final int[] px = new int[rw * rh];
                if (source.copyArgbRange(px, 0, rh) == rw * rh) {
                    bitmap = Bitmap.createBitmap(rw, rh, Bitmap.Config.ARGB_8888);
                    bitmap.setPixels(px, 0, rw, 0, 0, rw, rh);
                }
            }
            try {
                // **A number for "the colour looks wrong".** Every such report
                // so far has been resolved by comparing the three channel means
                // of this exact bitmap: the 1.5.0e path showed 28/30/42 where a
                // display-encoded frame is 81/86/97, and "dark and violet" is
                // what those numbers look like. Sampling every 97th pixel keeps
                // it off the frame budget.
                String means = "";
                if (bitmap != null) {
                    final int[] sample = new int[bitmap.getWidth() * bitmap.getHeight()];
                    bitmap.getPixels(sample, 0, bitmap.getWidth(), 0, 0,
                            bitmap.getWidth(), bitmap.getHeight());
                    long sr = 0, sg = 0, sb = 0;
                    int n = 0;
                    for (int i = 0; i < sample.length; i += 97) {
                        sr += (sample[i] >> 16) & 0xFF;
                        sg += (sample[i] >> 8) & 0xFF;
                        sb += sample[i] & 0xFF;
                        ++n;
                    }
                    if (n > 0) means = " mean=" + (sr / n) + "/" + (sg / n) + "/" + (sb / n);
                }
                DebugSink.text("raw-view", bitmap == null
                        ? "export: empty ev=" + ev
                        : "export " + bitmap.getWidth() + "x" + bitmap.getHeight()
                          + " ev=" + ev + means);
            } catch (Throwable ignored) { }
        } catch (Throwable t) {
            try { DebugSink.text("raw-view", "export failed: " + t); } catch (Throwable ignored) { }
        } finally {
            try { SpektraLabEngine.setSourceDisplayEv(0, false); } catch (Throwable ignored) { }
            try { SpektraLabEngine.setSourceToneCurve(null); } catch (Throwable ignored) { }
        }
        }
        return bitmap;
    }

    /**
     * Re-reads the original with the current display rule.
     *
     * The canvas is the only thing this touches: `exportSource` hands back the
     * engine's working numbers, and `nativeCopyArgbRange` is what applies the
     * gain and the transfer function. No render, no parameter, no export.
     */
    private void refreshOriginalView() {
        if (!uiReady || session == null) return;
        new Thread(() -> {
            Bitmap b = null;
            synchronized (renderMutex) {
                final SpektraLabEngine.Session s = session;
                if (s != null) b = exportSourceBitmap(s, 0.0);
            }
            if (b == null) return;
            final Bitmap shown = b;
            runOnUiThread(() -> {
                if (!uiReady || compare == null) return;
                // The frame has to be kept even while the developed side is on
                // screen: the switch is a property of the canvas, and flipping
                // it must not leave a stale "before" behind the film.
                beforeBitmap = shown;
                compare.setBefore(shown);
                if (showingOriginal) setStage(1, null);
            });
        }, "raw-view-rule").start();
    }

    private void loadRawImage(Uri uri, int reopenIndex) {
        fotuSourcePath = null;
        fotuSourcePathFor = null;
        fotuSourceDead = null;
        fotuGeneration++;
        // **This decode has a serial number.** A RAW takes three to five seconds, and the strip
        // is right there: tap chip A, tap chip B before A finishes, and A's worker woke up last
        // -- closed B's session, installed A's pixels and drew A under B's chip. That is the
        // "quick taps give the wrong picture / half-drawn canvas" report. `loadImage` bumps the
        // epoch; this worker is the one place that has to honour it.
        final int importEpoch = renderEpoch;
        // Read once, on the UI thread, before the decode starts: the worker
        // below cannot be allowed to see a flag that a later tap already moved.
        final boolean stayOnOriginal = reopenToOriginal;
        reopenToOriginal = false;
        // **A different import is a different frame.** The cache keys on path +
        // mtime, and every import is copied to `files/import/<same name>`; two
        // copies inside one second share an mtime, so the second import could
        // be handed the first one's decoded pixels. Clearing here costs one
        // unpack and buys the guarantee that the pixels belong to this file.
        try { SpektraLabEngine.clearRawCache(); } catch (Throwable ignored) { }
        CrashTrail.mark(this, "import:raw " + uri);
        try {
            String filePath = getFilePathFromUri(uri);
            rawFilePath = filePath;
            // **The phone's own idea of how this raw should look.** OnePlus and
            // OPPO ship a 128/140-point `ProfileToneCurve` plus a
            // `BaselineExposure`; LibRaw parses neither, which is the whole of
            // "our canvas is flat and Lightroom's is not". Read once here, a
            // 6 KB seek, and handed to the canvas only.
            sourceToneCurve = SpektraLabEngine.sourceDisplayProfile(filePath);
            final int curvePts = sourceToneCurve == null ? 0 : (sourceToneCurve.length - 1) / 2;
            DebugSink.text("raw-view", "display profile: "
                    + (sourceToneCurve == null ? "none"
                       : curvePts + " points, baseline "
                         + String.format(java.util.Locale.US, "%.2f", sourceToneCurve[0]) + " EV"));
            // **Which half of the import we got to.** Until now the RAW path
            // filed one mark (`import:raw`) and then nothing until the decode
            // had already finished, so a report of the form "crashed importing
            // a RAW" could not be narrowed past "somewhere in the next four
            // seconds" -- the file copy, `open_file`, the decode, `spk_open`,
            // the meter or the source view. The JPEG path has had these marks
            // for a while; this one had not.
            CrashTrail.markNow(this, "import:path " + (filePath == null ? "(null)" : "ok"));
            if (filePath == null) {
                showInAppToast("无法获取RAW文件路径");
                return;
            }

            // **Ask before the decode.** `open_file` reads the container header
            // in milliseconds; the decode that follows commits 12 bytes per
            // pixel before anyone is consulted, and at 50 MP that is 600 MB. A
            // sheet that appears after that memory is spent is a post-mortem,
            // not a choice.
            if (!suppressBudgetDialog && !importAtNativeSize && pendingCapPixels <= 0) {
                final int[] dims = SpektraLabEngine.rawDimensions(filePath);
                if (dims != null && dims[0] > 0 && dims[1] > 0) {
                    final long area = (long) dims[0] * (long) dims[1];
                    final int cap = maxImportPixels();
                    if (area > cap || Math.max(dims[0], dims[1]) > IMPORT_LONG_EDGE) {
                        statusText.setText("选择导入尺寸");
                        showRawBudgetDialog(uri, dims[0], dims[1], cap, reopenIndex);
                        return;
                    }
                }
            }

            statusText.setText("Decoding RAW…");
            // **The same three things the JPEG path does, for the same three
            // reasons** — and this path had none of them, which is why a RAW
            // import kept the previous photograph everywhere except the little
            // source thumbnail:
            //   · stopPrefetch() retires the shelf queue, whose generation is
            //     what stops last frame's cards being filed under this frame;
            //   · compare.clear() drops `CompareView.after`, the previous
            //     render, which nothing else ever clears;
            //   · filmThumbs.clear() is the shelf's own cache, keyed by film
            //     id with no frame identity in the key.
            stopPrefetch();
            if (compare != null) compare.clear();
            clearShelfCache();
            // Same as the JPEG path: a develop of the previous frame must not
            // land on this one (see `epoch` in `renderFotu`).
            ++fotuGeneration;
            fotuPending = false;
            lastFotuPlain = null;
            lastRenderedBitmap = null;
            refreshPanelLocks();
            // **Not `clearBusyPlate()`.** That emptied the canvas for the
            // decode and left "RAW LOADED" standing there while it worked --
            // the old behaviour the import was asked to stop having.
            dateText = null;
            // **This method raises its own plate.** `loadImage` no longer does:
            // it can return on a size question, and a plate with nothing under
            // it is what "导入选项不显示" was. The decode sets the stage itself
            // as soon as it has a preview; the plate sits on top of that.
            showBusy("READING");
            new Thread(() -> {
                try {
                    // Someone tapped another chip while this file was decoding. The newer import
                    // owns the canvas, the session and the strip: this one must not touch any of
                    // them, or the picture and the selected chip disagree.
                    if (importEpoch != renderEpoch) {
                        CrashTrail.mark(this, "import:superseded " + importEpoch + "/" + renderEpoch);
                        return;
                    }
                    String resourcesDir = getResourcesDir();
                    if (engine == null) {
                        vkLogFile().delete();
                        engine = SpektraLabEngine.create(resourcesDir, vkLogFile().getAbsolutePath());
                        uploadCapabilities();
                    }
                    // Under the render lock: the shelf queue can still be
                    // inside `renderBegin` when this thread gets here, and
                    // closing a session out from under it is a native crash,
                    // not an exception.
                    synchronized (renderMutex) {
                        if (session != null) { session.close(); session = null; }
                    }
                    Probe.log("import", "pre avail=" + Probe.mb(availableMemoryBytes())
                            + " cap=" + maxImportPixels() + " native=" + importAtNativeSize
                            + " pool=" + Probe.pool(engine));
                    Probe.step(this, "import:pre");
                    // **Same trim as the JPEG path.** A 50 MP frame needs
                    // ~76 B/px of planes (3.8 GB); the previous session's pool
                    // is freed here rather than left for the allocator to run
                    // out against.
                    try { if (engine != null) engine.trimPool(); } catch (Throwable ignored) { }
                    Probe.log("import", "trimmed pool=" + Probe.pool(engine));
                    
                    // `film_stock` names a profile file: "" and "null" both make
                    // `load_profile` fail ("bad stock name"), so an unchosen film
                    // omits the key and the engine keeps its own default. The UI
                    // still shows 原图 and renders nothing until a card is tapped.
                    // **Two engines, two id spaces.** A frame developed by the
                    // second engine keeps `fotu:c200` in `filmStock` and a
                    // fotufilm medium in `printStock`. To `spk_open` both read
                    // as profile file names, and neither exists -- so restoring
                    // such a frame died with "bad stock name 'fotu:c200'" before
                    // one pixel was shown, on every launch. This session still
                    // has work to do (it decodes the raw and paints 原图), so it
                    // opens with no film and the default paper; the picture
                    // itself is developed by `renderFotu` through `renderImage`.
                    final boolean fotuFrame = isFotuStock(filmStock);
                    final String spkFilm = fotuFrame ? null : filmStock;
                    // **Never the sentinel.** 无相纸 is a UI idea; `spk_open`
                    // reads this as a file name (SL-261119-938F).
                    final String spkPaper = fotuFrame ? "kodak_portra_endura"
                            : spkPaperForEngine(printStock);
                    final String filmField = spkFilm == null ? ""
                            : String.format(java.util.Locale.US, "\"film_stock\":\"%s\",", spkFilm);
                    // **`Locale.US`, always, for anything that becomes JSON.**
                    // Without it `%.2f` follows the phone's locale: a device set
                    // to German (or any comma-decimal locale) sent
                    // `"print_exposure":1,00`, the engine's parser read `1` and
                    // then wanted a key where the `,` stood, and answered
                    // `params_delta: expected a string at byte 147` -- byte 147
                    // is the first `0` of `00`. Every raw import on such a phone
                    // died with E-1106 (SL-261121-130E).
                    String params = String.format(java.util.Locale.US,
                        "{%s\"print_stock\":\"%s\",\"input_color_space\":\"ProPhoto RGB\",\"input_cctf_decoding\":false,\"output_color_space\":\"sRGB\",\"print_exposure\":%.2f,\"preview_long_edge\":2048}",
                        filmField, spkPaper, printExposure
                    );
                    
                    try { DebugSink.text("open-params", "path=" + filePath + "\n" + params); } catch (Throwable ignored) {}
                    // The cap comes from the device, not from a constant: a
                    // plane is 12 B/px and a binding may not exceed the GPU's
                    // maxStorageBufferRange. Two limits apply, whichever is
                    // lower -- that range, and the 65 535-workgroup dispatch
                    // limit (16,776,960 px) this driver still loses blocks over.
                    final boolean nativeSize = importAtNativeSize;
                    importAtNativeSize = false;                   // one import only
                    // The raw path re-opens at the file's own size for its
                    // export already (`openRawSession(..., 0, 0)`), so a flag
                    // left over from a JPEG import must not reach it.
                    exportAtNative = false;
                    if (nativeSize) {
                        try { DebugSink.text("import-mode", "native size, no cap"); } catch (Throwable ignored) { }
                    }
                    rawFilePath = filePath;
                    importCapPixels = nativeSize ? 0 : maxImportPixels();
                    // **The frame's own balance, if it had one.** A frame
                    // reopened from the strip restores `wbUserMul` through
                    // `applyLook`; without passing it here the reopen decodes
                    // as-shot while the sliders still show the saved Kelvin.
                    final float[] wbMul = wbUserMul;
                    CrashTrail.markNow(this, "import:opening cap=" + importCapPixels);
                    session = wbMul != null
                            ? engine.openRawSessionTuned(filePath, params,
                                    importCapPixels, nativeSize ? 0 : IMPORT_LONG_EDGE, wbMul)
                            : engine.openRawSession(filePath, params,
                                    importCapPixels, nativeSize ? 0 : IMPORT_LONG_EDGE);
                    Probe.log("import", "opened=" + (session != null)
                            + " cap=" + importCapPixels
                            + " edge=" + (nativeSize ? 0 : IMPORT_LONG_EDGE)
                            + " mul=" + Probe.mul(wbMul)
                            + " pool=" + Probe.pool(engine));
                    lastImportError = null;
                    {
                        // The size the engine actually opened, which is not
                        // always the one `rawDimensions` promised: `half_size`
                        // and the budget can both change it.
                        final int[] sd = session == null ? null : session.getDimensions();
                        CrashTrail.markNow(this, "import:opened "
                                + (sd == null || sd.length < 2 ? "none" : sd[0] + "x" + sd[1]));
                    }
                    // **The session's own parameters, which this path never sent.**
                    // `openRawSession` carries the film, the paper and the decode
                    // colour space; it does not carry grain, halation, glare, the
                    // format or the rebate, and those live in `applyParams()`. The
                    // bitmap path has always called this pair; the raw path did
                    // not, so a raw kept the engine's defaults for every optical
                    // control until the user moved a slider -- and a rebate or a
                    // date back chosen before the import never reached the render
                    // at all.
                    applySessionParams();

                    // **Meter before the source view.** `spk_export_source`
                    // materialises the live tier, and a meter taken after it
                    // has come back -11 EV on a frame whose own export read a
                    // perfectly normal mean -- the second RAW opened from a
                    // batch metered black, rendered black, and ignored every
                    // metering mode. Measuring first makes the `solve` below a
                    // cache hit (`meter_key` does not change in between).
                    // **Under the same lock `close()` takes.** These two solves
                    // ran outside `renderMutex`, so a close from another path
                    // could release the session between the null check and the
                    // call -- which is exactly the dangling handle that killed
                    // the process in the meter (SL-261110-F858). The session
                    // field is also re-read inside the lock, so a swap that
                    // lands in between simply skips the solve.
                    try {
                        synchronized (renderMutex) {
                            if (session != null) session.solve("exposure");
                        }
                    } catch (Throwable ignored) { }
                    // **The raw itself**, which is the "before" side of every
                    // comparison and the only honest thing to show on import:
                    // the decoded frame in working space, packed with no
                    // transfer function, so a display reads it the way it reads
                    // a raw -- flat, and dark. The camera's own JPEG is **not**
                    // a stand-in for it: a preview is the camera's rendering,
                    // not this frame, and showing it as "原图" is the same lie
                    // as importing it would be. No frame, no picture.
                    Bitmap rawView = exportSourceBitmap(session, 0.0);
                    final Bitmap preview = rawView;
                    CrashTrail.markNow(this, "import:source " + (preview == null ? "none"
                            : preview.getWidth() + "x" + preview.getHeight()));
                    final boolean hasPreview = preview != null;
                    if (!hasPreview) {
                        // The canvas is not allowed to be blank for no reason.
                        // A session that opened but produced no source frame is
                        // a bug, and it has to say so rather than look like a
                        // photo that failed to load.
                        try { DebugSink.text("raw-view", "no source frame for the canvas"); }
                        catch (Throwable ignored) { }
                        runOnUiThread(() -> statusText.setText("RAW 已载入，原图预览未生成"));
                    }
                    if (hasPreview) {
                        runOnUiThread(() -> {
                            beforeBitmap = preview;
                            compare.setBefore(preview);
                            setStage(1, getFileName(uri));
                            rememberFrame(uri, reopenIndex);
                            rebuildFilmCards();
                            setStep(1);
                            statusText.setText("Raw preview");
                        });
                    }

                    // "Process" (配光): without a solved print exposure and
                    // filter pack the print runs on defaults and blows the
                    // highlights. The mac app makes the user press Process;
                    // this build does it once on open.
                    String solvedJson = null;
                    try {
                        synchronized (renderMutex) {
                            solvedJson = session == null ? null : session.solve("both");
                        }
                        DebugSink.text("solve", solvedJson == null ? "(null)" : solvedJson);
                        CrashTrail.markNow(this, "import:print " + (solvedJson == null ? "none" : "ok"));
                    } catch (Throwable se) {
                        DebugSink.text("solve-failed", String.valueOf(se));
                    }
                    // **The meter's EV, applied to what the screen shows.** The
                    // developed side gets it; leaving the decoded side at 0 EV
                    // is what made a night frame look like a black rectangle
                    // next to a correctly exposed print.
                    if (solvedJson != null) {
                        // The applied value, for the export. See `meteredEv`.
                        try {
                            final org.json.JSONObject root = new org.json.JSONObject(solvedJson);
                            final org.json.JSONObject sp = root.optJSONObject("solved_params");
                            meteredEv = sp == null ? 0.0 : sp.optDouble("exposure_compensation_ev", 0.0);
                            Probe.log("meter", "applied ev=" + meteredEv);
                        } catch (Throwable ignored) { }
                    }
                    if (hasPreview && solvedJson != null) {
                        double solvedEv = 0.0;
                        try {
                            solvedEv = new org.json.JSONObject(solvedJson)
                                    .getJSONObject("exposure_ev_by_method")
                                    .optDouble("balanced", 0.0);
                        } catch (Throwable ignored) { }
                        // **Shown a little under the meter, on purpose.** At the
                        // full metered EV the decoded side reads brighter than
                        // the developed one, and the film's own contrast stops
                        // showing. 85 % is the same exposure a "before" frame is
                        // expected to have.
                        solvedEv *= SOURCE_VIEW_EV_SCALE;
                        if (Math.abs(solvedEv) > 0.02) {
                            final Bitmap lifted = exportSourceBitmap(session, solvedEv);
                            if (lifted != null) {
                                final double shownEv = solvedEv;
                                runOnUiThread(() -> {
                                    beforeBitmap = lifted;
                                    if (compare != null) compare.setBefore(lifted);
                                    if (currentFrame >= 0 && currentFrame < frames.size()) {
                                        final Frame frame = frames.get(currentFrame);
                                        try {
                                            final int tw = Math.max(1, dp(42));
                                            final int th = Math.max(1, Math.round(
                                                    tw * lifted.getHeight() / (float) lifted.getWidth()));
                                            frame.thumb = Bitmap.createScaledBitmap(lifted, tw, th, true);
                                            persistThumb(frame);
                                        } catch (Throwable ignored) { }
                                        rebuildFrameChips();
                                    }
                                    try {
                                        DebugSink.text("raw-view", "display ev=" + shownEv);
                                    } catch (Throwable ignored) { }
                                });
                            }
                        }
                    }
                    runOnUiThread(() -> {
                        if (session == null) return;
                        showingOriginal = true;
                        lastRenderedBitmap = null;
                        setOriginalVisual(true);
                        rebuildFilmCards();
                        if (filmStock == null) statusText.setText("未渲染 · 选择胶片开始");
                        // See the JPEG import: a photo now exists, so the lock
                        // has to be recomputed even when no render follows.
                        refreshPanelLocks();
                        refreshGlowForCurrentView();
                        // **No render from here.** `sourceWidth/Height` are
                        // still the previous frame's and `refreshEdgeFormats`
                        // has not run, so a render now used the old shape and
                        // the old gate: that is E-1305 the moment the user
                        // switches between a landscape and a portrait frame.
                        // The block after `dims` renders once this frame's own
                        // numbers are in.
                    });

                    // Get dimensions from session
                    int[] dims = session == null ? null : session.getDimensions();
                    if (dims == null || dims.length < 2 || dims[0] <= 0 || dims[1] <= 0) {
                        // **A session that will not say how big it is failed
                        // quietly.** Seen while switching back and forth between
                        // two photographs: the previous import's close raced
                        // this one's open, and the handle that came back had no
                        // size. One clean reopen is worth trying before asking
                        // the user to start again -- and if it fails the same
                        // way, that is a decode problem and the message below is
                        // the honest one.
                        try { if (session != null) session.close(); } catch (Throwable ignored) { }
                        session = wbMul != null
                                ? engine.openRawSessionTuned(filePath, params,
                                        importCapPixels, nativeSize ? 0 : IMPORT_LONG_EDGE, wbMul)
                                : engine.openRawSession(filePath, params,
                                        importCapPixels, nativeSize ? 0 : IMPORT_LONG_EDGE);
                        dims = session == null ? null : session.getDimensions();
                    }
                    if (dims == null || dims.length < 2 || dims[0] <= 0 || dims[1] <= 0) {
                        // A zero here used to travel silently: the canvas laid
                        // itself out for nothing, every later size was wrong,
                        // and the reason was never on screen.
                        throw new IllegalStateException(
                                "session reported no size: " + java.util.Arrays.toString(dims));
                    }
                    importedWidth = dims[0];
                    importedHeight = dims[1];
                    int w = dims[0];
                    int h = dims[1];
                    // **这一帧的像素在引擎的解码器里，不在 Java 的暂存里。**
                    // 以前这里只换 `sourceWidth/Height`：先导一张 JPEG、再导
                    // 一张 RAW 之后，那份**小的** JPEG 暂存还挂着，而宽高已经
                    // 是 RAW 的。导出的兜底会 `openSession(sourcePixels,
                    // sourceWidth, sourceHeight)`，引擎便照着大尺寸去读那块小
                    // 内存 —— `upload_data` 里一次 57 MB 的 memcpy 直接撞到未
                    // 映射页，进程当场 SIGSEGV（栈里只有 crash_handler 和
                    // memcpy，Java 一行都看不到）。
                    if (sourcePixels != 0) {
                        // 同一把锁：导出线程可能正拿着这个地址去 `spk_open`。
                        synchronized (renderMutex) {
                            SpektraLabEngine.freePixels(sourcePixels);
                            sourcePixels = 0;
                            sourcePixelsW = sourcePixelsH = 0;
                        }
                        CrashTrail.mark(this, "import:staging dropped (raw)");
                    }
                    sourcePixelsW = sourcePixelsH = 0;
                    sourceWidth = w;
                    sourceHeight = h;
                    try { DebugSink.text("raw-dims", "w=" + w + " h=" + h); } catch (Throwable ignored) {}

                    // **The session's own size, not `rawSourceSize()`.** That
                    // legacy query answers {0,0} on purpose -- its comment says
                    // callers must ask the session -- and reading it put
                    // "RAW 0×0 · 0.0 MP" on the status bar.
                    final boolean capped = importCapPixels > 0;
                    try {
                        DebugSink.text("raw-cap", (capped ? "capped at " + importCapPixels : "native")
                                + " -> session " + w + "x" + h);
                    } catch (Throwable ignored) {}

                    runOnUiThread(() -> {
                        refreshEdgeFormats();
                        setStep(1);
                        // **No sheet.** The raw arrives at the size it was
                        // imported at; the suggestion is a line in the status
                        // bar, not a gate.
                        hideBusy();
                        statusText.setText("RAW " + w + "×" + h
                                + " · " + megapixels(w, h) + " MP"
                                + importSizeNote(w, h));
                        refreshViewPanel();
                        // **Render only now.** The frame's real size and the
                        // gates that fit it are both known, so the render the
                        // chip's Look asks for uses this picture's shape.
                        if (filmStock != null && stayOnOriginal) {
                            showingOriginal = true;
                            setOriginalVisual(true);
                            updateFilmSelection();
                            statusText.setText("ORIGINAL · RAW 原始数据（未调色，选胶片后才成片）");
                            if (!batchExportRunning) startPrefetch();
                        } else if (filmStock != null) {
                            showingOriginal = false;
                            updateFilmSelection();
                            if (!batchExportRunning) renderImage();
                        } else if (!batchExportRunning) {
                            startPrefetch();
                        }
                    });
                } catch (Throwable t) {
                    final String said = describeImportFailure(t);
                    lastImportError = said;
                    // A High-Efficiency NEF is not a preview job. Say what it
                    // is (E-1108, a compression this build has no decoder for)
                    // and what to change, and leave the file alone.
                    runOnUiThread(() -> {
                        statusText.setText("RAW加载失败 " + SpkError.shortForm(said));
                        showErrorDialog("RAW 加载失败", said);
                        // **The plate belongs to whoever raised it.** This path
                        // returned with `showBusy("READING")` still up, so a
                        // failed import left the canvas saying 「加载中」 for
                        // ever -- and deleting the frame did not clear it,
                        // because nothing owned it.
                        hideBusy();
                    });
                }
            }).start();
        } catch (Throwable t) {
            lastImportError = describeImportFailure(t);
            hideBusy();
            showErrorDialog("RAW 加载失败", lastImportError);
        }
    }
    
    /**
     * A failure the user has to be able to read and copy.
     *
     * <p>A Toast is two lines on most phones and ends in an ellipsis, which is
     * exactly how the E-9000 detail disappeared for two releases: the message
     * carried the whole dlopen chain and the screen showed "……so …". This one
     * scrolls, can be selected, and copies itself in one tap -- an error the
     * user cannot forward is an error nobody can fix.
     */
    private void showErrorDialog(String title, String body) {
        showTextDialog(title, body, true);
    }

    /**
     * Shared body for the error dialog and for the answer to "导出最近的步骤".
     *
     * <p>{@code report} decides whether this dialog is itself a diagnostic
     * event: a failure is (once), a confirmation of a report the user just
     * asked for is not.
     */
    private void showTextDialog(String title, String body, boolean report) {
        // **A batch must not stop at the first bad frame.** One dialog per
        // failure would hide the queue behind a stack of sheets; the line is
        // recorded, the queue moves on, and the summary at the end counts it.
        if (batchExportRunning) {
            try { DebugSink.text("batch-error", title + " | " + body); }
            catch (Throwable ignored) { }
            return;
        }
        final String shownTitle = (title == null || title.isEmpty()) ? "错误" : title;
        final String shownBody = (body == null || body.isEmpty()) ? "[E-0000] 未知错误" : body;
        // **One row per failure.** The ring is already in memory; sending it
        // here is what makes an error report readable without the user having
        // to copy anything, and it costs one write instead of sixty-four.
        if (report) reportFailure(shownTitle, shownBody);
        runOnUiThread(() -> {
            final android.app.Dialog dialog = new android.app.Dialog(this);
            LinearLayout card = new LinearLayout(this);
            card.setOrientation(LinearLayout.VERTICAL);
            card.setBackgroundColor(UI_PAPER);
            View cap = new View(this);
            cap.setBackgroundColor(UI_BLUE);
            card.addView(cap, new LinearLayout.LayoutParams(-1, dp(3)));

            LinearLayout head = new LinearLayout(this);
            head.setOrientation(LinearLayout.HORIZONTAL);
            head.setGravity(android.view.Gravity.CENTER_VERTICAL);
            head.setPadding(dp(16), 0, dp(16), 0);
            TextView kicker = mixedLabel("ERROR / 错误详情", 8, UI_BLUE);
            kicker.setLetterSpacing(0.08f);
            head.addView(kicker, new LinearLayout.LayoutParams(0, -2, 1f));
            TextView close = label("关闭", 9, UI_MUTED, tfHan);
            close.setPaintFlags(close.getPaintFlags() | android.graphics.Paint.UNDERLINE_TEXT_FLAG);
            close.setPadding(dp(12), dp(14), 0, dp(14));
            close.setOnClickListener(v -> dialog.dismiss());
            head.addView(close);
            card.addView(head, new LinearLayout.LayoutParams(-1, dp(42)));

            ScrollView scroll = new ScrollView(this);
            LinearLayout bodyBox = new LinearLayout(this);
            bodyBox.setOrientation(LinearLayout.VERTICAL);
            bodyBox.setPadding(dp(16), 0, dp(16), 4);
            TextView titleView = label(shownTitle, 18, UI_INK, tfHan);
            titleView.setLetterSpacing(-0.02f);
            bodyBox.addView(titleView);
            TextView advice = label("请复制下面的完整信息，方便定位问题。记录号 " + DebugSink.REF, 10, UI_MUTED, tfHan);
            LinearLayout.LayoutParams adviceLp = new LinearLayout.LayoutParams(-1, -2);
            adviceLp.topMargin = dp(8);
            bodyBox.addView(advice, adviceLp);
            TextView detail = label(shownBody, 9.5f, 0xFF454640, tfHan);
            detail.setTextIsSelectable(true);
            detail.setLineSpacing(dp(4), 1f);
            detail.setPadding(dp(12), dp(11), dp(12), dp(11));
            android.graphics.drawable.GradientDrawable detailBg = new android.graphics.drawable.GradientDrawable();
            detailBg.setColor(0xFFE7E8E3);
            detail.setBackground(detailBg);
            LinearLayout.LayoutParams detailLp = new LinearLayout.LayoutParams(-1, -2);
            detailLp.topMargin = dp(14);
            bodyBox.addView(detail, detailLp);
            scroll.addView(bodyBox, new android.widget.FrameLayout.LayoutParams(-1, -2));
            int bodyHeight = (int) Math.min(dp(340), getResources().getDisplayMetrics().heightPixels * 0.44f);
            card.addView(scroll, new LinearLayout.LayoutParams(-1, bodyHeight));

            LinearLayout actions = new LinearLayout(this);
            actions.setOrientation(LinearLayout.HORIZONTAL);
            actions.setPadding(dp(16), dp(14), dp(16), dp(16));
            TextView closeAction = label("关闭", 10, UI_BLUE, tfHan);
            closeAction.setGravity(android.view.Gravity.CENTER);
            android.graphics.drawable.GradientDrawable closeBg = new android.graphics.drawable.GradientDrawable();
            closeBg.setColor(UI_PAPER);
            closeBg.setStroke(dp(1), UI_BLUE);
            closeAction.setBackground(closeBg);
            closeAction.setOnClickListener(v -> dialog.dismiss());
            LinearLayout.LayoutParams closeLp = new LinearLayout.LayoutParams(0, dp(42), 1f);
            closeLp.rightMargin = dp(8);
            actions.addView(closeAction, closeLp);
            TextView copy = label("复制错误信息", 10, UI_PAPER, tfHan);
            copy.setGravity(android.view.Gravity.CENTER);
            android.graphics.drawable.GradientDrawable copyBg = new android.graphics.drawable.GradientDrawable();
            copyBg.setColor(UI_BLUE);
            copy.setBackground(copyBg);
            copy.setOnClickListener(v -> {
                try {
                    // **The ref goes first.** It is the only line that leads
                    // back to the D1 rows; a screenshot of the dialog is not
                    // always possible, and a pasted body without it is a
                    // report with no address.
                    final String text = "记录号 " + DebugSink.REF
                            + "\n\n" + shownTitle + "\n\n" + shownBody
                            + "\n\nbuild=SpektraLab Android " + UpdateCheck.versionName(this)
                            + "\n" + probe.describe();
                    android.content.ClipboardManager cm =
                            (android.content.ClipboardManager) getSystemService(android.content.Context.CLIPBOARD_SERVICE);
                    cm.setPrimaryClip(android.content.ClipData.newPlainText("SpektraLab", text));
                    copy.setText("已复制");
                } catch (Throwable t) {
                    copy.setText("复制失败 · 请长按详情");
                }
            });
            actions.addView(copy, new LinearLayout.LayoutParams(0, dp(42), 1.45f));
            card.addView(actions, new LinearLayout.LayoutParams(-1, -2));

            dialog.setContentView(card);
            dialog.setCanceledOnTouchOutside(true);
            dialog.show();
            if (dialog.getWindow() != null) {
                dialog.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(0x00000000));
                int width = Math.min(dp(358),
                        getResources().getDisplayMetrics().widthPixels - dp(32));
                dialog.getWindow().setLayout(width, android.view.ViewGroup.LayoutParams.WRAP_CONTENT);
                dialog.getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_DIM_BEHIND);
                dialog.getWindow().setDimAmount(0.30f);
            }
            popInCard(card);
        });
    }

    private int extractInt(String json, String key) {
        int idx = json.indexOf(key);
        if (idx < 0) return 0;
        idx += key.length();
        int end = json.indexOf(",", idx);
        if (end < 0) end = json.indexOf("}", idx);
        if (end < 0) return 0;
        try {
            return Integer.parseInt(json.substring(idx, end).trim());
        } catch (Exception e) {
            return 0;
        }
    }
    
    private String getFileName(Uri uri) {
        String result = null;
        if (uri.getScheme().equals("content")) {
            try (android.database.Cursor cursor = getContentResolver().query(uri, null, null, null, null)) {
                if (cursor != null && cursor.moveToFirst()) {
                    int idx = cursor.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME);
                    if (idx >= 0) result = cursor.getString(idx);
                }
            }
        }
        if (result == null) {
            result = uri.getPath();
            // A provider can answer a `content://` URI whose path is null; the
            // crash then lands in `lastIndexOf` and reads as an import failure
            // with no file at all.
            if (result == null) return null;
            int cut = result.lastIndexOf('/');
            if (cut != -1) result = result.substring(cut + 1);
        }
        return result;
    }
    
    private String getFilePathFromUri(Uri uri) {
        // For content:// URIs, we need to copy to a temp file
        if (uri.getScheme().equals("content")) {
            try {
                String fileName = getFileName(uri);
                // **`filesDir`, not `cacheDir`.** The cache directory is the one
                // place the system is free to delete from under us, and the path
                // this returns is kept in `rawFilePath` and re-read by every full
                // export. A copy cut short reports `RAW unpack: Input/output
                // error (-100009)`, which reads like a corrupt file -- and the
                // file is fine. `filesDir/import` is the directory `privateCopy`
                // already uses for the same reason.
                java.io.File dir = new java.io.File(getFilesDir(), "import");
                if (!dir.exists() && !dir.mkdirs()) dir = getFilesDir();
                java.io.File tempFile = new java.io.File(dir, fileName);
                // What the provider says the size is, so a short copy is caught
                // here rather than in libraw's unpack().
                long expected = -1;
                try (android.database.Cursor c = getContentResolver().query(uri,
                        new String[]{android.provider.OpenableColumns.SIZE}, null, null, null)) {
                    if (c != null && c.moveToFirst()) expected = c.getLong(0);
                } catch (Throwable ignored) { }
                // **Already here, and whole: use it.** Every full export and every
                // fotufilm render asks for this path; copying the file again on
                // each of them is work nobody asked for.
                // **Only a *short* copy is a broken copy.** A provider's
                // `OpenableColumns.SIZE` can under-report: a Xiaomi gallery
                // answered 5,248,554 for a file that reads 5,248,586 -- and the
                // old `!= expected` test called that "copy short", deleted a
                // perfectly good copy twice, and left `fotufilm` with no path
                // ("\u8bfb\u4e0d\u5230\u539f\u56fe\u6587\u4ef6\uff1b\u8bf7\u91cd\u65b0\u5bfc\u5165\u8fd9\u4e00\u5f20",
                // SL-261118-06CA). The canvas never noticed: it decodes the
                // stream directly, and this door is only the second engine's.
                if (expected > 0 && tempFile.isFile() && tempFile.length() >= expected) {
                    return tempFile.getAbsolutePath();
                }
                // **Two callers can resolve the same grant at the same time.** The
                // canvas' import and the second engine's develop both land here,
                // and they used to write this path directly: one truncated the
                // other's bytes, and the engine then failed on a half-written
                // JPEG -- a 1 in two milliseconds, right after the tap. Each copy
                // gets its own name and the rename is atomic, so a reader only
                // ever sees a whole file.
                // **A short copy gets one more open.** Some providers answer the
                // first stream for a file they are still staging from the cloud
                // and hand out the whole thing the second time -- and the price
                // of asking again is one `openInputStream`, against a photograph
                // the user cannot render until they re-import it by hand.
                java.io.File part = null;
                for (int attempt = 0; attempt < 2; ++attempt) {
                    part = new java.io.File(dir, fileName + "." + System.nanoTime() + ".part");
                    try (InputStream in = getContentResolver().openInputStream(uri);
                         java.io.OutputStream out = new java.io.FileOutputStream(part)) {
                        if (in == null) { part.delete(); part = null; return null; }
                        final byte[] buf = new byte[64 * 1024];
                        copyStream(in, out, buf);
                    } catch (Exception e) {
                        part.delete();
                        part = null;
                        try { DebugSink.text("import", "copy failed: " + e); }
                        catch (Throwable ignored) { }
                        return null;
                    }
                    if (expected <= 0 || part.length() >= expected) {
                        if (expected > 0 && part.length() > expected) {
                            // Worth knowing: it means the provider's SIZE is not
                            // the file's length, which is what killed fotufilm.
                            try {
                                DebugSink.text("import", "copy longer than reported: "
                                        + part.length() + " > " + expected + " for " + fileName);
                            } catch (Throwable ignored) { }
                        }
                        break;
                    }
                    try { DebugSink.text("import", "copy short: " + part.length() + " of "
                            + expected + " for " + fileName + " (attempt " + (attempt + 1) + ")"); }
                    catch (Throwable ignored) { }
                    part.delete();
                    part = null;
                }
                if (part == null) return null;
                if (!part.renameTo(tempFile)) {
                    // Same directory, so a rename crosses no mount point and this
                    // should not happen -- but a `.part` name must never escape:
                    // the second engine decides by extension whether it can read
                    // the file, and would re-encode a perfectly good JPEG.
                    try (java.io.FileInputStream in = new java.io.FileInputStream(part);
                         java.io.FileOutputStream out = new java.io.FileOutputStream(tempFile)) {
                        byte[] buf = new byte[64 * 1024];
                        copyStream(in, out, buf);
                    } catch (Exception e) {
                        part.delete();
                        return null;
                    }
                    part.delete();
                }
                try { DebugSink.text("import", "copied " + tempFile.length() + " -> "
                        + tempFile.getAbsolutePath()); } catch (Throwable ignored) { }
                return tempFile.getAbsolutePath();
            } catch (Exception e) {
                try { DebugSink.text("import", "copy failed: " + e); } catch (Throwable ignored) { }
                return null;
            }
        } else if (uri.getScheme().equals("file")) {
            return uri.getPath();
        }
        return null;
    }

    /**
     * The EXIF orientation, or -1 when the provider will not give it to us.
     *
     * Two attempts on purpose: a stream first, then the file descriptor. Some
     * pickers and cloud providers hand out a one-shot stream, and the second
     * openInputStream() then fails -- the old code swallowed that and returned
     * the unrotated bitmap, which is exactly how a portrait frame arrives
     * sideways "at random".
     */
    /** The TIFF/EXIF orientation of a file on disk (raw containers included). */
    private int orientationOfPath(String path) {
        int fromPlatform = -1;
        try {
            fromPlatform = new android.media.ExifInterface(path).getAttributeInt(
                    android.media.ExifInterface.TAG_ORIENTATION,
                    android.media.ExifInterface.ORIENTATION_NORMAL);
        } catch (Throwable t) {
            try { DebugSink.text("exif", "path: " + t); } catch (Throwable ignored) { }
        }
        if (fromPlatform > 0) return fromPlatform;
        // ExifInterface does not open every raw container: RW2 writes 0x55
        // where TIFF writes 42, and the platform reader refuses it outright on
        // some builds. IFD0's tag 0x0112 is four bytes away from a header we
        // can read ourselves.
        return tiffOrientation(path);
    }

    /** TAG_ORIENTATION out of a TIFF-style container, magic 42 or Panasonic's 0x55. */
    private int tiffOrientation(String path) {
        java.io.RandomAccessFile file = null;
        try {
            file = new java.io.RandomAccessFile(path, "r");
            if (file.length() < 16) return -1;
            final byte[] head = new byte[8];
            file.readFully(head);
            final boolean little = head[0] == 0x49 && head[1] == 0x49;
            final int magic = shortAt(head, 2, little);
            if (magic != 42 && magic != 0x55) return -1;
            final long ifd = longAt(head, 4, little);
            if (ifd <= 0 || ifd > file.length() - 2) return -1;
            file.seek(ifd);
            final byte[] count = new byte[2];
            file.readFully(count);
            final int entries = shortAt(count, 0, little);
            if (entries <= 0 || entries > 512) return -1;
            final byte[] table = new byte[entries * 12];
            file.readFully(table);
            for (int i = 0; i < entries; ++i) {
                final int base = i * 12;
                if (shortAt(table, base, little) != 0x0112) continue;      // Orientation
                if (shortAt(table, base + 2, little) != 3) continue;       // SHORT
                return shortAt(table, base + 8, little);
            }
        } catch (Throwable t) {
            return -1;
        } finally {
            if (file != null) try { file.close(); } catch (Throwable ignored) { }
        }
        return -1;
    }

    private static int shortAt(byte[] b, int at, boolean little) {
        final int a = b[at] & 0xFF, c = b[at + 1] & 0xFF;
        return little ? (c << 8 | a) : (a << 8 | c);
    }

    private static long longAt(byte[] b, int at, boolean little) {
        long v = 0;
        for (int i = 0; i < 4; ++i) {
            final int idx = little ? at + 3 - i : at + i;
            v = (v << 8) | (b[idx] & 0xFF);
        }
        return v;
    }

    private int readOrientation(Uri uri) {
        try (InputStream in = getContentResolver().openInputStream(uri)) {
            if (in != null) {
                return new android.media.ExifInterface(in).getAttributeInt(
                        android.media.ExifInterface.TAG_ORIENTATION,
                        android.media.ExifInterface.ORIENTATION_NORMAL);
            }
        } catch (Throwable ignored) { }
        try (android.os.ParcelFileDescriptor fd = getContentResolver().openFileDescriptor(uri, "r")) {
            if (fd != null) {
                return new android.media.ExifInterface(fd.getFileDescriptor()).getAttributeInt(
                        android.media.ExifInterface.TAG_ORIENTATION,
                        android.media.ExifInterface.ORIENTATION_NORMAL);
            }
        } catch (Throwable ignored) { }
        return -1;
    }

    /**
     * The image, decoded. `BitmapFactory` first -- the path every JPEG and PNG
     * has always taken -- and `ImageDecoder` when that comes back empty.
     *
     * The second attempt is for HEIC/HEIF. Samsung and iPhone save 10-bit HEIF,
     * `BitmapFactory.decodeStream` returns null on those (and reports no bounds
     * at all for the sniff), while the platform decoder behind `ImageDecoder`
     * (API 28+) hands back a software bitmap. The old code said "无法解码图片"
     * and stopped -- which a Samsung user read, correctly, as "this app cannot
     * import my photos".
     */
    private Bitmap decodeImport(Uri uri, int capPixels, int edgeCap) {
        try {
            BitmapFactory.Options bounds = new BitmapFactory.Options();
            bounds.inJustDecodeBounds = true;
            try (InputStream head = getContentResolver().openInputStream(uri)) {
                if (head != null) BitmapFactory.decodeStream(head, null, bounds);
            } catch (Throwable t) {
                try { DebugSink.text("decode", "sniff " + t); } catch (Throwable ignored) { }
            }
            if (bounds.outWidth > 0 && bounds.outHeight > 0) {
                // **Skip pixels when the file is far beyond the budget.**
                // This used to decode at full size and scale afterwards, so a
                // 200 MP phone JPEG became an 800 MB ARGB bitmap and then a
                // second 220 MB one -- two of them live at once, which is what
                // the 12288x16320 imports were dying of (ANR, then LOW_MEMORY).
                // `inSampleSize` is a power of two and throws away three
                // quarters of the pixels, so it is only worth using when the
                // overshoot is more than 2.2x; below that the area scaling
                // after decode is the better trade.
                int sample = 1;
                while (sample < 16) {
                    final long sw = bounds.outWidth / (sample * 2);
                    final long sh = bounds.outHeight / (sample * 2);
                    if (sw <= 0 || sh <= 0) break;
                    final double overshoot = (double) bounds.outWidth * bounds.outHeight
                            / ((double) Math.max(1, capPixels) * sample * sample);
                    final long edge = Math.max(bounds.outWidth, bounds.outHeight) / (sample * 2);
                    if (overshoot <= 2.2 && edge <= (long) edgeCap * 1.2) break;
                    sample *= 2;
                }
                BitmapFactory.Options opts = new BitmapFactory.Options();
                opts.inSampleSize = sample;
                try (InputStream stream = getContentResolver().openInputStream(uri)) {
                    Bitmap decoded = BitmapFactory.decodeStream(stream, null, opts);
                    if (decoded != null) return decoded;
                    try { DebugSink.text("decode", "null at sample " + sample); }
                    catch (Throwable ignored) { }
                } catch (Throwable t) {
                    try { DebugSink.text("decode", "stream " + t); } catch (Throwable ignored) { }
                }
            } else {
                try { DebugSink.text("decode", "no bounds " + bounds.outWidth + "x" + bounds.outHeight); }
                catch (Throwable ignored) { }
            }
        } catch (Throwable t) {
            try { DebugSink.text("decode", "outer " + t); } catch (Throwable ignored) { }
        }
        Bitmap platform = decodeViaImageDecoder(uri, capPixels, edgeCap);
        if (platform != null) return platform;
        return decodeViaCodecs(uri, edgeCap);
    }

    /**
     * **A TIFF is not something Android can open.**
     *
     * <p>Both platform decoders report no bounds and hand back null, so every TIFF written by
     * Photoshop, Lightroom or a film scanner ended on "无法解码图片" -- the one import a
     * darkroom-shaped app must accept. The second engine's codecs already link libtiff; they
     * decode, upright and reduce in one call, and the answer is the same Display P3 / sRGB
     * eight-bit frame a JPEG arrives as.
     */
    private Bitmap decodeViaCodecs(Uri uri, int edgeCap) {
        java.io.File temp = null;
        try {
            String path = getFilePathFromUri(uri);
            if (path == null) {
                // A `content://` the resolver will not hand a path for: one copy, then decode it.
                temp = new java.io.File(getCacheDir(), "import-" + System.currentTimeMillis() + ".img");
                try (InputStream in = getContentResolver().openInputStream(uri);
                     java.io.OutputStream out = new java.io.FileOutputStream(temp)) {
                    if (in == null) return null;
                    final byte[] buf = new byte[256 * 1024];
                    copyStream(in, out, buf);
                }
                path = temp.getAbsolutePath();
            }
            final int edge = edgeCap > 0 ? edgeCap : 8000;
            final int[] px = app.spektralab.engine.FotuFilm.decodeImage(path, edge);
            if (px == null || px.length < 3) return null;
            final int w = px[0], h = px[1];
            if (w <= 0 || h <= 0 || px.length < 2 + w * h) return null;
            final int[] argb = new int[w * h];
            System.arraycopy(px, 2, argb, 0, w * h);
            final Bitmap bmp = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888);
            bmp.setPixels(argb, 0, w, 0, 0, w, h);
            CrashTrail.mark(this, "import:codecs " + w + "x" + h);
            try { DebugSink.text("decode", "codecs " + w + "x" + h); } catch (Throwable ignored) { }
            return bmp;
        } catch (Throwable t) {
            try { DebugSink.text("decode", "codecs " + t); } catch (Throwable ignored) { }
            return null;
        } finally {
            if (temp != null) temp.delete();
        }
    }

    /**
     * The platform decoder through its newer door, scaled in the decoder so the
     * full-size bitmap never exists. **Software allocator on purpose**: a
     * hardware bitmap cannot be read back with `getPixels`, and the import path
     * reads every pixel into a float buffer.
     */
    private Bitmap decodeViaImageDecoder(Uri uri, final int capPixels, final int edgeCap) {
        if (android.os.Build.VERSION.SDK_INT < 28) return null;
        try {
            final android.graphics.ImageDecoder.Source src =
                    android.graphics.ImageDecoder.createSource(getContentResolver(), uri);
            Bitmap decoded = android.graphics.ImageDecoder.decodeBitmap(src,
                    (decoder, info, source) -> {
                        final android.util.Size size = info.getSize();
                        final int w = size.getWidth(), h = size.getHeight();
                        double k = 1.0;
                        final long area = (long) w * (long) h;
                        if (area > capPixels) k = Math.min(k, Math.sqrt((double) capPixels / area));
                        final int longEdge = Math.max(w, h);
                        if (longEdge > edgeCap) k = Math.min(k, (double) edgeCap / longEdge);
                        if (k < 1.0) {
                            decoder.setTargetSize(Math.max(1, (int) Math.round(w * k)),
                                                  Math.max(1, (int) Math.round(h * k)));
                        }
                        decoder.setAllocator(android.graphics.ImageDecoder.ALLOCATOR_SOFTWARE);
                    });
            try { DebugSink.text("decode", "imagedecoder " + decoded.getWidth() + "x"
                    + decoded.getHeight()); } catch (Throwable ignored) { }
            return decoded;
        } catch (Throwable t) {
            try { DebugSink.text("decode", "imagedecoder " + t); } catch (Throwable ignored) { }
            return null;
        }
    }

    /**
     * A failure the user can act on. `OutOfMemoryError` is an `Error`, not an
     * `Exception`, which is why the `catch (Exception)` this replaces let the
     * process die on the Honor report instead of saying 内存不足.
     */
    private String describeImportFailure(Throwable t) {
        try { DebugSink.text("import-error", String.valueOf(t)); } catch (Throwable ignored) { }
        if (t instanceof OutOfMemoryError) {
            // **Never tell the user to bring a smaller picture.** That turns our
            // own allocation into their composition problem, and the frame that
            // failed here is usually one the engine can render perfectly -- the
            // 576 MB import buffer was refused by a ledger, not by the device.
            // What is worth saying is which way out exists and that the file
            // itself is wanted if it keeps happening.
            return "[E-1003] 这张图解码时内存不够了。先关掉其它应用再试一次；"
                    + "如果反复出现，把这张图的原始文件发给我，我看能不能在解码这一步省下内存";
        }
        return SpkError.format(describe(t));
    }

    private Bitmap applyExifRotation(Uri uri, Bitmap bitmap) {
        final int orientation = readOrientation(uri);
        try { DebugSink.text("exif", "orientation=" + orientation + " bitmap="
                + bitmap.getWidth() + "x" + bitmap.getHeight()); } catch (Throwable ignored) { }
        return rotateForOrientation(bitmap, orientation);
    }

    /** The orientation tag as a matrix. 0 or negative means "unreadable". */
    private Bitmap rotateForOrientation(Bitmap bitmap, int orientation) {
        if (orientation <= 0) return bitmap;      // unreadable: leave the pixels alone
        try {
            android.graphics.Matrix matrix = new android.graphics.Matrix();
            switch (orientation) {
                case android.media.ExifInterface.ORIENTATION_ROTATE_90:
                    matrix.postRotate(90); break;
                case android.media.ExifInterface.ORIENTATION_ROTATE_180:
                    matrix.postRotate(180); break;
                case android.media.ExifInterface.ORIENTATION_ROTATE_270:
                    matrix.postRotate(270); break;
                case android.media.ExifInterface.ORIENTATION_FLIP_HORIZONTAL:
                    matrix.postScale(-1, 1); break;
                case android.media.ExifInterface.ORIENTATION_FLIP_VERTICAL:
                    matrix.postScale(1, -1); break;
                // The two mirrored rotations. Rare, but a phone that writes 5
                // or 7 and lands in the default branch shows its photo sideways.
                case android.media.ExifInterface.ORIENTATION_TRANSPOSE:
                    matrix.postRotate(90); matrix.postScale(-1, 1); break;
                case android.media.ExifInterface.ORIENTATION_TRANSVERSE:
                    matrix.postRotate(-90); matrix.postScale(-1, 1); break;
                default:
                    return bitmap;
            }
            return Bitmap.createBitmap(bitmap, 0, 0, bitmap.getWidth(), bitmap.getHeight(), matrix, true);
        } catch (Exception e) {
            return bitmap;
        }
    }


    /**
     * A stock change only re-renders. Measured against fresh sessions on this
     * engine, the stored print solution already gives the same picture after a
     * film switch (mean 64.4/58.9/55.7 either way) and a paper switch only moves
     * the paper's own speed, which the enlarger-exposure slider is for. Calling
     * `spk_solve` here re-metered a cached full-size negative and never returned,
     * which is what left the status bar stuck on "配光中".
     */
    private void onStockChanged() {
        if (session == null || !uiReady) return;
        if (filmStock == null) {
            // No film yet: the frame stays the import's own, and the sheet's
            // choice is remembered for the first render.
            showInAppToast("选择一张胶片开始渲染");
            return;
        }
        // No `applySessionParams()` here any more: it wrote the engine from the
        // UI thread, which both raced the catalogue queue and could park the UI
        // behind a long render's lock. `renderImage` applies the stock under the
        // same lock it renders under -- one writer, one order.
        showingOriginal = false;
        setOriginalVisual(false);
        updateFilmSelection();
        renderImage();
    }


    /**
     * The cheap half: what a slider owns.
     *
     * No stock, no colour space, no preview size -- those describe the file and
     * live in `applySessionParams`. Sending them on every drag tick made the
     * engine rebuild the pipeline once per step (the presence of `film_stock`
     * in a delta *is* a stock change), which is what made the sliders feel
     * dead rather than merely slow.
     */
    private void applyParams() {
        if (session == null) return;
        // **A delta is never sent from the UI thread.**
        //
        // `spk_set_params` takes `session->lock`, and `render_tier` holds that
        // lock for the entire render. Releasing a slider mid-render therefore
        // blocked the main thread for the rest of the render, then rebuilt the
        // whole pipeline on the UI thread at the exact instant the render
        // finished -- and `renderImage` queued a second rebuild right after it
        // (`pendingRender`), so two full pipeline rebuilds landed back to back.
        // That is "渲染期间不能进行光学调整，否则容易出现闪退" on Adreno 730.
        //
        // Every caller below is followed by `renderImage()`, and its render
        // thread sends this same delta -- with the film and the paper, under
        // the lock -- once, immediately before `renderBegin`. So this method is
        // now a log line: the value belongs to the next render, and the next
        // render is the only thing allowed to say so.
        try {
            DebugSink.text("params", "deferred render=" + rendering + " film=" + filmStock
                    + " print=" + printStock + " overscan=" + overscanOn + " date=" + dateOn
                    + " fmt=" + filmFormatMm);
        } catch (Throwable ignored) { }
    }

    /**
     * The same delta **plus the film and the paper**, for every call that is
     * about to produce a picture.
     *
     * <p>This is the one thing that has to be true before `renderBegin`: the
     * session carries the stock the user is looking at. It used to be kept by
     * a Java-side `sessionSignature` -- a field written by the catalogue
     * queue and by the UI thread, compared against the engine's *assumed*
     * state. One write out of order and the signature claimed a stock the
     * session never got, so every film rendered the same picture while the
     * rebate text (which the app draws from its own field) kept changing.
     *
     * <p>Stating the stock in the delta costs ~10 ms on the host (26 ms
     * against 19 ms for the delta without it, measured at 900x600 with
     * `stock_cost`); a render is two orders of magnitude more. So there is no
     * bookkeeping left to get wrong: whoever draws, says what to draw.
     */
    /**
     * Push the geometry group on its own, right before a render.
     *
     * <p>Cheap (one stock rebuild, tens of milliseconds against a render that
     * costs a second) and unconditional, because the alternative -- trusting
     * the delta ledger to notice -- is what produced "一松手，重新渲染完，照片
     * 变回原来位置了": the canvas turned, the file did not. Always logs the
     * exact JSON, so the next report can say what left the app rather than
     * what should have.
     */
    private void sendGeometry() {
        if (session == null || filmStock == null) return;
        // **The snapshot, not the live fields.** See `geoSnapRot`: reading the
        // live ones here is what let a UI-thread write land between the commit
        // and this line and silently turn the picture back upright.
        final float rot = geoSnapValid ? geoSnapRot : geometryRotation;
        final int turns = geoSnapValid ? geoSnapTurns : geometryTurns;
        final boolean fh = geoSnapValid ? geoSnapFlipH : geometryFlipH;
        final boolean fv = geoSnapValid ? geoSnapFlipV : geometryFlipV;
        final float cropW = geoSnapValid ? geoSnapW : Math.max(0.01f, Math.min(1f, geometryCropW));
        final float cropH = geoSnapValid ? geoSnapH : Math.max(0.01f, Math.min(1f, geometryCropH));
        final float cropX = geoSnapValid ? geoSnapX : Math.max(0f, Math.min(1f - cropW, geometryCropX));
        final float cropY = geoSnapValid ? geoSnapY : Math.max(0f, Math.min(1f - cropH, geometryCropY));
        final String d = "{\"film_stock\":" + q(filmStock)
                + ",\"geometry_rotation_deg\":" + f("%.3f", -rot)
                + ",\"geometry_quarter_turns\":" + turns
                + ",\"geometry_flip_h\":" + b(fh)
                + ",\"geometry_flip_v\":" + b(fv)
                + ",\"geometry_crop_x\":" + f("%.6f", cropX)
                + ",\"geometry_crop_y\":" + f("%.6f", cropY)
                + ",\"geometry_crop_w\":" + f("%.6f", cropW)
                + ",\"geometry_crop_h\":" + f("%.6f", cropH) + "}";
        try {
            session.setParams(d);
            // The ledger no longer describes the session: the next full delta
            // has to restate everything, or the fields this call did not name
            // would be remembered as sent.
            deltaSession = null;
            deltaSent.clear();
            DebugSink.text("geo", "sent " + d);
            // **What the engine actually holds**, not what was sent. If these
            // two ever disagree the bug is inside `spk_set_params`; if they
            // agree and the canvas is still wrong, the bug is in the render.
            try {
                final String gp = session.getParams();
                final int at = gp.indexOf("\"geometry_rotation_deg\"");
                DebugSink.text("geo-check", at >= 0
                        ? gp.substring(at, Math.min(gp.length(), at + 44)) : "absent");
            } catch (Throwable ignored) { }
        } catch (Throwable t) {
            // Put it back: a geometry edit that did not reach the engine must
            // be retried by the next render, not forgotten.
            pendingGeometry = true;
            try { DebugSink.textNow("geo", "FAILED " + t + " :: " + d); } catch (Throwable ignored) { }
        }
    }

    private boolean applyParams(String stock, int longEdge) {
        return applyParams(stock, printStock == null ? "kodak_portra_endura" : printStock, longEdge);
    }

    /**
     * The same delta with the paper named explicitly.
     *
     * <p>The shelf needs this: a card is "this film on **its** paper", so a
     * black-and-white card must render on Ilford even while the canvas is on
     * whatever paper the user picked. Before this the card took the global
     * `printStock`, so every black-and-white card came out sepia -- the shelf
     * showed the wrong recipe and read as "the black-and-white film is broken".
     */
    private boolean applyParams(String stock, String paper, int longEdge) {
        return applyParamsTo(session, stock, paper, longEdge, previewSpace);
    }

    // ── undo ──────────────────────────────────────────────────────

    /**
     * Take a snapshot once the edit settles.
     *
     * <p>Debounced, because a slider fires `renderImage` on every release and
     * a burst of them would fill the stack with near-identical states. The
     * dedupe on the serialised Look means a render that changed nothing costs
     * nothing, which is what makes "one entry per real edit" hold.
     */
    private void scheduleUndo() {
        undoHandler.removeCallbacks(undoPush);
        undoHandler.postDelayed(undoPush, 600);
    }

    /** A render that failed must not enter the undo stack: replaying it would
     *  fail again, which is "undo brings the error back". */
    private void cancelUndo() {
        undoHandler.removeCallbacks(undoPush);
    }

    private void pushUndoNow() {
        if (session == null || filmStock == null) return;
        final String now;
        try { now = lookToJson(captureLook()).toString(); }
        catch (Throwable t) { return; }
        if (now.equals(undoLast)) return;
        undoLast = now;
        undoStack.push(now);
        while (undoStack.size() > UNDO_LIMIT) undoStack.removeLast();
        refreshUndoPill();
    }

    /**
     * Back one edit.
     *
     * <p>The stack holds the state *after* each edit, so undoing is: drop the
     * top (where we are), restore the new top. The first entry is the import,
     * which is why the button hides once `size() <= 1` -- there is nothing
     * before the import to go back to.
     */
    private void undoStep() {
        undoHandler.removeCallbacks(undoPush);
        if (undoStack.size() <= 1) {
            showInAppToast("已经回到最初的编辑");
            return;
        }
        undoStack.pop();
        final String previous = undoStack.peek();
        if (previous == null) return;
        try {
            applyLook(lookFromJson(new org.json.JSONObject(previous)));
        } catch (Throwable ignored) { }
        undoLast = previous;
        refreshUndoPill();
        applyParams();
        if (uiReady && session != null) {
            showingOriginal = false;
            setOriginalVisual(false);
            renderImage();
        }
    }

    /** A new photograph starts its own history. */
    private void resetUndo() {
        undoHandler.removeCallbacks(undoPush);
        undoStack.clear();
        undoLast = null;
        refreshUndoPill();
    }

    private void refreshUndoPill() {
        if (undoPill == null) return;
        undoPill.setVisibility(undoStack.size() > 1 ? View.VISIBLE : View.GONE);
    }

    /** Build the one Look delta and send it to the named session. Export uses
     * this directly; it never borrows the global preview-session field. */
    // ── the delta ──────────────────────────────────────────────────

    /** A JSON string literal. `q(null)` is `""`, not `"null"`. */
    private static String q(String v) {
        if (v == null) return "\"\"";
        final StringBuilder o = new StringBuilder(v.length() + 2).append('"');
        for (int i = 0; i < v.length(); ++i) {
            final char c = v.charAt(i);
            if (c == '"' || c == '\\') o.append('\\').append(c);
            else if (c < 0x20) o.append(String.format(java.util.Locale.US, "\\u%04x", (int) c));
            else o.append(c);
        }
        return o.append('"').toString();
    }

    private static String b(boolean v) { return v ? "true" : "false"; }

    private static String f(String fmt, double v) {
        return String.format(java.util.Locale.US, fmt, v);
    }

    /**
     * Only the keys whose value differs from what this session already carries.
     *
     * <p>**Why this exists.** The delta used to name all seventy-odd fields
     * every time. `spk_set_params` treats the *presence* of `film_stock` as a
     * stock change, so every slider tick rebuilt the whole parameter tree
     * (30–110 ms), and -- the part that mattered more -- a shoot-layer field in
     * the delta makes the engine drop the cached negative. With the whole set
     * going out on every tick, `spk_reprint` could never skip the film side: it
     * always found an empty cache and spent 200 ms redeveloping a frame the
     * user was only nudging the print exposure of.
     *
     * <p>The engine carries every field a delta leaves out (a stock change reads
     * the session's own tree back and replays it), so sending less says exactly
     * the same thing. What is *not* allowed to drift is this map: it is written
     * only by the thread that draws, under `renderMutex`, and a different
     * session object clears it.
     */
    private String deltaFor(SpektraLabEngine.Session target,
                            java.util.LinkedHashMap<String, String> kv) {
        if (target != deltaSession) {
            deltaSent.clear();
            deltaSession = target;
        }
        final StringBuilder out = new StringBuilder(768);
        int n = 0;
        for (java.util.Map.Entry<String, String> e : kv.entrySet()) {
            if (e.getValue().equals(deltaSent.get(e.getKey()))) continue;
            out.append(n++ == 0 ? "{" : ",").append('"').append(e.getKey()).append("\":")
               .append(e.getValue());
            deltaSent.put(e.getKey(), e.getValue());
        }
        if (n == 0) return null;
        return out.append('}').toString();
    }

    /** Frame `i`'s URI, or null. The identity behind "whose EV is this". */
    private String frameUri(int i) {
        try {
            if (i < 0 || i >= frames.size()) return null;
            final Frame f = frames.get(i);
            return f == null || f.uri == null ? null : f.uri.toString();
        } catch (Throwable t) {
            return null;
        }
    }

    /** True when {@link #lastAppliedEv} was measured on the frame in front of us. */
    private boolean appliedEvBelongsToCurrentFrame() {
        if (!lastAppliedEvValid) return false;
        final String here = frameUri(currentFrame);
        return here != null && here.equals(lastAppliedEvUri);
    }

    /** `"auto_exposure_ev":0.0755` out of a progress document, for a log line. */
    private static String appliedEvText(String progressJson) {
        if (progressJson == null) return "(no progress json)";
        final int at = progressJson.indexOf("\"auto_exposure_ev\"");
        if (at < 0) return "(none)";
        return progressJson.substring(at, Math.min(progressJson.length(), at + 40));
    }

    /**
     * Records the EV a render applied, from the progress document read **right
     * after** that render.
     */
    private void rememberAppliedEv(String progressJson, String tier) {
        String text = appliedEvText(progressJson);
        if (progressJson != null) {
            final int at = progressJson.indexOf("\"auto_exposure_ev\":");
            if (at >= 0) {
                int i = at + "\"auto_exposure_ev\":".length();
                while (i < progressJson.length() && progressJson.charAt(i) == ' ') ++i;
                final int start = i;
                while (i < progressJson.length()) {
                    final char c = progressJson.charAt(i);
                    if ((c >= '0' && c <= '9') || c == '-' || c == '+' || c == '.'
                            || c == 'e' || c == 'E') ++i;
                    else break;
                }
                if (i > start) {
                    try {
                        final double v = Double.parseDouble(progressJson.substring(start, i));
                        if (!Double.isNaN(v) && !Double.isInfinite(v)) {
                            lastAppliedEv = v;
                            lastAppliedEvValid = true;
                            lastAppliedEvUri = frameUri(currentFrame);
                        }
                    } catch (Throwable ignored) { }
                }
            }
        }
        // One line per *change*, not per frame: the live loop draws at 11 Hz and
        // a steady EV is the normal case.
        if (lastAppliedEv != loggedEv) {
            loggedEv = lastAppliedEv;
            try {
                DebugSink.text("exposure", "tier=" + tier + " " + text
                        + " -> pinned " + lastAppliedEv + (lastAppliedEvValid ? "" : " (none)"));
            } catch (Throwable ignored) { }
        }
    }

    /**
     * **The paper the engine may be handed.**
     *
     * <p>`printStock` is a UI value with two kinds of non-paper in it:
     * 「无相纸 · 负片本身」 (`PAPER_SCAN`) and a fotufilm medium
     * (`crystal-archive`, `screen`). `spk_open` / `openRawSession` read
     * `print_stock` as a *profile file name*, so either one answers
     * `no profile '__scan__'` before `scan_film` or anything else is read.
     *
     * <p>`applyParamsTo` has carried this check since 1.6.13 -- but the RAW
     * import and the export's own `spk_open` build their params by hand, and
     * neither did. With 「无相纸」 as the default paper (1.6.13y) that made
     * **reopening any RAW frame** die on import (SL-261119-938F). One function,
     * four callers, so a fifth cannot be born without it.
     */
    private String spkPaperForEngine(String paper) {
        if (paper != null && !PAPER_SCAN.equals(paper)
                && (printIds == null || printIds.isEmpty() || printIds.contains(paper)))
            return paper;
        return "kodak_portra_endura";
    }

    private boolean applyParamsTo(SpektraLabEngine.Session target, String stock, String paper,
                                  int longEdge, String space) {
        return applyParamsTo(target, stock, paper, longEdge, space, false);
    }

    /**
     * @param force send every key, ignoring what this session was already told.
     *
     * <p>**An export must force.** The delta is diffed against `deltaSent`, and
     * when the export runs on the session the canvas already used, every value
     * is "unchanged" -- so nothing was sent at all (`export-params:
     * ... pex=0.41125 (no delta sent)`), and the engine kept whatever that
     * session was opened with. The owner's report: the enlarger exposure was
     * pulled to the end of its travel and every exported file came back as if
     * it had never been touched. The engine is fine -- `print_exposure`
     * 0.25/1.00/4.00 renders 188.65/78.29/15.29 on the host.
     */
    /**
     * @return true when anything actually went to the engine. False means the
     *         delta came out empty -- the session already carries exactly this
     *         parameter set -- which is what lets an optics-only edit skip the
     *         render entirely (see `drawLivePreview`).
     */
    private boolean applyParamsTo(SpektraLabEngine.Session target, String stock, String paper,
                                  int longEdge, String space, boolean force) {
        if (force) {
            // Cold bookkeeping, not a behaviour change: with an empty ledger
            // every key differs and the loop below sends all of them.
            deltaSession = null;
            deltaSent.clear();
        }
        if (target == null || stock == null) return false;
        // **The second engine's ids never go to the first.** `fotu:c200` is not
        // a profile file name and `load_profile` rejects it outright, which is
        // E-9000 on whatever UI path happened to send it. Every fotufilm frame
        // is drawn by `renderFotu`, so there is nothing here to state.
        if (isFotuStock(stock)) return false;
        // A null paper used to return here, which meant "sent nothing at all"
        // rather than "sent everything but the paper".
        // **And a fotufilm medium is not a paper.** Picking a fotufilm stock
        // puts `crystal-archive` / `screen` / `endura-premier` into
        // `printStock`; the first engine has no such profile and answers with
        // `no profile 'crystal-archive'`. This is the one place all three
        // callers -- canvas, shelf card, export -- pass through, so the check
        // belongs here rather than in each of them.
        // **The sentinel never reaches the engine.** With `scan_film` on the
        // paper is ignored anyway, but `applyParamsTo` still has to hand it a
        // profile id it knows, or `no profile '__scan__'` is thrown before the
        // flag is ever read.
        // **Per call, not per field.** `scan_film` used to be read off
        // `printStock`, so once the canvas was on 无相纸 every *thumbnail* also
        // rendered with the flag set -- and the shelf, which renders one card at
        // a time through this same function, stopped filling. The medium is an
        // argument here; it must be read from the argument.
        final boolean scanMedium = PAPER_SCAN.equals(paper);
        paper = spkPaperForEngine(paper);
        pushViewAdjust();
        pushViewCurves();
        final java.util.LinkedHashMap<String, String> kv = new java.util.LinkedHashMap<>();
        kv.put("film_stock", q(stock));
        kv.put("print_stock", q(paper));
        kv.put("input_color_space", q(isRawFile ? "ProPhoto RGB" : "sRGB"));
        kv.put("input_cctf_decoding", b(!isRawFile));
        // **The honour system is the user's.** A JPEG used to be forced off
        // because the engine's default meter is an arithmetic mean and metering
        // a camera JPEG twice washed it grey. That is a reason not to *default*
        // it on, not a reason to refuse: a frame someone deliberately asks to
        // meter is their call, and `protect_highlights` on a JPEG is a
        // reasonable request. The default for a JPEG is still off.
        final String meter = sanitizeMeter(meterMethod);
        // **An export keeps the canvas' own meter, and that is the whole
        // point.** `auto_exposure` is applied by `node_auto_exposure` in
        // `film_prefix` -- *before* `scene_latitude` rolls the highlights off --
        // while `exposure_compensation_ev` is applied in `filming.expose`,
        // after it. The same number of stops therefore produces two different
        // pictures (host, 20 MP frame: 21410 vs 10061 mean16, p05 7271 vs 552).
        // Turning the meter off for the export and moving its EV into
        // `exposure_compensation_ev` is what made every file look as if the
        // enlarger exposure had never been touched. The export is the picture
        // on screen, so it is given the same flag *and* the same EV.
        kv.put("auto_exposure", b(!meter.isEmpty()));
        // **`protect_highlights`, not `balanced`, while the meter is on.**
        // `balanced` aimed a lamp-in-a-dark-room at mid-grey and put 19 % of the
        // frame past the paper's white; `protect_highlights` is the same meter
        // with the highlight end held, two stops lower on that scene (+2.41 vs
        // +5.41). The default (meter off) keeps `balanced` so the value is
        // identical to what the reference sends.
        kv.put("auto_exposure_method", q(meter.isEmpty() ? "balanced" : meter));
        // **Whether this stock is a slide, decided once.** Two switches below
        // are refused by the engine when it is: "black/white correction on a
        // directly scanned positive film is not implemented by the native
        // engine" -- seven sessions in a week, because the two sliders are on
        // the same page as everything else and nothing stops them being dragged
        // while a reversal film is loaded.
        final boolean scannedPositive = isPositiveStock(stock) || scanMedium;
        kv.put("scan_film", b(scannedPositive));
        kv.put("output_color_space", q(space == null ? "sRGB" : space));
        kv.put("preview_long_edge", Integer.toString(longEdge));
        kv.put("print_exposure", f("%.2f", printExposure));
        kv.put("grain_amount", f("%.3f", wireGrain(stock)));
        kv.put("grain_sublayers_active", b(!isMonochromeStock(stock)));
        kv.put("halation_amount", f("%.3f", halationAmount));
        kv.put("halation_boost_ev", f("%.2f", halationBoost));
        kv.put("halation_scatter_amount", f("%.3f", halationScatter));
        kv.put("halation_scatter_scale", f("%.3f", 1.0f + 63.0f * scatterRadius));
        kv.put("halation_additive", b(halationAmount > 1.01f));
        kv.put("halation_active", b(halationOn > 0.5f));
        kv.put("antihalation_removed", b(antihalationRemoved > 0.5f));
        kv.put("grain_active", b(grainOn > 0.5f));
        kv.put("dir_couplers_active", b(true));
        kv.put("dir_couplers_amount", f("%.3f", couplersOn));
        kv.put("scanner_white_correction", b(scannerWhite > 0.5f && !scannedPositive));
        // The five that used to have no sender. Ranges are the schema's:
        // scanner.lens_blur 0..20, halation.headroom_ev 0..8,
        // film_render.density_curve_gamma 0.2..4.
        kv.put("glare_active", b(glareActive > 0.5f));
        kv.put("scanner_lens_blur", f("%.2f", scannerLensBlur));
        kv.put("halation_headroom_ev", f("%.2f", halationHeadroom));
        kv.put("density_curve_gamma", f("%.4f", densityGamma));
        kv.put("digital_intermediate", b(digitalIntermediate));
        kv.put("digital_intermediate_blue_compensation", b(diBlueComp));
        kv.put("output_cctf_encoding", b(outputCctf));
        kv.put("hue_correction", f("%.3f", wireHueCorrection(stock)));
        kv.put("scanner_black_correction", b(scannerBlack > 0.5f && !scannedPositive));
        // **Ilford Multigrade has no calibrated EDR tone map.** Sending
        // `extended_dynamic_range` with that paper makes `spk_open` fail
        // outright -- "print profile 'ilford_multigrade_iv_rc' has no
        // calibrated EDR tone map" -- and the frame never opens at all. The
        // switch stays where the user put it; it simply cannot apply here.
        kv.put("extended_dynamic_range",
                b(edrOn > 0.5f && !"ilford_multigrade_iv_rc".equals(paper)));
        kv.put("camera_filter", q(cameraFilter));
        // **The solved curve, when it is this stock's.** The fit is one stock at
        // a time -- the medium lives on the film as much as on the paper -- so a
        // shelf card printed with another stock keeps the slider's curve.
        final boolean slFit = slFitValid && slFitStock != null && slFitStock.equals(stock);
        kv.put("scene_latitude_active", b(slFit ? slFitActive : sceneLatitudeActive()));
        kv.put("scene_latitude_norm", q(sceneNorm));
        // **The manual curve outranks the solve.** Everything else the fit
        // returns is still used -- the shadow side in particular -- but the
        // three numbers the user is holding go out as they are.
        final boolean hlMan = hlManual && hlRoom > 0.01f;
        kv.put("scene_latitude_highlight_knee", f("%.2f", hlMan ? hlKnee : (slFit ? (float) slFitHk : wireHighlightKnee())));
        kv.put("scene_latitude_highlight_room", f("%.2f", hlMan ? hlRoom : (slFit ? (float) slFitHr : wireHighlightRoom())));
        kv.put("scene_latitude_shadow_knee", f("%.2f", slFit ? (float) slFitSk : wireShadowKnee()));
        kv.put("scene_latitude_shadow_room", f("%.2f", slFit ? (float) slFitSr : wireShadowRoom()));
        kv.put("scene_latitude_rolloff", f("%.2f", hlMan ? hlRolloff : shadowRolloff));
        kv.put("scene_latitude_max_lift", f("%.2f", maxLift));
        // **半格对和第二段曲线。** `split` 在不成对时发 0 —— 引擎拿 0 当
        // 「一格一套曲线」，和根本不发这个字段是同一件事。
        final boolean pair = pairActive();
        kv.put("overscan_pair", b(pair));
        kv.put("scene_latitude_split", f("%.4f", pair ? pairSplit : 0f));
        kv.put("scene_latitude_b_active", b(pair && pairTone));
        kv.put("scene_latitude_b_highlight_knee", f("%.2f", pairHighKnee));
        kv.put("scene_latitude_b_highlight_room", f("%.2f", pairHighRoom));
        kv.put("scene_latitude_b_shadow_knee", f("%.2f", pairShadowKnee));
        kv.put("scene_latitude_b_shadow_room", f("%.2f", pairShadowRoom));
        // RFC-024's contrast mask. `refreshLatitude` is idempotent and cheap;
        // calling it here means a tier restored from a look or typed into the
        // field is always the one that goes on the wire.
        refreshLatitude();
        kv.put("contrast_mask_active", b(latActive));
        kv.put("contrast_mask_highlights", f("%.2f", latHl));
        kv.put("contrast_mask_shadows", f("%.2f", latSh));
        kv.put("contrast_mask_core", f("%.2f", latCore));
        kv.put("contrast_mask_scale", f("%.3f", latScale));
        kv.put("contrast_mask_reach", f("%.2f", latReach));
        kv.put("glare_amount", f("%.3f", glareAmount));
        kv.put("film_format_mm", f("%.1f", wireFormatMm()));
        kv.put("lens_blur_um", f("%.1f", lensBlur));
        // **A zero-width crop is not a small crop, it is a blank frame.** The
        // renderer honours the rectangle it is given, so `crop_w == 0` (or a
        // rectangle pushed outside the frame) comes back as one flat colour --
        // every film card grey, the canvas grey, and no error anywhere. Clamp
        // to something that can actually contain pixels.
        final float cropW = Math.max(0.01f, Math.min(1f, geometryCropW));
        final float cropH = Math.max(0.01f, Math.min(1f, geometryCropH));
        final float cropX = Math.max(0f, Math.min(1f - cropW, geometryCropX));
        final float cropY = Math.max(0f, Math.min(1f - cropH, geometryCropY));
        kv.put("geometry_crop_x", f("%.6f", cropX));
        kv.put("geometry_crop_y", f("%.6f", geometryCropY));
        kv.put("geometry_crop_w", f("%.6f", cropW));
        kv.put("geometry_crop_h", f("%.6f", cropH));
        // **The engine turns the other way round.** `geometry_rotation_deg`
        // is counter-clockwise positive (measured: rendering +15 and undoing
        // it with PIL's +15 matches to 11.7/255, while -15 misses by 42.7),
        // and Android's `Canvas.rotate` is clockwise positive. The app keeps
        // the screen convention everywhere -- the gesture, the scale, the
        // reading, `Look` -- and flips the sign once, here and in
        // `sendGeometry`, at the boundary. Without it the picture turns one
        // way under the finger and comes back the other way when the render
        // lands, which is exactly "一松手，重新渲染完，照片变回原来位置了".
        kv.put("geometry_rotation_deg", f("%.3f", -geometryRotation));
        kv.put("geometry_quarter_turns", Integer.toString(geometryTurns));
        kv.put("geometry_flip_h", b(geometryFlipH));
        kv.put("geometry_flip_v", b(geometryFlipV));
        kv.put("m_filter_shift", f("%.3f", mFilter));
        kv.put("y_filter_shift", f("%.3f", yFilter));
        kv.put("filter_shift_scale", f("%.1f", filterScale));
        // **0..1 on the slider, 0..0.04 in the engine.** Measured on a real
        // frame: 0.05 already takes the top 5 % down by 24 %, and 0.5 by 65 %
        // -- the physics is not linear in the way the number suggested, so the
        // slider keeps only the usable end.
        kv.put("preflash_exposure", f("%.4f", preflash * 0.2f));
        // **A print frame is not a carrier this engine has.** The seven gauges the
        // second engine lays its own film on (Super 35 / 16 mm / Super 8 / 4x5 /
        // Instax) are `pf:` slots on the host; `spkGateId()` can only answer with
        // one of the ten rebate carriers. The picture, though, is still cropped to
        // the *print frame's* ratio, so sending `overscan_active` is a guaranteed
        // rejection -- measured here with a 1.263 crop:
        //
        //   spk_render failed (-5): overscan: a 900 x 504 frame is not the 135
        //   gate's shape (36.25 x 24.3); crop the picture to the gate first
        //
        // and the same line reached a user as 渲染失败 on 1.7.0 with Portra 800 --
        // a film only this engine has -- which reads as "SpektraLab 引擎用不了".
        // Switching back to a fotufilm stock worked because the host accepts the
        // print frame, which is exactly what made the report look film-specific.
        //
        // There is no border to draw here, so the frame renders bare; the gate
        // stays where it is and the second engine gets it back untouched.
        final boolean spkBorder = overscanOn
                && !(isPrintFrameGauge(overscanFormat) && !isFotuStock(stock));
        kv.put("overscan_active", b(spkBorder));
        kv.put("overscan_format", q(spkGateId()));
        kv.put("overscan_edge_text", q(edgeTextOn ? edgeTextFor(stock) : ""));
        kv.put("overscan_fog", f("%.2f", edgeFog));
        kv.put("overscan_leaks", f("%.2f", edgeLeaks));
        kv.put("overscan_frame_number", f("%.0f", frameNumber));
        kv.put("overscan_mode", q(edgeMode));
        kv.put("overscan_gate", q(edgeGate));
        kv.put("overscan_holes", q(edgeHoles));
        kv.put("overscan_carrier", q(edgeCarrier));
        kv.put("overscan_f_number", f("%.2f", edgeFNumber));
        kv.put("overscan_camera_seed", Integer.toString(cameraSeed));
        kv.put("overscan_frame_seed", Integer.toString(frameSeed));
        kv.put("date_imprint_active", b(dateOn));
        kv.put("date_imprint_text", q(dateOn ? imprintDate() : ""));
        kv.put("date_imprint_style", q(dateStyle));
        kv.put("date_imprint_text_b", q(dateTextB));
        kv.put("date_imprint_data_text", q(dataText));
        kv.put("date_imprint_placement", q(datePlacement));
        kv.put("date_imprint_corner", q(dateCorner));
        kv.put("date_imprint_inset_x", f("%.2f", dateInsetX));
        kv.put("date_imprint_inset_y", f("%.2f", dateInsetY));
        kv.put("date_imprint_size", f("%.2f", dateSize));
        kv.put("date_imprint_ev", f("%.1f", dateEv));
        // The user's own offset only. The meter's stops travel through the pin
        // (`pinAutoExposureEv`), which lands in the same node the canvas used.
        kv.put("exposure_compensation_ev", f("%.2f", cameraEv));

        // **What the look is, as one number.** The live preview is twenty-two
        // frames of engine time; keeping it across a slider drag would show the
        // previous look, and rebuilding it after every drag costs two seconds.
        // A hash of exactly the values we send answers "can this be kept" -- and
        // the print-only keys are skipped, because the preview draws no strip and
        // an export's `preview_long_edge` must not invalidate it.
        long lookHash = 1125899906842597L;
        for (java.util.Map.Entry<String, String> e : kv.entrySet()) {
            final String k = e.getKey();
            if (k.startsWith("preview_") || k.startsWith("overscan_") || k.startsWith("date_")) continue;
            lookHash = 31L * lookHash + k.hashCode() * 17L + e.getValue().hashCode();
        }
        lastLookHash = lookHash;
        // **Device rules run before the delta is computed**, so a rule's value
        // is the one that gets diffed and therefore the one the engine keeps.
        // Applied after would mean the engine holds the value the rule was
        // meant to override while the ledger says otherwise. The table is
        // empty today -- this is the socket, not a change.
        SelfHeal.applyRules(kv);
        final String delta = deltaFor(target, kv);
        if (delta == null) return false;
        try {
            DebugSink.text("params", "draw film=" + stock + " print=" + paper
                    + " render=" + rendering + " long=" + longEdge
                    + " keys=" + delta.split(",").length + " [" + keyNames(delta) + "]"
                    + " geo=" + kv.get("geometry_rotation_deg"));
        } catch (Throwable ignored) { }
        // **A JSON that does not parse is a build error, not a user error.**
        try {
            new org.json.JSONObject(delta);
        } catch (Throwable bad) {
            try { DebugSink.textNow("params-bad", bad + "\n" + delta); }
            catch (Throwable ignored) { }
        }
        try {
            target.setParams(delta);
        } catch (Throwable t) {
            // The engine may have applied none, some or all of it. Start over
            // from a full delta next time rather than assume.
            deltaSent.clear();
            deltaSession = null;
            throw t;
        }
        return true;
    }

    /** Same set, at whatever long edge the caller is rendering. The catalogue
     *  pass uses a small one so a whole shelf of films is affordable; a look
     *  the user is about to export still goes out at the preview size. */
    private void applyParams(int longEdge) {
        if (session == null) return;
        final String stock = filmStock;
        if (stock == null) return;
        // **With the stock, always.** `spk_set_params` decides to rebuild the
        // pipeline on `delta.has("film_stock") || delta.has("print_stock")` --
        // presence of the key, not a change in its value. The date back, the
        // rebate and every other SHOOT-layer field only reach the picture on
        // that rebuild, so a delta without the stock was written into the
        // parameter tree and then rendered with the old `pb_`: the date's size,
        // corner, style and exposure did nothing until the film was re-picked.
        // Sending it costs one profile read; not sending it costs the control.
        applyParams(stock, printStock == null ? "kodak_portra_endura" : printStock, longEdge);
    }

    /**
     * The half that describes the file: once per session, and after a stock
     * change.
     *
     * <p>`auto_exposure` is off for everything that is not a RAW. The engine's
     * default meter is `center_weighted`: an **arithmetic** mean of luminance
     * under a Gaussian centred on the frame, sigma 0.2 of the long edge (see
     * `exposure_evs_from` in the pipeline). An arithmetic mean is dominated by
     * whatever is brightest, so a frame whose middle is open sky meters about
     * three times mid-grey and the whole picture prints 1.7 stops down -- a
     * user sent exactly that screenshot: bright blue sky rendered as slate,
     * sunlit leaves rendered black.
     *
     * <p>A camera JPEG has already been metered once, by the camera, and that
     * decision is what the user sees in their gallery. Metering it a second
     * time is double-counting, and the two meters disagree by more than a stop
     * on exactly the pictures people take: sky, backlight, snow. With the
     * meter off the render starts from the file's own exposure, which is what
     * "import this photo" has to mean.
     *
     * <p>A RAW is scene-referred and has no exposure decision baked in, so it
     * keeps the meter. (`auto_exposure: false` makes the engine apply no EV at
     * all -- `pipeline.cpp` returns the input untouched.)
     */
    private void applySessionParams() {
        // **Retired.** It wrote the engine from whichever thread imported the
        // file, racing the render thread; and the delta bookkeeping is now a
        // map shared between renders, so "who may write it" has exactly one
        // answer. Every field it used to send (colour space, cctf decoding,
        // meter) is part of the full delta `renderImage` builds, and a new
        // session starts with an empty bookkeeping map -- so the first render
        // states all of it anyway.
    }

    /**
     * A mark every three seconds, from now until the thread is interrupted.
     *
     * A blocking native call is a black box: `session.renderBegin` can take
     * forty seconds on a 50 MP rebate canvas, and a process that dies inside it
     * leaves exactly one line -- `render:call` -- whether it died at second one
     * or second thirty-nine. The ticker turns "somewhere in there" into "after
     * 27 seconds", which is a different investigation.
     *
     * It writes through {@link CrashTrail#mark}, so a tick costs a commit only
     * when the throttle has expired; the thread is a daemon and is interrupted
     * in a `finally`, so it can never outlive the call it is watching.
     */
    private Thread startTick(final String tag, final SpektraLabEngine.Session s) {
        final Thread t = new Thread(() -> {
            int n = 0;
            String lastStage = null;
            int sameStage = 0;
            boolean warned = false;
            try {
                while (!Thread.currentThread().isInterrupted()) {
                    Thread.sleep(3000);
                    if (Thread.currentThread().isInterrupted()) return;
                    n += 3;
                    // **Which node, not just how long.** The engine publishes a
                    // 96-byte label from the render thread through a seqlock;
                    // this reads it without taking the render lock, so a render
                    // that has been inside `filming.expose.halation` for twenty
                    // seconds says so in the trail instead of just "20s".
                    String stage = null;
                    try { stage = s == null ? null : s.stageSnapshot(); } catch (Throwable ignored) { }
                    CrashTrail.mark(this, tag + ":tick " + n + "s"
                            + (stage == null || stage.isEmpty() ? "" : " @ " + stage));
                    // **A node that has not changed in fifteen ticks is stuck.**
                    // Total time is not the signal -- a 51 MP frame legitimately
                    // spends a minute inside one kernel -- so this watches the
                    // engine's own stage label. Fifteen ticks is 45 s.
                    //
                    // **Saved, not cancelled.** Resetting `rendering` here would
                    // let the next request call `renderBegin` while this one is
                    // still inside the device, and the two would interleave on
                    // the one native result buffer. What can be saved is the
                    // user's work: the look and the session go to disk, so a
                    // force-stop costs nothing but time.
                    if (stage != null && !stage.isEmpty()) {
                        if (stage.equals(lastStage)) ++sameStage;
                        else { sameStage = 0; lastStage = stage; }
                        if (!warned && sameStage >= 15) {
                            warned = true;
                            final String stuckAt = stage;
                            final int secs = n;
                            runOnUiThread(() -> onRenderStuck(tag, secs, stuckAt));
                        }
                    }
                }
            } catch (InterruptedException ignored) {
            } catch (Throwable ignored) { }
        }, "tick-" + tag);
        t.setDaemon(true);
        t.start();
        return t;
    }

    private static void stopTick(Thread t) {
        if (t != null) t.interrupt();
    }

    /**
     * A render that has not moved an engine node in 45 seconds.
     *
     * <p>**Nothing is cancelled here, and that is deliberate.** Resetting
     * `rendering` would let the next request call `renderBegin` while this one
     * is still inside the device; the two would interleave on the one native
     * result buffer, and the app would either show another frame's dimensions
     * or die. A native render cannot be interrupted from Java -- `spk_render`
     * is a blocking call that owns the lock.
     *
     * <p>What can be saved is the user's work. The look and the session go to
     * disk immediately, so a force-stop costs a minute of waiting and nothing
     * else, and the status line says where it stopped instead of leaving a
     * spinner running for ever.
     */
    private void onRenderStuck(String tag, int seconds, String stage) {
        try { saveLookIntoFrames(); } catch (Throwable ignored) { }
        try { saveSessionState(); } catch (Throwable ignored) { }
        SelfHeal.repaired("render-stuck", tag + " " + seconds + "s @ " + stage);
        CrashTrail.markNow(this, "stuck:" + tag + " " + seconds + "s @ " + stage);
        if (statusText != null) {
            statusText.setText("渲染停在 " + stage + " 已 " + seconds + " 秒 · 参数已保存");
        }
    }

    // ── live preview ───────────────────────────────────────────────

    /**
     * A slider moved. Ask for a picture.
     *
     * <p>Called from `onProgressChanged`, so it runs a hundred times a second
     * while a thumb is down. Everything here is a flag: the drawing happens on
     * `liveLoop`, one frame at a time, and requests that arrive mid-frame are
     * folded into the next one. Nothing is queued, so a fast drag cannot build
     * a backlog it will spend the rest of the gesture draining.
     *
     * <p>It deliberately does not draw while `rendering`: a full-size pass
     * holds `renderMutex` for two to four seconds, and a live frame started
     * now would simply wait behind it and then paint 800 px over the 2048 px
     * result. The next move asks again.
     */
    /** The field names inside a delta, for one readable log line. */
    private static final java.util.regex.Pattern KEY_IN_DELTA =
            java.util.regex.Pattern.compile("\"([A-Za-z0-9_]+)\":");
    private static String keyNames(String delta) {
        final java.util.regex.Matcher m = KEY_IN_DELTA.matcher(delta);
        final StringBuilder out = new StringBuilder();
        while (m.find()) {
            if (out.length() > 0) out.append(',');
            out.append(m.group(1));
        }
        return out.toString();
    }

    /** FNV-1a over the pixels, the same shape the preview log uses. */
    private static long pixelHash(int[] pixels, int size) {
        long h = 1469598103934665603L;
        for (int i = 0; i < size; i += 7) { h ^= pixels[i]; h *= 1099511628211L; }
        return h;
    }

    /** One line a second is enough to tell "blocked" from "never called". */
    private long lastLiveLog = 0;
    private void liveLog(String what) {
        final long now = nowMs();
        if (now - lastLiveLog < 1000) return;
        lastLiveLog = now;
        try { DebugSink.text("live", what); } catch (Throwable ignored) { }
    }

    private void requestLivePreview() {
        // **The second engine does have a cheaper tier**: the 800 px frame its
        // own panel drags with, about a fifth of a second. The 光学 page used to
        // get nothing at all -- the picture only arrived on release.
        if (isFotuStock(filmStock)) {
            requestFotuLive(false);
            scheduleFotuSettle();
            return;
        }
        if (!uiReady || appPaused || session == null || filmStock == null) {
            liveLog("blocked state ui=" + uiReady + " paused=" + appPaused
                    + " session=" + (session != null) + " film=" + filmStock);
            return;
        }
        if (wbDecoding) {
            liveLog("blocked wb");
            return;
        }
        // **A full-size render in flight is not a reason to drop the frame.**
        // It used to `return` here, and since a 2048 render takes ~1.4 s while a
        // drag lasts about as long, every request of the whole gesture landed
        // inside one and was thrown away -- "the number moves and the picture
        // does not", on exactly the print-layer sliders that were supposed to be
        // the fast ones. `drawLivePreview` already takes `renderMutex` and
        // re-checks `fullGeneration` inside it, so queueing is safe: the live
        // frame waits for the full one to finish and paints immediately after.
        // Dragging a slider while the canvas shows the source means "show me
        // what this does", so the canvas has to be showing the print.
        if (showingOriginal) {
            showingOriginal = false;
            setOriginalVisual(false);
        }
        // The shelf's queue renders other stocks into the same session; a live
        // frame would land between two cards and be overwritten by the next
        // one. A gesture is the user editing, which outranks the catalogue.
        liveLog("request ok");
        liveLastInput = nowMs();
        stopPrefetch();
        if (liveThread == null) {
            liveThread = new Thread(this::liveLoop, "live-preview");
            liveThread.setDaemon(true);
            liveThread.start();
        }
        liveWanted = true;
        synchronized (liveLock) { liveLock.notifyAll(); }
    }

    /**
     * Drop whatever a live frame is about to paint.
     *
     * <p>A full-size render is starting, or the photograph is changing. The
     * frame already inside `renderBegin` cannot be interrupted -- it will
     * finish and then throw its bitmap away, which is exactly what the
     * generation check is for.
     */
    private void cancelLivePreview() {
        liveGeneration.incrementAndGet();
        liveWanted = false;
    }

    private void liveLoop() {
        while (true) {
            synchronized (liveLock) {
                while (!liveWanted) {
                    try { liveLock.wait(); } catch (InterruptedException e) { return; }
                }
            }
            // Let the gesture settle for a moment: every request that arrives
            // during this sleep folds into the frame that follows.
            final long since = nowMs() - liveLastStart;
            if (since < LIVE_MIN_GAP_MS) {
                try { Thread.sleep(LIVE_MIN_GAP_MS - since); } catch (InterruptedException e) { return; }
            }
            liveWanted = false;
            if (session == null || filmStock == null || wbDecoding) continue;
            // The release that ended the drag has already started the full-size
            // pass. It sets `rendering` before it takes the lock, so this is the
            // cheap chance to stay out of its way instead of spending 0.4 s of
            // its time on a frame it is about to replace.
            if (rendering) continue;
            liveLastStart = nowMs();
            // Still moving? Then the frame that matters is the next one, not the
            // prettiest one: 560 until the input stops, 800 for the last frame.
            final boolean moving =
                    nowMs() - liveLastInput < LIVE_SETTLE_MS;
            // **A drag frame does not carry the glow.** That is a whole extra
            // pass over the frame (60-100 ms at 800 px) for a look the slider
            // under the finger is not changing; the settled frame -- 260 ms
            // after the input stops -- puts it back.
            drawLivePreview(moving ? LIVE_DRAG_EDGE : LIVE_LONG_EDGE, !moving);
        }
    }

    /**
     * One frame at `LIVE_LONG_EDGE`, on the same lock, with the same delta a
     * full render sends -- stock and paper included.
     *
     * <p>**The delta is sent here, from this thread, inside `renderMutex`,
     * immediately before `renderBegin`.** That is the one rule the 1.5.0l fix
     * rests on (`applyParams()` on the UI thread is a log line, not a writer):
     * `spk_set_params` takes the session lock, `render_tier` holds it for the
     * whole render, and a delta sent from the UI thread parks the main thread
     * behind a live render -- the exact stack that used to take Adreno 730
     * down mid-drag.
     *
     * <p>Nothing else here is the full path's job. No JPEG to the sink, no
     * progress json, no undo entry, no persist: this bitmap lives until the
     * next frame replaces it.
     */
    private void drawLivePreview() { drawLivePreview(LIVE_LONG_EDGE, true); }

    private void drawLivePreview(int edge) { drawLivePreview(edge, true); }

    /** @param withGlow false while a finger is down -- see the call in `liveLoop`. */
    private void drawLivePreview(int edge, boolean withGlow) {
        final SpektraLabEngine.Session s = session;
        final String stock = filmStock;
        if (s == null || stock == null) return;
        // **Read the generation, never advance it here.**
        //
        // `runOnUiThread` only posts; this method returns immediately and the
        // loop starts the next frame, whose `++` lands microseconds later. The
        // UI thread then compares against a counter that has already moved past
        // the frame it was handed and drops it -- measured at 18 of 20 frames
        // thrown away, which is exactly "the number changes and the picture does
        // not". Advancing on cancel alone keeps the invalidation the caller
        // actually means: stop showing frames from before the user let go.
        final int gen = liveGeneration.get();
        final int fullGen = fullGeneration.get();
        final int frame = currentFrame;
        final String paper = printStock == null ? "kodak_portra_endura" : printStock;
        Bitmap bmp = null;
        long liveHash = 0;
        int[] liveBins = null;
        synchronized (renderMutex) {
            // `renderImage` may have taken the session while this frame was
            // waiting for the lock.
            if (s != session || fullGen != fullGeneration.get()) return;
            try {
                // **Two ways to answer an edit, and the cheap one is most of
                // them.**
                //
                // The delta only names what moved. When it comes out empty the
                // session already holds exactly this parameter set, so the last
                // engine result is still the right frame -- and the whole 光学
                // page (exposure, contrast, highlights, shadows, HSL, curves,
                // grading, sharpen, texture, vignette) lives *inside*
                // `copyArgbRange`, as pixel maths over that result. Re-reading
                // it is 8 ms where a render is 50-150 ms on a mid-range phone,
                // and it is the same picture: nothing about the film changed.
                //
                // When the delta is not empty it is a reprint: only the print
                // side runs, the cached negative is untouched, and a
                // shoot-layer field drops that cache inside `spk_set_params`
                // itself, so a full develop only ever happens on the sliders
                // that genuinely need one (grain, halation, geometry, rebate).
                final boolean touched = applyParams(stock, paper, edge);
                final long liveStart = nowMs();
                int[] dims = touched ? null : s.resultSize();
                // {w, h, isSource} -- a source export is the *decoded frame*
                // in the same slot, and re-reading that under a print's
                // controls would paint the negative.
                if (dims != null && dims.length > 2 && dims[2] != 0) dims = null;
                final boolean reused = dims != null && dims[0] > 0 && dims[1] > 0;
                if (!reused) dims = s.renderBegin("live", true);
                final int w = dims[0], h = dims[1];
                if (w <= 0 || h <= 0) throw new RuntimeException("empty live frame");
                if (livePixels == null || livePixels.length < w * h) livePixels = new int[w * h];
                final int copied = s.copyArgbRange(livePixels, 0, h);
                if (copied != w * h) throw new RuntimeException("live copy " + copied + "/" + (w * h));
                bmp = newFrameBitmap(w, h);
                bmp.setPixels(livePixels, 0, w, 0, 0, w, h);
                // The settled frame carries the glow; a drag frame does not.
                // It is a second full pass over the pixels (60-100 ms) and the
                // look it adds is not what the finger is changing.
                if (withGlow) glowInPlace(bmp);
                // **The result is kept, not released.** `renderEnd` frees it,
                // and the next frame may want to read it again for free. The
                // next `renderBegin` replaces it anyway, so the only cost is
                // one frame's worth of pixels (1 MB at a drag size) living a
                // moment longer.
                if (touched) {
                    try { rememberAppliedEv(s.progressJson(), "live"); } catch (Throwable ignored) { }
                }
                liveHash = pixelHash(livePixels, w * h);
                // **The histograms move with the picture, not with the render
                // size.** Both of them used to wait for a full 2048 render, so
                // a drag left them frozen on the previous frame. Every third
                // live frame is enough to read as continuous and costs a
                // fraction of the frame's own budget (a strided count over an
                // array that already exists, never a Bitmap).
                if (histogram != null && (++liveHistCounter % 3) == 0)
                    liveBins = HistogramView.computeBins(livePixels, w, h);
                try { DebugSink.text("live", "frame " + w + "x" + h + " "
                        + (nowMs() - liveStart) + " ms edge=" + edge
                        + (withGlow ? " glow" : "") + (reused ? " reuse" : "")
                        + " " + Long.toHexString(liveHash)); }
                catch (Throwable ignored) { }
            } catch (Throwable t) {
                try { s.renderEnd(); } catch (Throwable ignored) { }
                try { DebugSink.text("live", "fail " + describe(t)); } catch (Throwable ignored) { }
                return;
            }
        }
        final Bitmap out = bmp;
        final long hash = liveHash;
        final int[] histBins = liveBins;
        runOnUiThread(() -> {
            if (!uiReady || gen != liveGeneration.get()) {
                liveLog("drop: superseded");
                return;
            }
            if (fullGen != fullGeneration.get()) {
                liveLog("drop: a full render started");
                return;
            }
            if (frame != currentFrame) {
                liveLog("drop: frame changed");
                return;
            }
            if (session == null || compare == null) {
                liveLog("drop: no session/canvas");
                return;
            }
            lastRenderedBitmap = out;
            compare.setAfter(out);
            setStage(1, null);
            // Only a frame that is actually shown updates the bins; a dropped
            // one describes a picture the canvas never had.
            if (histBins != null && histogram != null) histogram.applyBins(histBins);
            // The other half of the comparison: `frame` says what was produced,
            // this says what the canvas was handed. If they disagree the loss is
            // between the two, not in the render.
            try { DebugSink.text("live", "canvas " + out.getWidth() + "x" + out.getHeight()
                    + " " + Long.toHexString(hash)); } catch (Throwable ignored) { }
        });
    }

    /**
     * Hand the GPU pool back when a render left it much larger than the frame.
     *
     * <p>**Shoot-layer edits are the expensive ones.** Each one drops the cached
     * negative, so `run_film` allocates a new set of planes and the pool keeps
     * them for the next render. One edit is fine; ten in a row (which is what a
     * switch that "does nothing" invites) leaves gigabytes parked, and Android
     * answers by killing the launcher. Trimming costs one re-allocation on the
     * next render, which is far cheaper than that.
     */
    private void trimPoolIfBloated() {
        if (engine == null) return;
        try {
            final String report = engine.memoryReport();
            // `"total":N` is the pool's own byte count.
            final int at = report.indexOf("\"total\":");
            if (at < 0) return;
            int i = at + 8;
            final StringBuilder digits = new StringBuilder();
            while (i < report.length() && Character.isDigit(report.charAt(i))) digits.append(report.charAt(i++));
            if (digits.length() == 0) return;
            final long total = Long.parseLong(digits.toString());
            if (total > (1536L << 20)) {
                // **Under the render lock.** Trimming destroys device buffers;
                // a render that starts between the measurement and the trim
                // would hand the GPU memory that is being freed.
                long freed;
                synchronized (renderMutex) { freed = engine.trimPool(); }
                try { DebugSink.text("pool-trim",
                        "after render: total was " + (total >> 20) + " MB, freed "
                                + (freed >> 20) + " MB"); } catch (Throwable ignored) { }
            }
        } catch (Throwable ignored) { }
    }

    // ── fotufilm: the second engine ──────────────────────────────────────

    /**
     * Long edge the second engine renders the canvas at.
     *
     * <p>Its chain is one CPU pass and there is no cheaper tier to fall back
     * on: 2048 is ~2 s on this class of phone, 1600 would save a third of a
     * second and look mushy. Export asks for 0, which is the photograph's own
     * size.
     */
    private static final int FOTU_PREVIEW_EDGE = 2048;
    /** A card is 86 dp wide, so 320 px of long edge is already more than a screen shows. */
    private static final int FOTU_CARD_EDGE = 320;
    /**
     * A live frame: the first engine's live tier, a notch up.
     *
     * <p>With the rebate on, the canvas is the frame plus its margins and the
     * host budgets for that -- but the engine drops the edge print entirely on
     * canvases under 900 px, and 800 of *frame* is a ~835 px canvas for 135.
     * At 900 the live frame keeps its own print, so toggling the strip does not
     * make the words vanish until the full render lands.
     */
    private static final int FOTU_LIVE_EDGE = 900;
    /**
     * The edge a fotufilm live frame uses while the finger is moving.
     *
     * <p>Its chain has no tiers: every frame is a full develop, so the only
     * lever is how many pixels go through it. Measured on this device, a steady
     * frame costs 300 ms at 900, 185 at 640 and 108 at 512; 560 is the point
     * where a drag still reads at about seven frames a second and,
     * being under the rebate's own 720 px floor, it also skips laying the strip
     * — which is a second full pass over the canvas. The frame after the finger
     * stops is 900 with the strip, so nothing is lost but the wait.
     */
    /**
     * fotufilm 拖动时那一帧的长边。
     *
     * <p>内核是 CPU 的 Halide AOT（已 3.06× 并行，没有余量），所以和第一引擎
     * 一样，唯一有效的杠杆是像素数：`fh_bench` 稳态 560 → 94 ms、420 → 42 ms
     * （缓存的表和 SceneCache 都命中）。停手之后仍补一张 {@link #FOTU_LIVE_EDGE}。
     */
    private static final int FOTU_DRAG_EDGE = 420;
    /** Below this the strip is not drawn: on a drag frame it is a 6% band of mush. */
    private static final int FOTU_REBATE_MIN_EDGE = 720;
    private boolean fotuLiveSettled;
    private final android.os.Handler uiHandler =
            new android.os.Handler(android.os.Looper.getMainLooper());

    /**
     * Which engine a stock belongs to.
     *
     * <p>Deliberately **not** {@code FotuFilm.isFotu}: a static method call on
     * that class runs its initialiser, which loads two native libraries. If a
     * device ever refuses one of them the class is left in an erroneous state
     * and every later call throws {@link NoClassDefFoundError}; this predicate
     * sits on the launch path (the paper label), so it must not be able to
     * throw. The prefix is a compile-time constant and the test is a
     * `startsWith`.
     */
    private static boolean isFotuStock(String stock) {
        return stock != null && stock.startsWith("fotu:");
    }

    /** The medium this frame is printed through, always one the stock allows. */
    private String fotuMedium() {
        return fotuMediumFor(FotuFilm.idOf(filmStock));
    }

    /** The medium a given stock would print on, without moving the canvas'. */
    private String fotuMediumFor(String id) {
        final FotuFilm.Stock stock = fotuStocks.get(id);
        if (stock == null) return FotuFilm.defaultMedium(id);
        if (FotuFilm.indexOfMedium(printStock) >= 0
                && FotuFilm.mediaFor(stock).contains(printStock)) {
            return printStock;
        }
        return FotuFilm.defaultMedium(id);
    }

    /**
     * The card's caption for a film only the second engine carries.
     *
     * <p>The first engine's catalogue names its stocks in full ("Fujifilm
     * C200"), so its cards do too; this shelf sits in the same row and reads
     * wrong beside them when it says "Superia 200". The maker is taken from the
     * same buckets the tabs use, and only for the four names a wordmark can
     * carry -- "AR-5" and "Creative" are emulsion codes, not makers, and a card
     * must not turn "Kodak Aerochrome 1443" into "AR-5 Kodak Aerochrome".
     */
    private String fotuCardCaption(int index) {
        if (index < 0 || index >= fotuNames.size()) return "";
        String name = fotuNames.get(index);
        final String bucket = brandOf(FotuFilm.PREFIX + fotuIds.get(index));
        final String brand = "kodak".equals(bucket) ? "Kodak"
                : "fujifilm".equals(bucket) ? "Fujifilm"
                : "ilford".equals(bucket) ? "Ilford"
                : "cinestill".equals(bucket) ? "CineStill" : null;
        if (brand != null && !name.regionMatches(true, 0, brand, 0, brand.length())) {
            name = brand + " " + name;
        }
        final String mark = fotuKinds.get(index);
        return mark == null || mark.isEmpty() ? name : name + " · " + mark;
    }

    /**
     * The table cache.
     *
     * <p>Three tables per (stock, medium) are 561 KB each and building them
     * costs 0.5 s of the chain. They are pure functions of the pair, so they
     * survive between renders, and a card is 100 ms with them against 250-450
     * without -- measured on the whole 29-card shelf, cold against warm.
     *
     * <p>**The cap has to be larger than one shelf.** Each (stock, medium) is
     * three files and the shelf itself is 29 of them: 87 files, 48 MB. At
     * ninety-six the very next render on another medium -- the canvas is one
     * more -- evicted the oldest entries, so the following pass rebuilt what it
     * had just thrown away and every card paid the full 450 ms again. 160 holds
     * the whole shelf plus the handful of media a session actually touches.
     */
    private String fotuTableCache() {
        final java.io.File dir = new java.io.File(getCacheDir(), "fotu-tables");
        if (!dir.isDirectory() && !dir.mkdirs()) return null;
        final java.io.File[] files = dir.listFiles();
        if (files != null && files.length > 160) {
            java.util.Arrays.sort(files,
                    (a, b) -> Long.compare(a.lastModified(), b.lastModified()));
            for (int i = 0; i < files.length - 160; ++i) files[i].delete();
        }
        return dir.getAbsolutePath();
    }

    /**
     * The unpacked resources: 32 MB of skeletons, tables and decoders' data.
     *
     * <p>Only the skeletons this shelf can actually reach ship: a stock that is
     * printed on negative paper has no use for the two Ilfochrome ones, and a
     * transparency has no use for any negative sheet. That leaves 368 of the
     * 564 the engine was baked with, fourteen megabytes that used to be copied
     * into private storage on every upgrade so that nothing could ever open
     * them.
     *
     * <p>Copied once per installed build, because native code opens these by
     * path and a zip inside an APK is not a file system. Keyed by the version
     * code so an upgrade refreshes them.
     */
    private static final Object FOTU_ASSET_LOCK = new Object();

    private String ensureFotuRoot() throws java.io.IOException {
        if (fotuRoot != null) return fotuRoot;
        // Two callers can arrive together (a render and the push menu's first
        // open); two writers into the same FileOutputStream is a corrupt asset,
        // and the marker would then make it permanent.
        synchronized (FOTU_ASSET_LOCK) {
            if (fotuRoot != null) return fotuRoot;
            final java.io.File dir = new java.io.File(getFilesDir(), "fotufilm");
            final long t0 = nowMs();
            FotuFilm.unpack(this, dir, bundleVersion() + "-e");
            fotuRoot = dir.getAbsolutePath();
            fotuAssetsReady = true;
            try {
                DebugSink.text("fotufilm", "resources ready in "
                        + (nowMs() - t0) + " ms at " + fotuRoot);
            } catch (Throwable ignored) { }
            return fotuRoot;
        }
    }

    /** A quiet unpack for the first tap on a fotufilm stock. */
    private void ensureFotuRootAsync(final Runnable after) {
        statusText.setText("准备 fotufilm 资源（首次约 32 MB）…");
        new Thread(() -> {
            String failure = null;
            try { ensureFotuRoot(); } catch (Throwable t) { failure = String.valueOf(t); }
            final String said = failure;
            runOnUiThread(() -> {
                if (said != null) {
                    showErrorDialog("fotufilm 资源解包失败", said);
                    return;
                }
                statusText.setText("fotufilm 就绪");
                if (after != null) after.run();
            });
        }, "SpektraLab-fotu-assets").start();
    }

    /**
     * The file this photograph is rendered from.
     *
     * <p>The engine takes a path, not a descriptor: it decodes with its own
     * codecs. A RAW already has one (`rawFilePath`, the copy every full export
     * re-reads); a JPEG may still be a `content://` grant, so it is copied to
     * `filesDir/import` the same way the RAW path does and remembered for the
     * frame.
     */
    private String fotuSourceFile() {
        String path = null;
        // **A copy belongs to one photograph.** The path alone is not enough:
        // `files/import/<name>` is derived from the file name, and a name can
        // come back (a second card, the same export twice) -- and a path that
        // outlived its import would otherwise develop the *previous* picture
        // while the canvas says this one. Reported as 「用 fotu 会显示删除的
        // 图片，当前的图片不加载」, gone after a cold start for the obvious
        // reason.
        final String wantFor = sourceUri == null ? null : sourceUri.toString();
        if (fotuSourcePath != null && wantFor != null && wantFor.equals(fotuSourcePathFor)
                && new java.io.File(fotuSourcePath).isFile()) path = fotuSourcePath;
        else if (rawFilePath != null) path = rawFilePath;
        else if (sourceUri != null) {
            // **One attempt per frame, not one per card.** The shelf asks for
            // this path once for every film it draws; a grant that cannot be
            // copied used to be re-copied twenty five times in a row, each try
            // writing and deleting the same few megabytes, and each printing
            // 「读不到原图文件」 in the log. A re-import
            // clears this, because it clears `fotuSourcePath`.
            if (!sourceUri.toString().equals(fotuSourceDead)) {
                path = getFilePathFromUri(sourceUri);
                if (path == null) fotuSourceDead = sourceUri.toString();
            }
        }
        if (path == null) return null;
        final java.io.File file = new java.io.File(path);
        if (!file.isFile() || file.length() <= 0) {
            try { DebugSink.text("fotufilm", "source missing or empty: " + path); }
            catch (Throwable ignored) { }
            return null;
        }
        // **A raw is the engine's own business.** Its codecs carry libraw, and a
        // JPEG stand-in would throw away the whole point of the file.
        final boolean raw = rawFilePath != null && path.equals(rawFilePath);
        // **Ask the bytes, not the name.** The engine read
        // `1000036421.jpg` and answered "HEIF support is not part of this
        // build": the file is a HEIC that arrived with a .jpg name (the
        // picker, QQ and the screenshot tools all do this). Its codecs were
        // trimmed of HEIF and never had WebP, so the only reliable test is the
        // header. The canvas already holds the pixels, so those are handed over
        // instead -- once per frame, and said out loud in the log.
        if (!raw && !fotuReadable(path)) {
            final String stand = fotuStandInSource(fotuSniff(path));
            if (stand == null) return null;
            path = stand;
        }
        fotuSourcePath = path;
        fotuSourcePathFor = wantFor;
        return path;
    }

    /** What a file actually is, from its first sixteen bytes. */
    private static String fotuSniff(String path) {
        try (java.io.FileInputStream in = new java.io.FileInputStream(path)) {
            final byte[] h = new byte[16];
            int n = 0;
            while (n < h.length) {
                final int got = in.read(h, n, h.length - n);
                if (got <= 0) break;
                n += got;
            }
            if (n >= 2 && (h[0] & 0xFF) == 0xFF && (h[1] & 0xFF) == 0xD8) return "jpeg";
            if (n >= 4 && (h[0] & 0xFF) == 0x89 && h[1] == 'P' && h[2] == 'N' && h[3] == 'G') return "png";
            if (n >= 4 && ((h[0] == 'I' && h[1] == 'I' && h[2] == 0x2A && h[3] == 0x00)
                    || (h[0] == 'M' && h[1] == 'M' && h[2] == 0x00 && h[3] == 0x2A))) return "tiff";
            if (n >= 12 && h[4] == 'f' && h[5] == 't' && h[6] == 'y' && h[7] == 'p') {
                final String brand = new String(h, 8, 4, java.nio.charset.StandardCharsets.US_ASCII);
                return "crx ".equals(brand) ? "cr3"
                        : "ftyp:" + brand.trim().toLowerCase(java.util.Locale.US);
            }
            if (n >= 12 && h[0] == 'R' && h[1] == 'I' && h[2] == 'F' && h[3] == 'F'
                    && h[8] == 'W' && h[9] == 'E' && h[10] == 'B' && h[11] == 'P') return "webp";
            if (n >= 4 && h[0] == 'F' && h[1] == 'U' && h[2] == 'J' && h[3] == 'I') return "raf";
            if (n >= 4 && h[0] == 'F' && h[1] == 'O' && h[2] == 'V' && h[3] == 'b') return "x3f";
            if (n >= 4 && h[0] == 'I' && h[1] == 'I' && h[2] == 'U' && h[3] == 0x00) return "rw2";
            if (n >= 4 && h[0] == 'I' && h[1] == 'I' && h[2] == 'R') return "orf";
        } catch (Throwable ignored) { }
        return "";
    }

    /** Containers the second engine's own codecs can open. Anything else --
     *  HEIF under any brand, WebP, or a header we cannot name -- is decoded by
     *  the platform instead and handed over as pixels. */
    private static boolean fotuReadable(String path) {
        final String kind = fotuSniff(path);
        return kind.equals("jpeg") || kind.equals("png") || kind.equals("tiff")
                || kind.equals("cr3") || kind.equals("raf") || kind.equals("x3f")
                || kind.equals("rw2") || kind.equals("orf");
    }

    /** The canvas' decode, written out as a JPEG the engine can read. One per
     *  frame: the pixels do not change between sliders, and the file is swept
     *  from the cache on the next launch. */
    private String fotuStandInSource(String kind) {
        if (beforeBitmap == null) return null;
        final java.io.File out = new java.io.File(getCacheDir(),
                "fotu-src-" + System.currentTimeMillis() + ".jpg");
        try (java.io.FileOutputStream stream = new java.io.FileOutputStream(out)) {
            if (!beforeBitmap.compress(android.graphics.Bitmap.CompressFormat.JPEG, 95, stream)) {
                out.delete();
                return null;
            }
        } catch (Throwable t) {
            out.delete();
            return null;
        }
        try {
            DebugSink.text("fotufilm", "source " + getFileName(sourceUri)
                    + " is " + (kind == null || kind.isEmpty() ? "not a container the codecs read" : kind)
                    + ": re-encoded to JPEG " + beforeBitmap.getWidth() + "x" + beforeBitmap.getHeight());
        } catch (Throwable ignored) { }
        return out.getAbsolutePath();
    }

    /**
     * What the panel's direct controls ask the configuration for.
     *
     * <p>Empty at rest, so a frame nobody touched sends nothing and the engine's own calibration
     * stands. Grammar: `N=v` writes, `mul:N=v` multiplies, `add:N=v` offsets.
     */
    private String fotuSlots(String stockId, String root) {
        return fotuSlots(stockId, root, true, "");
    }

    private String fotuSlots(String stockId, String root, boolean withGrain) {
        return fotuSlots(stockId, root, withGrain, "");
    }

    /** One more verb on the end, when there is one. */
    private static String withSlot(String base, String extra) {
        if (extra == null || extra.isEmpty()) return base;
        return base.isEmpty() ? extra : base + ";" + extra;
    }

    private String fotuSlots(String stockId, String root, boolean withGrain, String extra) {
        return fotuSlots(stockId, root, withGrain, extra, true);
    }

    private String fotuSlots(String stockId, String root, boolean withGrain, String extra,
                             boolean withRebate) {
        // The grain model's tiles, when the panel asks for them: the population the reference
        // laid them from is ten kilobytes, and the host lays the same thirteen megabytes here.
        if (withGrain && fotuFilmGrain) {
            final java.io.File records = new java.io.File(root, "records-" + stockId + ".txt");
            if (records.isFile()) {
                final StringBuilder g = new StringBuilder(fotuSlots(withRebate));
                if (g.length() > 0) g.append(';');
                g.append("grain:").append(records.getAbsolutePath());
                if (Math.abs(fotuGrainSize - 1f) > 1e-4f)
                    g.append(";grainsize:").append(f("%.3f", fotuGrainSize));
                if (Math.abs(fotuGrainColour - 1f) > 1e-4f)
                    g.append(";graincolour:").append(f("%.3f", fotuGrainColour));
                if (Math.abs(fotuGrainSoft - 1f) > 1e-4f)
                    g.append(";grainsoft:").append(f("%.3f", fotuGrainSoft));
                if (Math.abs(fotuGrainR - 1f) > 1e-4f || Math.abs(fotuGrainG - 1f) > 1e-4f
                        || Math.abs(fotuGrainB - 1f) > 1e-4f)
                    g.append(";grainlayers:").append(f("%.3f", fotuGrainR)).append(',')
                     .append(f("%.3f", fotuGrainG)).append(',').append(f("%.3f", fotuGrainB));
                return withSlot(g.toString(), extra);
            }
        }
        // **The blurred clump has its own size, and it lives in the configuration.**
        //
        // Without the tile model (the default) the grain is a Poisson field blurred to the
        // clump's size, so `grainsize:` -- which moves FILM_TILE's pitch -- changed nothing and
        // the slider read as broken. `grainscale:` moves that field's sigma and radius, and drops
        // its density with the square, which is the same knob in physical terms.
        final StringBuilder plain = new StringBuilder(fotuSlots(withRebate));
        if (Math.abs(fotuGrainSize - 1f) > 1e-4f) {
            if (plain.length() > 0) plain.append(';');
            plain.append("grainscale:").append(f("%.3f", fotuGrainSize));
        }
        return withSlot(plain.toString(), extra);
    }

    /** The view layer's numbers, as the host's `view:` slot. */
    private String fotuViewSlot() {
        final double[] v = viewAdjustValues();
        boolean any = false;
        for (double x : v) if (Math.abs(x) > 1e-6) { any = true; break; }
        if (!any) return "";
        final StringBuilder b = new StringBuilder("view:");
        for (int i = 0; i < v.length; ++i) {
            if (i > 0) b.append(',');
            b.append(f("%.4f", (float) v[i]));
        }
        return b.toString();
    }

    /**
     * The view layer's five curves as the host's `curves:` slot.
     *
     * <p>Five channels x eight control points, unused points sent as `-1` -- the
     * same packing `nativeSetViewCurves` takes, so the host builds the tables
     * with the engine's own monotone cubic. Empty while every channel is the
     * identity, which leaves the develop untouched.
     */
    private String fotuCurveSlot() {
        boolean any = false;
        for (int ch = 0; ch < 5; ++ch) {
            final java.util.List<float[]> pts = curvePoints[ch];
            if (pts == null || pts.size() != 2) { any = true; break; }
            final float[] a = pts.get(0), b = pts.get(1);
            if (Math.abs(a[0]) > 1e-4f || Math.abs(a[1]) > 1e-4f
                    || Math.abs(b[0] - 1f) > 1e-4f || Math.abs(b[1] - 1f) > 1e-4f) {
                any = true;
                break;
            }
        }
        if (!any) return "";
        final StringBuilder out = new StringBuilder("curves:");
        boolean first = true;
        for (int ch = 0; ch < 5; ++ch) {
            final java.util.List<float[]> pts = curvePoints[ch];
            for (int i = 0; i < 8; ++i) {
                if (!first) out.append(',');
                first = false;
                if (pts != null && i < pts.size()) {
                    out.append(f("%.5f", pts.get(i)[0])).append(',')
                       .append(f("%.5f", pts.get(i)[1]));
                } else {
                    out.append("-1,0");
                }
            }
        }
        return out.toString();
    }

    private String fotuSlots() {
        return fotuSlots(true);
    }

    /**
     * @param withRebate false for a shelf card.
     *
     * <p>A card is {@code FOTU_CARD_EDGE} across. The strip is then a thirty
     * pixel band -- the host drops the print on canvases under 900 px anyway --
     * and the picture inside it a third smaller than the card it is drawn on.
     * The cards show the frame; the strip belongs to the canvas and the export.
     */
    private String fotuSlots(boolean withRebate) {
        final StringBuilder b = new StringBuilder();
        if (Math.abs(fotuGrain - 1f) > 1e-4f) {
            // The three layers' amplitudes, each scaled by the same multiplier.
            for (int i = 0; i < 3; ++i) {
                if (b.length() > 0) b.append(';');
                b.append("mul:").append(30 + i).append('=').append(f("%.4f", fotuGrain));
            }
        }
        if (fotuPreflash > 1e-5f) {
            if (b.length() > 0) b.append(';');
            b.append("18032=").append(f("%.5f", fotuPreflash));
        }
        // **The fringe is a pair, not a slot.** `chromaticFringeAmount` alone changes
        // nothing: the engine only lays a fringe when its radius reaches past the
        // coating's own coupler diffusion, and it writes sigma and radius beside the
        // amount. Writing 18026 on its own was a slider that did not move a pixel.
        if (fotuEncodedGrade > 0.5f) {
            if (b.length() > 0) b.append(';');
            b.append("gsc:1");
        }
        if (fotuCondenser > 0.5f) {
            if (b.length() > 0) b.append(';');
            b.append("enl:condenser");
        }
        if (fotuPrintLight != null && fotuPrintLight.length() > 0) {
            if (b.length() > 0) b.append(';');
            b.append("plt:").append(fotuPrintLight);
        }
        // Digital Reference's transfer style. The default (auto levels) is what a skeleton baked
        // with no style carries, so only a non-default one is sent.
        if (fotuDigitalRef != null && fotuDigitalRef.length() > 0 && !"auto-levels".equals(fotuDigitalRef)) {
            if (b.length() > 0) b.append(';');
            b.append("dsr:").append(fotuDigitalRef);
        }
        // Target Tone off keys the tone controls to each pixel instead of to its region.
        if (fotuLocalTone < 0.5f) {
            if (b.length() > 0) b.append(';');
            b.append("lct:0");
        }
        if (fotuPrinter > 0.5f) {
            if (b.length() > 0) b.append(';');
            b.append("prn:1");
            if (Math.abs(fotuPrinterLamp - 3200f) > 0.5f)
                b.append(";prl:").append(f("%.1f", fotuPrinterLamp));
            if (Math.abs(fotuPrinterM - 0.4f) > 1e-4f)
                b.append(";prm:").append(f("%.4f", fotuPrinterM));
            if (Math.abs(fotuPrinterY - 0.5f) > 1e-4f)
                b.append(";pry:").append(f("%.4f", fotuPrinterY));
            if (Math.abs(fotuPrinterEv) > 1e-4f)
                b.append(";pre:").append(f("%.4f", fotuPrinterEv));
            if (Math.abs(fotuPrinterR - 25f) > 1e-4f)
                b.append(";prr:").append(f("%.3f", fotuPrinterR));
            if (Math.abs(fotuPrinterG - 25f) > 1e-4f)
                b.append(";prg:").append(f("%.3f", fotuPrinterG));
            if (Math.abs(fotuPrinterB - 25f) > 1e-4f)
                b.append(";prb:").append(f("%.3f", fotuPrinterB));
        }
        if (fotuMottle > 1e-4f) {
            if (b.length() > 0) b.append(';');
            b.append("gm:").append(f("%.3f", fotuMottle));
        }
        if (fotuFringe > 1e-4f) {
            if (b.length() > 0) b.append(';');
            b.append("fr:").append(f("%.4f", fotuFringe))
             .append(";frr:").append(f("%.1f", fotuFringeRadius));
        }
        if (Math.abs(fotuCouplerReach - 1f) > 1e-4f) {
            if (b.length() > 0) b.append(';');
            b.append("cr:").append(f("%.4f", fotuCouplerReach));
        }
        if (Math.abs(fotuCouplerRG - 1f) > 1e-4f) {
            if (b.length() > 0) b.append(';');
            b.append("crg:").append(f("%.4f", fotuCouplerRG));
        }
        if (Math.abs(fotuCouplerGB - 1f) > 1e-4f) {
            if (b.length() > 0) b.append(';');
            b.append("cgb:").append(f("%.4f", fotuCouplerGB));
        }
        if (Math.abs(fotuCouplerSelf - 1f) > 1e-4f) {
            if (b.length() > 0) b.append(';');
            b.append("cs:").append(f("%.4f", fotuCouplerSelf));
        }
        if (fotuBlackPoint > 1e-4f) {
            if (b.length() > 0) b.append(';');
            b.append("bp:").append(f("%.4f", fotuBlackPoint));
        }
        if (fotuWhitePoint < 0.9999f) {
            if (b.length() > 0) b.append(';');
            b.append("wp:").append(f("%.4f", fotuWhitePoint));
        }
        if (fotuPrinterPreflash > 1e-5f) {
            if (b.length() > 0) b.append(';');
            b.append("ppf:").append(f("%.5f", fotuPrinterPreflash));
        }
        if (Math.abs(fotuCouplers - 1f) > 1e-4f) {
            // `effectiveCouplerScale`: below one the value is the scale; above it the overdrive
            // is compressed, so 1.6 stores 1.375 and 2 stores 1.5. The warp block and the
            // adjacency strength ride the same number.
            final float cs = fotuCouplers <= 1f ? fotuCouplers : 2f - 1f / fotuCouplers;
            if (b.length() > 0) b.append(';');
            b.append("mul:58=").append(f("%.4f", cs))
             .append(";mul:59=").append(f("%.4f", cs))
             .append(";mulrange:66-449=").append(f("%.4f", cs));
        }
        if (fotuHalationColour > 1e-4f) {
            if (b.length() > 0) b.append(';');
            b.append("hc:").append(f("%.4f", fotuHalationColour));
        }
        if (Math.abs(fotuHalation - 1f) > 1e-4f) {
            // The halo's radius is folded from three millimetre sigmas into pixels by
            // `resize_config`; scaling has to happen before that fold, hence `physmul`.
            for (int i = 0; i < 3; ++i) {
                if (b.length() > 0) b.append(';');
                b.append("physmul:halationSigmaMM_").append(i).append('=')
                        .append(f("%.4f", fotuHalation));
            }
        }
        if (fotuShadowDetail > 1e-4f) {
            if (b.length() > 0) b.append(';');
            b.append("sd:").append(f("%.4f", fotuShadowDetail));
        }
        if (fotuPrintCorrection > 1e-4f) {
            if (b.length() > 0) b.append(';');
            b.append("pc:").append(f("%.4f", fotuPrintCorrection));
        }
        if (fotuHighlightDetail > 1e-4f) {
            if (b.length() > 0) b.append(';');
            b.append("hd:").append(f("%.4f", fotuHighlightDetail));
        }
        // **The view layer travels with the render.** The 光学 page writes it for
        // the first engine's viewer; the second engine has no such pass, so the
        // host applies the very same `view_adjust.hpp` to its own output and a
        // preview, a canvas frame and an export all agree. Empty when every
        // control is at rest, and then the develop is untouched.
        final String view = fotuViewSlot();
        if (!view.isEmpty()) {
            if (b.length() > 0) b.append(';');
            b.append(view);
        }
        final String curves = fotuCurveSlot();
        if (!curves.isEmpty()) {
            if (b.length() > 0) b.append(';');
            b.append(curves);
        }
        // **The frame gauge.** Grain size, halation radius and MTF are all scaled
        // from the short side in millimetres, so a sensor the engine reads too
        // small renders as mush -- which is what the 尺度 page is for. The page
        // states the gate's *long* edge (135 = 36 mm); its ratio is the gate's
        // own (36:24, 1:1, 65:24 ...), so the short side is the edge over that
        // ratio -- not the crop's, or a square photo of a 135 frame would claim
        // 36 mm and render four times too coarse.
        if (formatIndex >= 0 && formatIndex < EDGE_MM.length) {
            final float shortMm = (float) Math.max(1.0,
                    EDGE_MM[formatIndex] / EDGE_RATIOS[formatIndex]);
            if (b.length() > 0) b.append(';');
            b.append("mm:").append(f("%.2f", shortMm));
        }

        // **A print-frame gauge carries its own border.** The seven gauges
        // ported from fotufilm are laid out by the host, so a look sitting on
        // one of them asks for the print frame by itself: a gate chosen before
        // this rule existed -- or restored from a look saved then -- otherwise
        // cropped the picture and drew nothing at all.
        // A look that only ever carried the gauge (no marker, no explicit
        // pick) draws its border with the 片边 switch; an explicit print frame
        // draws with 边框 → 印刷边框, whatever that switch says.
        // **fotufilm 的边框只有一套：`print_frame`。** 135、半格、XPan、七种 120、
        // 电影片、页片、Instax 全走它 —— 那才是 web 端画的那张片边。第一引擎的
        // rebate（片基雾 / 漏光 / 齿孔 / 张数 / DX / 日期）在这里一个字节都不发：
        // 两套材料、两套参数，混着发就是两种片边叠在一张图上。
        final String pfKindHere = (pfKind == null || "none".equals(pfKind)) ? "film" : pfKind;
        final boolean pfFilmHere = "film".equals(pfKindHere) || "film-positive".equals(pfKindHere);
        // A border this film and paper cannot carry is never sent: the host
        // would have no definition or no gauge to lay it on.
        // **On fotufilm the border's own row is the switch.** `overscanOn` is
        // the first engine's rebate flag: keeping it in this condition meant a
        // fotufilm frame could only be given a border by visiting 片边 -- the
        // one page that does nothing for this engine.
        final boolean pfDraw = withRebate
                && (isFotuStock(filmStock)
                        ? (pfKind != null && !"none".equals(pfKind))
                        : (overscanOn || (pfKind != null && !"none".equals(pfKind))))
                && pfAvailable(pfKindHere);
        if (pfDraw) {
            if (b.length() > 0) b.append(';');
            b.append("pf:").append(pfKindHere);
            if (pfFilmHere) {
                b.append(";pfg:").append(overscanFormat);
                // **Always, including at 1.** The host keeps `--pfframes` in a
                // file-level global that outlives one render, so leaving the slot
                // out meant "1" never reached it: going back from 2 was a no-op
                // and the frame count was stuck.
                b.append(";pffr:").append(pfFrames);
                b.append(";pfcam:").append("mediumFormatBack".equals(pfCamera)
                        ? "mediumFormatBack" : "panoramic");
            }
            // 厂印：官方那张表里有的才画（`edge_print_for`）。
            if (pfFilmHere && edgeTextOn) b.append(";etext:1");
            if (pfNeedsMargin())
                b.append(";pfm:").append(f("%.2f", Math.max(0f, Math.min(20f, pfMargin))));
            if (Math.abs(pfFx) > 1e-4f) b.append(";pffx:").append(f("%.3f", pfFx));
            if (Math.abs(pfFy) > 1e-4f) b.append(";pffy:").append(f("%.3f", pfFy));
        }
        // **第二引擎的白平衡。** 它没有「重解」这一步：`450..452` 是乘在解码
        // 结果上的三通道增益（默认 1,1,1），所以这里发的是**相对 5500 K** 的
        // 倍率。第一引擎那边同一个滑杆走的是 LibRaw 的 `user_mul`。
        final float[] wbg = fotuWbGain();
        if (wbg != null) {
            if (b.length() > 0) b.append(';');
            b.append("450=").append(f("%.5f", wbg[0]))
             .append(";451=").append(f("%.5f", wbg[1]))
             .append(";452=").append(f("%.5f", wbg[2]));
        }
        return b.toString();
    }

    /** Blocking: decode, develop, write a JPEG. Call on a worker thread. */
    private java.io.File fotuDevelop(String id, String medium, int maxEdge, String tag)
            throws java.io.IOException {
        return fotuDevelop(id, medium, maxEdge, tag, true);
    }

    /**
     * @param withGrain the film-grain tile model, when the panel asked for it.
     *
     * <p>The shelf's cards pass false even while the canvas uses it: a card is
     * 86 dp wide, the clumps are sub-pixel at that size, and laying the tiles
     * for forty-seven stocks costs eighteen seconds each.
     */
    private java.io.File fotuDevelop(String id, String medium, int maxEdge, String tag,
                                     boolean withGrain) throws java.io.IOException {
        return fotuDevelop(id, medium, maxEdge, tag, withGrain, "jpg");
    }

    /**
     * @param extRow "jpg" for a JPEG, "tif" for the 16-bit linear TIFF the host
     *               writes when the out path ends in `.tif`. The render is the
     *               same; only the encoder changes.
     */
    /** The last few non-empty lines of the host's report, trimmed for a dialog. */
    private static String fotuLastLines(String log, int lines, int chars) {
        if (log == null || log.isEmpty()) return "";
        final String[] all = log.split("\n");
        final StringBuilder tail = new StringBuilder();
        int taken = 0;
        for (int i = all.length - 1; i >= 0 && taken < lines; --i) {
            final String one = all[i].trim();
            if (one.isEmpty()) continue;
            tail.insert(0, one + "\n");
            taken++;
        }
        final String out = tail.toString().trim();
        return out.length() <= chars ? out : out.substring(out.length() - chars);
    }

    /**
     * Put the strip on before the file is written.
     *
     * <p>The host writes PNG for this path, not JPEG: composing means decoding
     * the frame again, and decoding a JPEG only to encode another one spends a
     * whole generation on a border. One lossy encode at the end, as always.
     */
    /**
     * The develop has to have produced the thing we are about to hand the album.
     *
     * <p>Cheap, and it names the failure at the layer it happened on. `.png`
     * used to reach this path with a PPM inside, and the only symptom was a
     * MediaStore error pointing at a file that no longer existed.
     */
    private static void verifyFotuExport(java.io.File f, boolean tiff)
            throws java.io.IOException {
        if (f == null || !f.isFile()) throw new java.io.IOException("引擎没有写出文件");
        if (f.length() < 128) throw new java.io.IOException("导出文件是空的（" + f.length() + " B）");
        final byte[] h = new byte[4];
        try (java.io.FileInputStream in = new java.io.FileInputStream(f)) {
            if (in.read(h) < 4) throw new java.io.IOException("导出文件不完整");
        }
        final boolean ok = tiff
                ? ((h[0] == 'I' && h[1] == 'I') || (h[0] == 'M' && h[1] == 'M'))
                : ((h[0] & 0xFF) == 0xFF && (h[1] & 0xFF) == 0xD8);
        if (!ok) {
            throw new java.io.IOException("引擎写出来的不是" + (tiff ? "TIFF" : "JPEG")
                    + "（文件头 "
                    + String.format(java.util.Locale.US, "%02X %02X", h[0] & 0xFF, h[1] & 0xFF)
                    + "）");
        }
    }

    private java.io.File fotuDevelop(String id, String medium, int maxEdge, String tag,
                                     boolean withGrain, String extRow) throws java.io.IOException {
        return fotuDevelop(id, medium, maxEdge, tag, withGrain, extRow, "");
    }

    private java.io.File fotuDevelop(String id, String medium, int maxEdge, String tag,
                                     boolean withGrain, String extRow,
                                     String extraSlots) throws java.io.IOException {
        final String source = fotuSourceFile();
        if (source == null) throw new java.io.IOException("读不到原图文件；请重新导入这一张");
        return fotuDevelopFrom(source, id, medium, maxEdge, tag, withGrain, extRow,
                !"tif".equals(extRow) && (maxEdge == 0 || maxEdge >= FOTU_REBATE_MIN_EDGE),
                extraSlots);
    }

    /**
     * The same develop, from a file the caller names.
     *
     * <p>The motion-photo path has twenty-two sources -- one per frame of the
     * clip it is re-developing. They are not the frame's photograph, so
     * {@link #fotuSourceFile} (which answers "which file is this frame rendered
     * from") would hand back the still every time. Everything else -- the
     * skeleton, the panel values, the table cache, the host lock -- is
     * deliberately the same, so a clip frame and the still beside it come out of
     * one develop.
     *
     * @param rebate the strip of film. **Never for a clip frame**: a rebate is
     *               something a print has, and the still already carries it.
     */
    private java.io.File fotuDevelopFrom(String source, String id, String medium, int maxEdge,
                                         String tag, boolean withGrain, String extRow,
                                         boolean rebate, String extraSlots)
            throws java.io.IOException {
        final String root = ensureFotuRoot();
        final String prefix = root + "/cfg/" + id + "/" + medium + "/";
        if (!new java.io.File(prefix, "config.f32").isFile()) {
            throw new java.io.IOException("这套胶片没有「" + FotuFilm.mediumLabel(medium)
                    + "」的骨架（cfg/" + id + "/" + medium + "）");
        }
        final java.io.File out = new java.io.File(getCacheDir(),
                "fotu-" + tag + "-" + System.currentTimeMillis() + "." + extRow);
        // **One call at a time.** The host keeps its decoded scene, its option
        // block and its Halide state in file-scope globals -- it was written for
        // a caller that renders one frame at a time. The shelf began developing
        // fotufilm cards in the background in 457, so the canvas render and a
        // card render can now overlap, and two `process` calls at once share
        // that state: the canvas sat on 「fotufilm 渲染中…」 and never came back.
        int rc;
        synchronized (FOTU_HOST_LOCK) {
        rc = FotuFilm.process(root, prefix, source, out.getAbsolutePath(),
                id, FotuFilm.mediumBin(medium), maxEdge, FotuFilm.SCREEN.equals(medium),
                fotuEv, fotuHighlights, fotuShadows, fotuSaturation, fotuVibrance, 0.95f,
                fotuWarmth, fotuTint, fotuFlare, fotuGradeLift, fotuGradeGain,
                fotuExpired, fotuBleach, fotuTableCache(), null, fotuPush,
                fotuSlots(id, root, withGrain, extraSlots,
                        // A thumbnail is not a print: see fotuSlots(boolean).
                        // **And a 16-bit linear TIFF is a master for another
                        // program**: the strip belongs to the print, so it goes
                        // on the JPEG only. `extRow` was not consulted here, so
                        // every TIFF export carried the rebate too.
                        rebate));
        }
        if (rc != 0) {
            // 3 is the cancel this UI asked for; everything else is a failure
            // the user has to read.
            // 4 is the host's own "an allocation did not fit" -- a hundred-megapixel
            // JPEG decodes to a float RGBA frame of sixteen bytes a pixel, and the
            // chain then needs three more planes. Saying so is better than the
            // signal 6 that used to be the only report.
            if (rc == 3) throw new java.io.IOException("已取消");
            if (rc == 4) throw new java.io.IOException("内存不足：这张图对 fotufilm 链来说太大"
                    + "（整幅浮点解码要一次装下）。关掉其它应用再试，或换 SpektraLab 引擎的胶片导出");
            // **The failure has a sentence, and until now nobody could read it.**
            final String said = fotuLastLines(FotuFilm.lastLog(), 6, 700);
            try {
                DebugSink.text("fotufilm", "rc=" + rc + " " + id + "/" + medium
                        + " edge=" + maxEdge + " src=" + source
                        + " out=" + out.getName() + " cache=" + fotuTableCache()
                        + (said.isEmpty() ? "" : "\n" + said));
            } catch (Throwable ignored) { }
            throw new java.io.IOException("fotufilm 渲染失败（返回 " + rc + "）"
                    + (said.isEmpty() ? "" : "\n\n" + said));
        }
        return out;
    }

    /**
     * The canvas frame.
     *
     * <p>Same contract as `renderImage`: exactly one render at a time, a
     * request that lands mid-render becomes the next one, and the result is
     * dropped if the frame moved on. What is different is the cost -- and the
     * fact that a cancel cannot stop the kernel mid-tile, so the button is not
     * offered here.
     */
    private void renderFotu() {
        if (!isFotuStock(filmStock)) return;
        try {
            DebugSink.text("border", "fotu pf=" + pfKind + " card=" + frameTemplate
                    + " gate=" + overscanFormat + " film=" + filmStock + " frame=" + currentFrame);
        } catch (Throwable ignored) { }
        if (fotuRendering) {
            fotuPending = true;
            statusText.setText("渲染中…");
            return;
        }
        final String stock = filmStock;
        final String id = FotuFilm.idOf(stock);
        final String medium = fotuMedium();
        final int gen = ++fotuGeneration;
        // **Which photograph this frame belongs to.** A develop takes seconds,
        // and it used to have no identity at all: a pass started on the picture
        // before an import landed afterwards and painted that picture onto the
        // new frame's canvas, seeded the shelf's cache with it and labelled the
        // status with the *new* file's name -- 「导入新照片，卡片和画布还是上一张」.
        // `renderEpoch` is bumped by every import, and this is what checks it.
        final int epoch = renderEpoch;
        stopPrefetch();
        fotuRendering = true;
        rendering = true;
        // Captured here, on the thread that owns the edit: the render thread
        // reads the fields a moment later and a half-applied crop would show.
        final String geo = fotuGeoSlot();
        progressBar.setVisibility(View.GONE);
        showBusyIfSlow();
        statusText.setText(fotuRoot == null
                ? "准备 fotufilm 资源（首次约 32 MB）…"
                : "fotufilm 渲染中…（CPU，约 2 秒）");
        final long t0 = nowMs();
        CrashTrail.mark(this, "fotu:begin " + id + "/" + medium);
        // **The flags are cleared by the render thread's own callback.** If that
        // callback never comes — a kernel that never returns — nothing else
        // clears them, and every later request becomes `fotuPending = true` and
        // a promise. Ninety seconds is longer than the slowest first-time table
        // build and short enough to be noticed.
        uiHandler.postDelayed(() -> {
            if (gen != fotuGeneration || !fotuRendering) return;
            markFile("fotu timeout " + id + "/" + medium);
            fotuRendering = false;
            rendering = false;
            clearBusyPlate();
            statusText.setText("fotufilm 超时 · 请再点一次，或换一张胶片");
            CrashTrail.markNow(this, "fotu:timeout " + id);
        }, 90000);
        new Thread(() -> {
            java.io.File file = null;
            Throwable failure = null;
            try { file = fotuDevelop(id, medium, FOTU_PREVIEW_EDGE, "p", true, "jpg", geo); }
            catch (Throwable t) { failure = t; }
            final java.io.File written = file;
            final Throwable error = failure;
            final long ms = nowMs() - t0;
            // **Mutable, or the glow pass cannot write into it.** `decodeFile`
            // returns an immutable bitmap by default and `setPixels` then throws
            // -- which `glowInPlace` turns into a silent no-op, so the panel
            // moved and the picture never did.
            final Bitmap bmp = written == null
                    ? null : decodeMutable(written.getAbsolutePath());
            // One JPEG per canvas render otherwise piles up in cacheDir: every
            // slider release on a fotufilm frame used to leave one behind.
            if (written != null) written.delete();
            runOnUiThread(() -> {
                fotuRendering = false;
                rendering = false;
                clearBusyPlate();
                if (gen != fotuGeneration) return;
                if (epoch != renderEpoch) {
                    // The photograph changed under us. Nothing of this frame
                    // belongs on the canvas, in the shelf's cache, or in the
                    // status line.
                    CrashTrail.mark(this, "fotu: dropped, the photo changed");
                    if (bmp != null) bmp.recycle();
                    return;
                }
                if (bmp == null) {
                    // **The gate heals itself once.** The host refuses a frame
                    // that is not its gate's shape -- the first engine's E-1305 --
                    // and the answer is the same here: cut the picture to the
                    // gate and ask again. Without this a crop in 构图 left the
                    // rebate permanently refusing.
                    final String said = error == null ? "" : String.valueOf(error.getMessage());
                    if (!fotuGateHealed && said.contains("gate's shape")) {
                        fotuGateHealed = true;
                        CrashTrail.mark(this, "fotu:heal gate " + overscanFormat);
                        applyGate(overscanFormat);
                        return;
                    }
                    // **A file that is no longer there is not a render
                    // failure.** A restored strip (150 frames was the report)
                    // can outlive the private copies its frames name, and every
                    // visit to such a frame used to raise a modal dialog with
                    // nothing the user could do in it -- 3 of the 8 errors in
                    // 1.7.0's first four hours. Say it on the canvas instead,
                    // once, and let browsing continue.
                    if (said.contains("读不到原图文件")) {
                        statusText.setText("这张照片的原始文件已不在 · 换一张，或重新导入");
                        showInAppToast("fotufilm：这张照片的原始文件已不在");
                        CrashTrail.mark(this, "fotu: source gone " + id);
                        return;
                    }
                    statusText.setText("fotufilm 渲染失败");
                    showErrorDialog("fotufilm 渲染失败",
                            (error == null ? "写出的 JPEG 打不开" : error.getMessage())
                                    + "\n\n" + id + " / " + medium);
                    return;
                }
                // **Keep the chain's own frame.** The border is drawn, not
                // developed, so toggling it (or nudging 张数) recomposes from this
                // instead of spending another second in the kernels.
                // **Never recycle what the canvas is holding.** With the border
                // off the composed frame *is* the chain's frame, so the two
                // fields alias one bitmap; recycling it here took the picture
                // off the screen and then drew a recycled bitmap.
                if (lastFotuPlain != null && lastFotuPlain != bmp
                        && lastFotuPlain != lastRenderedBitmap) lastFotuPlain.recycle();
                // **The second engine's own wrong answer.** Same detector as the
                // first: no exception, plausible size, one value everywhere.
                // Checked on the chain's frame and before the glow, because the
                // glow is a post-process and would only blur the evidence.
                // The cure is a second develop, not an engine rebuild -- this
                // path has no VkDevice of ours to throw away.
                final PictureCheck.Result fotuLook = PictureCheck.of(sampleGrid(bmp));
                if (!fotuLook.ok() && SelfHeal.budget("fotu-redraw", 1)) {
                    SelfHeal.repaired("fotu-flat", fotuLook.describe()
                            + " at " + bmp.getWidth() + "x" + bmp.getHeight());
                    bmp.recycle();
                    renderFotu();
                    return;
                }
                if (!fotuLook.ok()) {
                    statusText.setText("画面异常 · " + fotuLook.verdict);
                }
                // Glow the picture itself, not the strip it is printed on: the
                // rebate is drawn afterwards and a halo over perforations would
                // give the pass away.
                glowInPlace(bmp);
                lastFotuPlain = bmp;
                fotuGateHealed = false;
                final Bitmap shown = frameApply(fotuWithRebate(bmp));
                lastRenderedBitmap = shown;
                showingOriginal = false;
                setOriginalVisual(false);
                if (compare != null) compare.setAfter(shown);
                setStage(1, sourceUri == null ? null : getFileName(sourceUri));
                if (histogram != null) histogram.setBitmap(shown);
                cacheFilmThumb(stock, shown);
                updateCardThumb(stock);
                updateFilmSelection();
                refreshPanelLocks();
                statusText.setText("FOTUFILM · " + FotuFilm.mediumLabel(medium)
                        + " · " + ms + " ms");
                CrashTrail.mark(this, "fotu:done " + ms + "ms");
                schedulePersist();
                if (fotuPending) {
                    fotuPending = false;
                    renderFotu();
                } else {
                    // A user render stops the queue so it can own the CPU; put
                    // it back or the rest of the shelf never fills.
                    startPrefetch();
                }
            });
        }, "SpektraLab-fotu").start();
    }

    /**
     * One small frame while the finger is down.
     *
     * <p>The second engine has no session, so this is a whole chain run --
     * decode (cached in the host), tables (cached), the develop and print
     * kernels at 800 px, a JPEG and back. Measured on a 20 MP frame: 140-200 ms
     * once the first render has warmed the caches, against 1.2 s at the canvas
     * size. One frame in flight, the newest settings queued behind it, which is
     * what keeps a drag from stacking up work it will never show.
     */
    private void requestFotuLive() { requestFotuLive(false); }

    private void requestFotuLive(boolean settled) {
        if (!uiReady || appPaused || !isFotuStock(filmStock)) return;
        if (fotuRendering) { fotuLivePending = true; fotuLiveSettled |= settled; return; }
        drawFotuLive(settled);
    }

    /**
     * One settled frame 200 ms after the last input.
     *
     * <p>A drag only ever asks for the cheap frame; the cheap frame is what
     * makes the drag usable. This is what puts the strip and the full edge back
     * when the finger stops without a release (a tap on the ruler, a nudge with
     * the keyboard) — the release itself renders at 2048 anyway.
     */
    private void scheduleFotuSettle() {
        uiHandler.removeCallbacks(fotuSettle);
        uiHandler.postDelayed(fotuSettle, 200);
    }

    private final Runnable fotuSettle = () -> {
        if (isFotuStock(filmStock) && !fotuRendering && !appPaused) requestFotuLive(true);
    };

    private void drawFotuLive(boolean settled) {
        final String stock = filmStock;
        if (stock == null) return;
        final String id = FotuFilm.idOf(stock);
        final String medium = fotuMedium();
        final int gen = ++fotuLiveGeneration;
        // Same identity as the full render: a drag frame must not land on a
        // photograph it was not drawn from.
        final int epoch = renderEpoch;
        final String geo = fotuGeoSlot();
        fotuRendering = true;
        final int edge = settled ? FOTU_LIVE_EDGE : FOTU_DRAG_EDGE;
        final long liveStart = nowMs();
        new Thread(() -> {
            java.io.File file = null;
            Bitmap frame = null;
            try {
                file = fotuDevelop(id, medium, edge, "l", false, "jpg", geo);
                frame = BitmapFactory.decodeFile(file.getAbsolutePath());
            } catch (Throwable ignored) {
            } finally {
                if (file != null) file.delete();
            }
            // The one number the next report needs: what a drag frame costs on
            // that device, at the size it was drawn at.
            try {
                DebugSink.text("fotu-live", "frame " + edge + " "
                        + (nowMs() - liveStart) + " ms"
                        + (settled ? " settled" : ""));
            } catch (Throwable ignored) { }
            final Bitmap drawn = frame;
            runOnUiThread(() -> {
                fotuRendering = false;
                if (epoch != renderEpoch) {
                    if (drawn != null) drawn.recycle();
                    return;
                }
                // A full render asked for while this was in flight owns the
                // canvas; running it here is what the queue would have done.
                if (fotuPending) { fotuPending = false; renderFotu(); return; }
                if (drawn != null && gen == fotuLiveGeneration && isFotuStock(filmStock)) {
                    final Bitmap live = fotuWithRebate(drawn);
                    if (live != drawn) drawn.recycle();
                    showingOriginal = false;
                    setOriginalVisual(false);
                    if (compare != null) compare.setAfter(live);
                }
                if (fotuLivePending) {
                    fotuLivePending = false;
                    final boolean full = fotuLiveSettled;
                    fotuLiveSettled = false;
                    drawFotuLive(full);
                } else if (!settled) {
                    // **Only a cheap frame re-arms the timer.** A settled frame
                    // that re-armed it would render 900 px for ever, once every
                    // 200 ms, with nobody dragging.
                    scheduleFotuSettle();
                }
            });
        }, "SpektraLab-fotu-live").start();
    }

    /**
     * The export.
     *
     * <p>0 asks for the photograph's own size -- the same promise the first
     * engine's "全尺寸" makes, and the reason there is no shrink-to-fit here.
     * The chain writes a JPEG; the album write is the app's own, so a provider
     * that refuses the row is reported the way every other export reports it.
     */
    /**
     * The second engine's export.
     *
     * <p>Two files, and they serve different ends. A JPEG is eight bits of
     * display codes: the whole top stop of the print lives in about ten of them,
     * which is why "pull the highlights back" has nothing to pull. A linear
     * 16-bit TIFF spends 32768 codes on that same stop, so a tone curve in
     * Lightroom moves detail instead of posterising it -- the file a lab scan
     * would hand over. Both come out of the same render; only the write differs.
     */
    // --- fotufilm: the strip of film around the frame, drawn ---------------------
    //
    // The second engine renders the picture and nothing else: its host has no
    // rebate, no perforations and no edge printing, and giving it those would mean
    // porting the first engine's overscan subsystem (ten gate masks, emulsion
    // physics) into a CPU chain that deliberately stops at the frame.
    //
    // So the border is *composed*: the developed frame is laid on a strip of base
    // in Java, the way a scan of a negative shows it. It is honest about what it
    // is -- the base has the 片基雾 control's tint but not its density model, the
    // perforations are drawn rather than lit -- and it is the same code for the
    // canvas, the live frame and the export, so what you see is what ships.

    /** The gate the 片门 chips name, as an index into {@link #EDGE_IDS}. */
    private static int gateIndexOf(String id) {
        if (id != null) {
            for (int i = 0; i < EDGE_IDS.length; ++i) if (EDGE_IDS[i].equals(id)) return i;
        }
        return 0;
    }

    /** Black and white mixed, for the base and the tint. */
    private static int toneMix(int a, int b, float t) {
        final float u = Math.max(0f, Math.min(1f, t));
        final int ar = (a >> 16) & 0xFF, ag = (a >> 8) & 0xFF, ab = a & 0xFF;
        final int br = (b >> 16) & 0xFF, bg = (b >> 8) & 0xFF, bb = b & 0xFF;
        return 0xFF000000
                | (Math.round(ar + (br - ar) * u) << 16)
                | (Math.round(ag + (bg - ag) * u) << 8)
                | Math.round(ab + (bb - ab) * u);
    }

    /** The maker's name as it would be printed on the edge. */
    private String fotuEdgeBrand() {
        final FotuFilm.Stock stock = fotuStocks.get(FotuFilm.idOf(filmStock));
        if (stock == null) return "FOTUFILM";
        final String brand = stock.brand == null ? "" : stock.brand.trim();
        final String name = stock.name == null ? "" : stock.name.trim();
        if (brand.isEmpty()) return name.toUpperCase(java.util.Locale.US);
        return (brand + " " + name).toUpperCase(java.util.Locale.US).trim();
    }

    /**
     * The frame on a strip of film.
     *
     * <p>Returns the argument itself when the rebate is off, so every caller can
     * pass its bitmap through unconditionally.
     */
    private void recomposeFotu() {
        if (lastFotuPlain == null) return;
        final Bitmap shown = frameApply(fotuWithRebate(lastFotuPlain));
        if (shown == lastRenderedBitmap) return;
        lastRenderedBitmap = shown;
        if (compare != null) compare.setAfter(shown);
        if (histogram != null) histogram.setBitmap(shown);
        if (isFotuStock(filmStock)) {
            cacheFilmThumb(filmStock, shown);
            updateCardThumb(filmStock);
        }
    }

    private Bitmap fotuWithRebate(Bitmap frame) {
        // **The host draws it now.** The rebate is built where the film is
        // exposed -- gate shadow, perforations, edge print and date as exposure --
        // and develops with the picture, so there is nothing left to paint on
        // top. The drawing below is kept as the record of what a drawn border
        // looks like -- it is not reachable.
        if (true) return frame;
        final int fw = frame.getWidth(), fh = frame.getHeight();
        if (fw < 8 || fh < 8) return frame;
        final int gi = gateIndexOf(overscanFormat);
        final float longMm = EDGE_MM[Math.min(gi, EDGE_MM.length - 1)];
        final float shortMm = (float) (longMm / EDGE_RATIOS[Math.min(gi, EDGE_RATIOS.length - 1)]);
        final boolean portrait = fh > fw;
        final float pxPerMm = Math.max(fw, fh) / Math.max(1f, longMm);
        // 35 mm film is 35 mm wide and carries a 24 mm frame: the margin across
        // the film is (35 - short side) / 2. The 120 carriers have no
        // perforations and only the paper's own 2 mm edge.
        final boolean sprockets = gi <= 2;
        final float across = (sprockets ? Math.max(0f, (35f - shortMm) * 0.5f) : 2.0f) * pxPerMm;
        final float along = (sprockets ? 1.0f : 2.0f) * pxPerMm;
        final int mx = Math.max(2, Math.round(portrait ? across : along));
        final int my = Math.max(2, Math.round(portrait ? along : across));
        Bitmap out = null;
        try {
            out = Bitmap.createBitmap(fw + mx * 2, fh + my * 2, Bitmap.Config.ARGB_8888);
            final Canvas c = new Canvas(out);
            drawRebate(c, frame, mx, my, sprockets, pxPerMm, portrait);
            return out;
        } catch (Throwable t) {
            if (out != null) { try { out.recycle(); } catch (Throwable ignored) { } }
            return frame;
        }
    }

    private void drawRebate(Canvas c, Bitmap frame, int mx, int my,
                            boolean sprockets, float pxPerMm, boolean portrait) {
        final int w = c.getWidth(), h = c.getHeight();
        final int fw = frame.getWidth(), fh = frame.getHeight();
        // 片基雾 is a density control on the engine's side; here it can only be
        // the base's own lightness, which is what a dirtier base looks like.
        final float fog = Math.max(0f, Math.min(4f, edgeFog)) / 4f;
        final int base = toneMix(0xFF0E0B09, 0xFF43392D, fog);
        c.drawColor(base);
        final Paint p = new Paint(Paint.ANTI_ALIAS_FLAG);
        c.drawBitmap(frame, mx, my, null);
        // A hairline where the gate cut the frame: the one place a scan shows a
        // hard edge against the base.
        p.setStyle(Paint.Style.STROKE);
        p.setStrokeWidth(Math.max(1f, pxPerMm * 0.05f));
        p.setColor(0x33FFFFFF);
        c.drawRect(mx, my, mx + fw, my + fh, p);
        p.setStyle(Paint.Style.FILL);
        if (sprockets) {
            final float pitch = 4.75f * pxPerMm;                 // 135: 4.75 mm
            final float side = Math.min(pitch * 0.44f, 1.98f * pxPerMm);
            final float halfSide = side * 0.5f;
            p.setColor(0xFFEDE4D2);
            p.setAlpha(200);
            if (!portrait) {
                for (float x = mx + pitch * 0.5f; x < mx + fw; x += pitch) {
                    c.drawRoundRect(x - halfSide, my * 0.5f - halfSide,
                            x + halfSide, my * 0.5f + halfSide, halfSide * 0.4f, halfSide * 0.4f, p);
                    c.drawRoundRect(x - halfSide, h - my * 0.5f - halfSide,
                            x + halfSide, h - my * 0.5f + halfSide, halfSide * 0.4f, halfSide * 0.4f, p);
                }
            } else {
                for (float y = my + pitch * 0.5f; y < my + fh; y += pitch) {
                    c.drawRoundRect(mx * 0.5f - halfSide, y - halfSide,
                            mx * 0.5f + halfSide, y + halfSide, halfSide * 0.4f, halfSide * 0.4f, p);
                    c.drawRoundRect(w - mx * 0.5f - halfSide, y - halfSide,
                            w - mx * 0.5f + halfSide, y + halfSide, halfSide * 0.4f, halfSide * 0.4f, p);
                }
            }
            p.setAlpha(255);
        }
        final String stamp = dateText != null ? dateText : dateTextB;
        final boolean stampOn = dateOn && stamp != null && !stamp.isEmpty();
        final float textPx = 2.1f * pxPerMm;
        final float pad = pxPerMm * 1.3f;
        if (edgeTextOn && textPx >= 3.5f) {
            p.setTypeface(tfBold != null ? tfBold : tfBody);
            p.setTextScaleX(0.88f);
            p.setTextSize(textPx);
            p.setColor(0xFFA99C86);
            final String brand = fotuEdgeBrand();
            final String no = (frameNo() > 0 ? frameNo() : 12) + "A";
            if (!portrait) {
                final float baseline = my * 0.5f + textPx * 0.36f;
                p.setTextAlign(Paint.Align.LEFT);
                c.drawText(brand, mx + pad, baseline, p);
                p.setTextAlign(Paint.Align.RIGHT);
                c.drawText(no, mx + fw - pad, baseline, p);
                if (stampOn && "rebate".equals(datePlacement)) {
                    p.setColor(0xFFE8A45C);
                    final float mid = mx + fw * 0.5f;
                    p.setTextAlign(Paint.Align.CENTER);
                    c.drawText(withData(stamp), mid, baseline, p);
                }
            } else {
                // The film ran vertically: the margin that has room is the wide
                // one on the left, so the printing goes in it rotated, as it does
                // on the strip itself.
                p.setTextAlign(Paint.Align.CENTER);
                c.save();
                c.rotate(-90f, mx * 0.5f, my);
                c.drawText(brand, mx * 0.5f, my + fh - pad, p);
                c.drawText(no, mx * 0.5f, my + textPx + pad, p);
                if (stampOn && "rebate".equals(datePlacement)) {
                    p.setColor(0xFFE8A45C);
                    c.drawText(withData(stamp), mx * 0.5f, my + fh * 0.5f, p);
                }
                c.restore();
            }
        }
        if (stampOn && !"rebate".equals(datePlacement)) {
            // Burnt into the picture, the way a date back does it: the corner the
            // page names, inset by the same two controls the first engine reads.
            p.setTypeface(tfBold != null ? tfBold : tfBody);
            p.setTextScaleX(0.88f);
            final float size = Math.max(textPx, fh * 0.026f * Math.max(0.5f, dateSize));
            p.setTextSize(size);
            p.setColor(0xFFFF9A3C);
            final boolean right = !"bl".equals(dateCorner) && !"tl".equals(dateCorner);
            final boolean top = "tr".equals(dateCorner) || "tl".equals(dateCorner);
            p.setTextAlign(right ? Paint.Align.RIGHT : Paint.Align.LEFT);
            final float at = Math.min(fw * 0.9f, Math.max(size, dateInsetX * pxPerMm));
            final float x = right ? mx + fw - at : mx + at;
            final float inset = Math.max(2f, dateInsetY * pxPerMm);
            final float y = top ? my + inset + size : my + fh - inset;
            c.drawText(stamp, x, y, p);
            if (dataText != null && !dataText.isEmpty()) {
                p.setColor(0xFFE8A45C);
                c.drawText(dataText, x, top ? y + size * 1.15f : y - size * 1.15f, p);
            }
        }
    }

    /** The date and the shot data the rebate prints on one line, as a date back does. */
    private String withData(String stamp) {
        return dataText == null || dataText.isEmpty() ? stamp : stamp + "  " + dataText;
    }

    /** The 张数 the rebate prints (0 = unset). */
    private int frameNo() {
        return Math.round(frameNumber);
    }

    private void exportFotu(String format, String tier, final Runnable onDone,
                            final int liveEdgeIn) {
        final boolean tiff = "tifflin".equals(format) || "tiff".equals(format);
        final String ext = tiff ? ".tif" : ".jpg";
        final String mime = tiff ? "image/tiff" : "image/jpeg";
        if (!isFotuStock(filmStock)) {
            if (onDone != null) onDone.run();
            return;
        }
        if (fotuRendering) {
            showInAppToast("正在渲染，完成后即可导出");
            if (onDone != null) onDone.run();
            return;
        }
        final String id = FotuFilm.idOf(filmStock);
        final String medium = fotuMedium();
        final String base = "SpektraLab_" + System.currentTimeMillis();
        final long t0 = nowMs();
        stopPrefetch();
        fotuRendering = true;
        runOnUiThread(() -> {
            statusText.setText("导出中：fotufilm 全尺寸渲染…");
            showBusy("EXPORTING");
            setStep(3);
        });
        CrashTrail.mark(this, "export:fotu " + id + "/" + medium + " tier=" + tier);
        // **The file's own size, as far as this phone can develop it.** A hundred megapixels
        // is a gigabyte and a half of float frame before a kernel runs; asking for that on a
        // phone which cannot hold it was an abort, and would now be an error. The budget is
        // the same twenty bytes a pixel the host uses, so the two agree on where the line is.
        final int edge = fotuExportEdge();
        final String geo = fotuGeoSlot();
        // **Which clip, decided on the caller's thread** -- the same rule the
        // first engine's path uses. `liveExportWanted` is consumed here so it
        // cannot leak into the next export: this branch returns before the other
        // path ever reads it.
        final int liveEdge = (!tiff && !batchExportRunning) ? liveEdgeIn : 0;
        final String liveClipPath = liveEdge > 0 ? liveClipForCurrentFrame() : null;
        final long liveTsUs = (liveClipPath != null && currentFrame >= 0
                && currentFrame < frames.size()) ? frames.get(currentFrame).liveTsUs : 0L;
        final boolean[] liveDone = {false};
        new Thread(() -> {
            java.io.File file = null;
            Throwable failure = null;
            try {
                // **The strip of film is the host's, and has been since 1.6.5b.**
                // It is exposed with the picture (`rebate:1` travels in the slots)
                // and develops with it, so an intermediate image and a second pass
                // in Java have nothing left to do -- and the intermediate was
                // being written as a PPM named `.png`, because this build has no
                // PNG encoder. `BitmapFactory` could not open it, the
                // compose step threw, and the failure surfaced as
                // 「相册写入失败」 with a `fotu-x-*.png: ENOENT` cause, three
                // layers away from the truth. Bug since the host took over the
                // strip; reported against 1.6.5q on a 120 6x12 frame.
                file = fotuDevelop(id, medium, edge, "x", true, tiff ? "tif" : "jpg",
                        withSlot(geo, tiff ? fotuExifSlot() : ""));
                verifyFotuExport(file, tiff);
                // **History first, motion last.** `JpegExif.inject` drops every
                // APP1 it meets and writes its own, and our motion declaration
                // *is* an APP1: run it after the clip is attached -- which is
                // what would happen on a camera whose JPEG carries no Exif of its
                // own -- and it would delete the declaration and leave the clip
                // orphaned inside the file. That shape ("no motion XMP, 688 KB of
                // video") is exactly what poisons every downstream reader, so the
                // still is annotated while it is still a still.
                if (!tiff) annotateFotuExport(file, id, medium);
                // **The still is finished; now the clip that plays behind it.**
                // The second engine develops a frame from a path, so this walks
                // the clip through `fotufilm` itself -- one file goes to the
                // album, so it has to happen before the write.
                if (liveClipPath != null) {
                    runOnUiThread(() -> statusText.setText("导出中：动图逐帧冲洗（fotufilm）..."));
                    final java.io.File withClip = attachLiveClip(file, liveClipPath, liveTsUs,
                            (c, st) -> renderFotuLiveClip(c, liveEdge, st));
                    if (withClip != null) {
                        final java.io.File stillOnly = file;
                        file = withClip;
                        stillOnly.delete();
                        liveDone[0] = true;
                    }
                }
            }
            catch (Throwable t) { failure = t; }
            final java.io.File written = file;
            final Throwable error = failure;
            final long ms = nowMs() - t0;
            // **`file != null` does not mean the develop succeeded.** The old
            // guard only asked whether a name had been handed back, so anything
            // thrown after the first assignment -- a compose, a header check --
            // fell through to the album writer with a file that was already
            // gone, and the user was told the gallery had refused it.
            if (written == null || error != null) {
                final String why = error == null ? "没有出图"
                        : (error.getMessage() == null ? error.toString() : error.getMessage());
                if (written != null) written.delete();
                runOnUiThread(() -> {
                    fotuRendering = false;
                    hideBusy();
                    statusText.setText("导出失败");
                    showErrorDialog("导出失败", why);
                    if (onDone != null) onDone.run();
                });
                return;
            }
            // **The pixels arrived without their history.** fotufilm's writer emits
            // the frame and its ICC profile and nothing else, so every JPEG export
            // lost the model, the date, the shutter, the aperture, the ISO and the
            // focal length -- visible the moment the file lands in a gallery. The
            // same seven fields the first engine's writer takes go in front of the
            // image data here, with orientation normalised: the pixels are already
            // upright, so carrying the source's 90 degrees would turn the print a
            // second time.
            try {
                final Uri outUri = writeExportFile(written, base, ext, mime);
                runOnUiThread(() -> {
                    // The share pill sends "the last export"; a fotu file has to
                    // claim that slot the same way the other engine's does.
                    lastExportUri = outUri;
                    lastExportMime = mime;
                    fotuRendering = false;
                    hideBusy();
                    final String what = tiff ? "TIFF 16 位 · 线性" : "JPEG";
                    final String hint = tiff ? "（TIFF：点导出旁边的「分享」发给手机版 Lightroom 即可使用）" : "";
                    statusText.setText("已导出 " + what + " · fotufilm · " + (ms / 1000) + " 秒"
                            + (edge > 0 ? "（按本机内存，长边 " + edge + " px）" : "") + hint);
                    final String liveNote = liveDone[0] ? " · 实况（含动图）"
                            : (liveClipPath != null ? " · 动图未写入" : "");
                    showInAppToast("已保存到相册：" + base + ext
                            + (edge > 0 ? "（原图太大，按本机上限缩到长边 " + edge + " px）" : "")
                            + liveNote + hint);
                    if (sharePill != null) sharePill.setVisibility(tiff ? View.VISIBLE : View.GONE);
                    CrashTrail.mark(this, "export:written fotu " + ms + "ms");
                    if (onDone != null) onDone.run();
                });
            } catch (Throwable t) {
                runOnUiThread(() -> {
                    fotuRendering = false;
                    hideBusy();
                    statusText.setText("导出失败");
                    showErrorDialog("相册写入失败",
                            "渲染完成，但系统相册没有接受这个文件：\n\n" + t);
                    if (onDone != null) onDone.run();
                });
            } finally {
                // The album has its own copy; this one is a full-size JPEG in
                // cacheDir and nothing will ever read it again.
                if (written != null) written.delete();
            }
        }, "SpektraLab-fotu-export").start();
    }

    /**
     * The longest edge fotufilm's export may develop, or 0 for the file's own size.
     *
     * <p>The chain decodes into float RGBA (sixteen bytes a pixel) and then splits that into
     * three planes (twelve more), so a hundred megapixels is 2.8 GB before a kernel starts.
     * The host applies the same budget to what it decodes; this is what stops a frame being
     * asked for in the first place, and it is what the status line reports when it bites.
     * A file that fits is exported at its own size, unchanged.
     */
    private int fotuExportEdge() {
        final long avail = availableMemoryBytes();
        final long budgetPx = Math.max(4_000_000L,
                (avail > 0 ? avail * 45L / 100L : (2L << 30)) / 20L);
        int w = importedWidth, h = importedHeight;
        try {
            if (rawFilePath != null) {
                final int[] d = SpektraLabEngine.rawDimensions(rawFilePath);
                if (d != null && d[0] > 0 && d[1] > 0) { w = d[0]; h = d[1]; }
            } else if (sourceUri != null) {
                final int[] d = sniffImageSize(sourceUri);
                if (d != null && d[0] > 0 && d[1] > 0) { w = d[0]; h = d[1]; }
            }
        } catch (Throwable ignored) { }
        if (w <= 0 || h <= 0) return 0;
        final long px = (long) w * h;
        if (px <= budgetPx) return 0;
        final double k = Math.sqrt((double) budgetPx / (double) px);
        return Math.max(1024, (int) Math.round(Math.max(w, h) * k));
    }

    /**
     * Puts this frame's capture fields into a fotufilm JPEG.
     *
     * <p>Everything here is best effort: an unreadable source, a container the
     * platform reader refuses, a file that is not a JPEG -- each one leaves the
     * export exactly as the engine wrote it. What never happens is *wrong*
     * metadata: the orientation is ours (1), and a field the source could not
     * give is omitted rather than written blank.
     */
    private void annotateFotuExport(java.io.File file, String stockId, String medium) {
        try {
            // **The encoder already carried the source's own record.** `ffc_encode`
            // is handed the Exif the decoder captured, and writes it minus the
            // orientation, the pixel size, the thumbnail and the maker notes --
            // a fuller copy than the seven fields below can rebuild, and the one
            // the Mac app's exports carry. Only when there is no APP1 at all --
            // a raw container whose decoder reports none -- is there anything
            // left for this method to add.
            if (JpegExif.hasExif(file)) {
                try {
                    DebugSink.text("exif", "fotufilm export: the encoder carried the source record"
                            + " (" + stockId + "/" + medium + ")");
                } catch (Throwable ignored) { }
                return;
            }
            final int[] size = JpegExif.sizeOf(file);
            if (size == null || size[0] <= 0 || size[1] <= 0) return;
            final JpegExif.Meta meta = new JpegExif.Meta();
            meta.width = size[0];
            meta.height = size[1];
            // Provenance, in the one place a later reader will look for it.
            meta.note = "fotufilm " + stockId + " / " + medium;
            final String[] f = fotuSourceFields();
            meta.make = f[0];
            meta.model = f[1];
            meta.datetime = f[2];
            meta.exposure = f[3];
            meta.aperture = f[4];
            meta.iso = f[5];
            meta.focal = f[6];
            final byte[] app1 = JpegExif.buildApp1(meta);
            if (app1 == null) return;
            final boolean ok = JpegExif.inject(file, app1);
            try {
                DebugSink.text("exif", "fotufilm export " + (ok ? "APP1 " + app1.length + " B" : "APP1 refused")
                        + " " + stockId + "/" + medium + " " + size[0] + "x" + size[1]
                        + " from " + java.util.Arrays.toString(f));
            } catch (Throwable ignored) { }
        } catch (Throwable ignored) { }
    }

    /**
     * The frame's shape, as the second engine's one slot.
     *
     * <p>That chain has no geometry node -- it goes from the photograph into the
     * film -- so the host applies the crop, the quarter turns, the flips and the
     * rotation to the decoded scene before the kernel sees it. The host's map is
     * the first engine's, constant for constant, so the same numbers give the
     * same picture whichever engine developed it; that is what keeps the canvas
     * preview and the export agreeing across a stock switch.
     *
     * <p>Identity is the empty string: a frame nobody cropped takes the
     * untouched path and stays bit-exact against the engine.
     */
    private String fotuGeoSlot() {
        final float w = Math.max(0.005f, Math.min(1f, geometryCropW));
        final float h = Math.max(0.005f, Math.min(1f, geometryCropH));
        final float x = Math.max(0f, Math.min(1f - w, geometryCropX));
        final float y = Math.max(0f, Math.min(1f - h, geometryCropY));
        final float rot = Math.max(-45f, Math.min(45f, geometryRotation));
        final int turns = ((geometryTurns % 4) + 4) % 4;
        final int flips = (geometryFlipH ? 1 : 0) | (geometryFlipV ? 2 : 0);
        if (turns == 0 && flips == 0 && Math.abs(rot) < 1e-4f
                && w > 0.9999f && h > 0.9999f && x < 1e-4f && y < 1e-4f) {
            return "";
        }
        return String.format(java.util.Locale.US, "geo:%.5f|%.5f|%.5f|%.5f|%.4f|%d|%d",
                x, y, w, h, rot, turns, flips);
    }

    /**
     * The TIFF's IFD0 record, as one slot.
     *
     * <p>A TIFF carries no APP1, so the capture fields become ordinary tags and
     * the host writes them beside the pixels -- the same seven the JPEG gets in
     * its segment. Empty fields are skipped there rather than written as zero,
     * and the two characters the slot grammar uses are folded to spaces.
     */
    private String fotuExifSlot() {
        final String[] f = fotuSourceFields();
        final StringBuilder b = new StringBuilder("exif:");
        for (int i = 0; i < 7; ++i) {
            if (i > 0) b.append('|');
            b.append(slotSafe(f[i]));
        }
        return b.toString();
    }

    /** A value the slot string can carry: no field separator, no verb separator. */
    private static String slotSafe(String value) {
        if (value == null) return "";
        return value.replace('|', ' ').replace(';', ' ').trim();
    }

    /**
     * {make, model, datetime, shutter, aperture, iso, focal} for this fotufilm frame.
     *
     * <p>A raw container goes through the platform reader, which parses the
     * TIFF-based ones (DNG, NEF, CR2, ARW) and refuses the rest. A JPEG goes
     * through the same two readers the first engine's export uses, so a file
     * whose APP1 our own parser can read does not depend on the platform at all.
     */
    private String[] fotuSourceFields() {
        if (rawFilePath != null) {
            // **The container's own IFD first.** The platform reader decides by
            // the first four bytes whether it knows a format, and a Panasonic
            // `.RW2` (`IIU\0`) or an Olympus `.ORF` (`IIRO`) is not one of them
            // -- though both are TIFF with a different magic number, which is
            // all this parser cares about. It returns empty strings rather than
            // guesses when a tag is absent.
            try {
                final String[] t = TiffExif.read(rawFilePath);
                if (t != null && (!t[0].isEmpty() || !t[2].isEmpty())) return t;
            } catch (Throwable ignored) { }
            try {
                final android.media.ExifInterface e = new android.media.ExifInterface(rawFilePath);
                return new String[]{
                        nz(e.getAttribute(android.media.ExifInterface.TAG_MAKE)),
                        nz(e.getAttribute(android.media.ExifInterface.TAG_MODEL)),
                        nz(e.getAttribute(android.media.ExifInterface.TAG_DATETIME_ORIGINAL)),
                        nz(e.getAttribute(android.media.ExifInterface.TAG_EXPOSURE_TIME)),
                        nz(e.getAttribute(android.media.ExifInterface.TAG_F_NUMBER)),
                        nz(e.getAttribute(android.media.ExifInterface.TAG_ISO_SPEED_RATINGS)),
                        nz(e.getAttribute(android.media.ExifInterface.TAG_FOCAL_LENGTH))};
            } catch (Throwable ignored) { }
        }
        try {
            final String[] parsed = jpegSourceExif();
            if (parsed != null && parsed.length >= 7) return parsed;
        } catch (Throwable ignored) { }
        return new String[]{"", "", "", "", "", "", ""};
    }

    /** Which media this stock may be printed on, with the current one marked. */
    private void showFotuMediumPicker() {
        final String id = FotuFilm.idOf(filmStock);
        final FotuFilm.Stock stock = fotuStocks.get(id);
        if (stock == null) return;
        final List<String> media = FotuFilm.mediaFor(stock);
        final List<String> labels = new ArrayList<>();
        final List<String> notes = new ArrayList<>();
        for (String medium : media) {
            labels.add(FotuFilm.mediumLabel(medium));
            // What the sheet does, not just its name: this is the only place
            // the second engine's twelve media are explained.
            notes.add(paperLineT(medium, fotuMediumNote(medium)));
        }
        final String current = fotuMedium();
        final int at = media.indexOf(current);
        showChoiceSheet("fotufilm · 相纸 / 输出介质", labels, notes,
                at >= 0 ? labels.get(at) : null, index -> true,
                picked -> {
                    final int i = labels.indexOf(picked);
                    if (i < 0 || i >= media.size()) return;
                    final String want = media.get(i);
                    if (want.equals(fotuMedium())) return;
                    printStock = want;
                    refreshPaperLabel();
                    showingOriginal = false;
                    onStockChanged();
                });
    }

    /** 推拉显影: only the steps the stock's pack actually lists. */
    private void showFotuPushPicker() {
        if (fotuRoot == null) {
            ensureFotuRootAsync(this::showFotuPushPicker);
            return;
        }
        final String id = FotuFilm.idOf(filmStock);
        final float[] listed = FotuFilm.pushStops(fotuRoot, id);
        final List<String> labels = new ArrayList<>();
        final List<Float> values = new ArrayList<>();
        labels.add("不推拉");
        values.add(0f);
        if (listed != null) {
            for (float v : listed) {
                labels.add(String.format(java.util.Locale.US, "%+.4g 档", v));
                values.add(v);
            }
        }
        int selected = 0;
        for (int i = 0; i < values.size(); ++i) {
            if (Math.abs(values.get(i) - fotuPush) < 1e-4f) { selected = i; break; }
        }
        showChoiceSheet("推拉显影", labels, labels.get(selected), picked -> {
            final int i = labels.indexOf(picked);
            if (i < 0) return;
            fotuPush = values.get(i);
            refreshFotuPush();
            if (uiReady && isFotuStock(filmStock)) {
                showingOriginal = false;
                renderFotu();
            }
        });
    }

    private void refreshFotuPush() {
        if (fotuPushValue == null) return;
        fotuPushValue.setText(Math.abs(fotuPush) < 1e-4f ? "不推拉"
                : String.format(java.util.Locale.US, "%+.1f 档", fotuPush));
    }

