    /**
     * One row: name, value, a full-width bar.
     *
     * <p>No live preview on drag: the chain is two seconds and a preview per
     * tick would queue six. The number follows the thumb, the picture follows
     * the release -- which is also what the validation shell did, and what the
     * engine's own cost makes honest.
     */
    /** One menu row: the title, the current choice, and a sheet of the rest. */
    private void fotuChoiceRow(LinearLayout parent, String title, String hint,
                               final String[] ids, final String[] labels,
                               final java.util.function.Supplier<String> get,
                               final java.util.function.Consumer<String> set) {
        final LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setGravity(android.view.Gravity.CENTER_VERTICAL);
        row.setPadding(0, dp(6), 0, dp(6));
        row.addView(label(title, 9, UI_INK, tfHan), new LinearLayout.LayoutParams(-2, -2));
        if (hint != null && !hint.isEmpty()) row.addView(bangFor(() -> hint));
        row.addView(new View(this), new LinearLayout.LayoutParams(0, -2, 1f));
        final TextView value = label("", 9, UI_BLUE, tfBody);
        row.addView(value);
        row.addView(label(" ↓", 10, UI_BLUE, tfBody));
        final Runnable refresh = () -> {
            final String cur = get.get();
            String shown = labels[0];
            for (int i = 0; i < ids.length; ++i) if (ids[i].equals(cur)) shown = labels[i];
            value.setText(shown);
        };
        refresh.run();
        fotuRefreshers.add(refresh);
        row.setClickable(true);
        row.setOnClickListener(v -> {
            final String cur = get.get();
            int sel = 0;
            for (int i = 0; i < ids.length; ++i) if (ids[i].equals(cur)) sel = i;
            showChoiceSheet(title, new java.util.ArrayList<>(java.util.Arrays.asList(labels)),
                    labels[sel], picked -> {
                        for (int i = 0; i < labels.length; ++i) {
                            if (!labels[i].equals(picked)) continue;
                            set.accept(ids[i]);
                            refresh.run();
                            if (uiReady && isFotuStock(filmStock)) {
                                showingOriginal = false;
                                renderFotu();
                            }
                            return;
                        }
                    });
        });
        parent.addView(row, new LinearLayout.LayoutParams(-1, dp(34)));
        // The note is behind the "!" now.

    }

    /** `def`: where a double tap on the pointer puts the row back. */
    private View[] fotuRow(LinearLayout parent, String title, final float lo, final float hi,
                           final java.util.function.Supplier<Float> get,
                           final java.util.function.Consumer<Float> set, String hint, float def) {
        final LinearLayout line = new LinearLayout(this);
        line.setOrientation(LinearLayout.HORIZONTAL);
        line.setGravity(android.view.Gravity.CENTER_VERTICAL);
        line.addView(label(title, 9, UI_INK, tfHan), new LinearLayout.LayoutParams(-2, -2));
        if (hint != null && !hint.isEmpty()) line.addView(bangFor(() -> hint));
        line.addView(new View(this), new LinearLayout.LayoutParams(0, -2, 1f));
        final TextView value = numberReadout();
        line.addView(value, new LinearLayout.LayoutParams(dp(60), -2));
        parent.addView(line, new LinearLayout.LayoutParams(-1, dp(20)));

        final DialBar bar = new DialBar(this);
        bar.setMax(1000);
        styleRange(bar);
        final float fLo = lo, fHi = hi;
        bar.setValueFormat(p -> String.format(java.util.Locale.US, "%.2f",
                fLo + (fHi - fLo) * p / 1000f));
        final Runnable refresh = () -> {
            final float v = get.get();
            bar.setProgress(Math.max(0, Math.min(1000,
                    Math.round((v - lo) / (hi - lo) * 1000f))));
            value.setText(String.format(java.util.Locale.US, "%.2f", v));
        };
        fotuRefreshers.add(refresh);
        refresh.run();
        bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener() {
            @Override public void onProgressChanged(SeekBar sb, int progress, boolean fromUser) {
                final float v = lo + (hi - lo) * progress / 1000f;
                set.accept(v);
                value.setText(String.format(java.util.Locale.US, "%.2f", v));
                // The chain at 800 px is about a fifth of a second now that the
                // host keeps the decoded scene and the tables, so the canvas can
                // follow the finger instead of waiting for the release.
                if (bar.isDragging()) requestFotuLive();
            }
            @Override public void onStartTrackingTouch(SeekBar sb) { }
            @Override public void onStopTrackingTouch(SeekBar sb) {
                if (uiReady && isFotuStock(filmStock)) {
                    showingOriginal = false;
                    renderFotu();
                }
            }
        });
        // **Same tap-to-type as the first engine's rows.** The two rows look
        // identical, and only one of them answered a tap on the number -- which
        // reads as "this number is not editable", not as "this build differs".
        value.setOnClickListener(v ->
                editNumber(title, lo, hi, get.get(), nv -> set.accept(nv), () -> {
                    for (Runnable r : fotuRefreshers) r.run();
                    if (uiReady && isFotuStock(filmStock)) {
                        showingOriginal = false;
                        renderFotu();
                    }
                }));
        // Double tap puts the row back to its neutral and re-develops, exactly
        // as releasing the dial does -- a reset that only moves the thumb is
        // the number lying about the picture.
        final float home = Math.max(lo, Math.min(hi, def));
        final int resetProgress = Math.max(0, Math.min(1000,
                Math.round((home - lo) / (hi - lo) * 1000f)));
        bar.setResetTarget(resetProgress, () -> {
            bar.setProgress(resetProgress);
            set.accept(home);
            value.setText(String.format(java.util.Locale.US, "%.2f", home));
            if (uiReady && isFotuStock(filmStock)) {
                showingOriginal = false;
                setOriginalVisual(false);
                renderFotu();
            }
        });
        parent.addView(bar, new LinearLayout.LayoutParams(-1, dp(32)));
        // The note is behind the "!" now.
        return new View[]{line, bar};
    }

    /** The 冲印 page, for the second engine. */
    /** The seven pages the second engine's print panel is read in. */
    private static final String[] FOTU_GROUPS = {
            "影调", "色彩", "胶片", "颗粒", "光晕", "镜头", "相纸",
    };
    private int fotuGroup = 0;
    /** Which group's body is on screen; -1 until the panel is first built. */
    private int fotuGroupShown = -1;
    /** Which cascade owns the rows; an older one's clean-up checks this. */
    private int panelMotionGen = 0;
    /** The sketch on screen now, which page owns it, and the rows it hid. */
    private android.animation.ValueAnimator lineTravel;
    private View linePanel;
    private java.util.List<View> lineRows;
    /** Frames being traced, and the drawables drawing them. */
    private java.util.List<View> traceHosts;
    private java.util.List<TraceDraw> traceDraws;
    private android.animation.ValueAnimator traceAnim;
    /** Typing: the queue, a cursor into it, and what to put back if cut short. */
    private java.util.List<TypedStep> typeSteps;
    private java.util.List<android.widget.TextView> typeTouched;
    private java.util.List<CharSequence> typeOriginals;
    private android.animation.ValueAnimator typeAnim;
    /** The note popup's own typing run, so it cannot fight the panel's. */
    private android.animation.ValueAnimator noteAnim;
    private android.widget.PopupWindow notePopup;
    private int typeAt;
    /**
     * Per label, the three spans a moment is expressed with: a transparent one
     * over the not-yet-typed tail, and the inverse pair for the word being
     * composed. They are moved, never re-created -- `setSpan` with the same
     * object relocates it, so a page has a fixed number of spans no matter how
     * many moments it goes through.
     */
    private final java.util.HashMap<android.widget.TextView, Object[]> typeSpans =
            new java.util.HashMap<>();
    /** What an arrival actually did, for `boot.txt`. */
    private int traceCount, typeLabelCount, typeStepCount, typeMs;
    private android.view.Choreographer.FrameCallback frameProbe;
    private long probeAt, probeWorst, probeFrames;
    private int lineGen = 0;
    private LinearLayout fotuBody;
    private TextView[] fotuGroupTabs;

    /**
     * The second engine's print panel, one page per group.
     *
     * <p>Its chain exposes fifty knobs, and they used to be one flat column
     * inside a 250 dp window: the first three were reachable, everything below
     * them was a scroll away. Worse, three of them only take effect under
     * another control -- the region switch under highlights and shadows, the
     * grading space under lift and gain, the digital-reference style under the
     * screen medium -- and sitting far from their trigger they read as broken.
     * Each page now holds one physical stage of the chain, in the order the
     * light goes through it.
     */
    private View buildFotuPanel() {
        final LinearLayout panel = new LinearLayout(this);
        panel.setOrientation(LinearLayout.VERTICAL);
        try {
            buildFotuPanelInto(panel);
        } catch (Throwable t) {
            // Same rule as the pages: this is `onCreate`, and an exception here
            // is an app that will not open.
            panel.removeAllViews();
            panel.addView(label("FOTUFILM 面板初始化失败：" + t, 8f, UI_INK, tfHan),
                    new LinearLayout.LayoutParams(-1, dp(34)));
            try {
                DebugSink.text("fotupanel", "build: " + t + "\n"
                        + android.util.Log.getStackTraceString(t));
            } catch (Throwable ignored) { }
        }
        return panel;
    }

    private void buildFotuPanelInto(LinearLayout panel) {
        panel.addView(sectionHead("FOTUFILM / 冲印", this::resetFotuPanel),
                new LinearLayout.LayoutParams(-1, dp(38)));

        // The seven pages are the strip above the tool bar now, not a row of
        // words inside this panel: they were sitting between the heading and the
        // sliders, i.e. in the middle of the page they switch away from.
        fotuGroupTabs = null;

        fotuBody = new LinearLayout(this);
        fotuBody.setOrientation(LinearLayout.VERTICAL);
        // **The cap is what the eight long pages have in common, and it is why
        // 影调 -> 色彩 does not change height: both want more room than the box
        // gives, so both sit at the cap.** The pages that *do* differ are the
        // short ones -- 胶片 is three rows (156 dp), 镜头 four (208 dp) -- and
        // those were the jumps nobody could see: the animation was travelling
        // `fotuBody`'s own height, which is hidden behind this cap. Raising the
        // cap buys nothing (光晕 at 314 dp against its own 312 is two pixels) and
        // costs the photograph 60 dp of height, so it stays at 250.
        final CappedScroll scroll = new CappedScroll(this, dp(PANEL_CAP_DP));
        scroll.addView(fotuBody, new android.widget.FrameLayout.LayoutParams(-1, -2));
        panel.addView(scroll, new LinearLayout.LayoutParams(-1, -2));

        final TextView note = label("fotufilm 引擎：CPU 渲染。拖动时先出小图，松手后出全尺寸。"
                + "片边与日期是 SpektraLab 引擎专属；构图两个引擎都有。", 7.5f, UI_MUTED, tfHan);
        note.setPadding(0, dp(4), 0, dp(6));
        panel.addView(note);

        showFotuGroup(0);
    }

    /**
     * One page of it. Rebuilt on every switch, so the widgets read the fields.
     *
     * <p>**UI thread only.** `applyLook` runs from `reopenFrame` and from the
     * import path, both of which are background threads, and it restores the
     * whole fotu look -- so a call from there used to tear down and rebuild an
     * attached view hierarchy off the main thread, which is a crash on the first
     * frame of a restored session. A call that arrives on the wrong thread is
     * posted instead of run.
     */
    private void showFotuGroup(int index) {
        if (android.os.Looper.myLooper() != android.os.Looper.getMainLooper()) {
            final int wanted = index;
            runOnUiThread(() -> showFotuGroup(wanted));
            return;
        }
        final boolean moved = index != fotuGroupShown;
        fotuGroup = index;
        fotuGroupShown = index;
        if (fotuBody == null) return;
        // 影调 -> 色彩 is a different number of rows, so the block's height moves
        // here too and the photograph above would jump with it. The height that
        // moves is read further down, off the box that is actually visible.
        syncSubRowActive();
        if (fotuGroupTabs != null) {
            for (int i = 0; i < fotuGroupTabs.length; ++i) {
                // A colour change is an `invalidate`, not a measure, so these
                // travel with the height instead of snapping ahead of it.
                tintText(fotuGroupTabs[i], i == index ? UI_INK : UI_MUTED, MS_SOFT);
                underline(fotuGroupTabs[i], i == index);
            }
        }
        fotuRefreshers.clear();
        fotuBody.removeAllViews();
        // The push row only exists on one page; a stale reference would have
        // `refreshFotuPush` writing into a detached label.
        fotuPushValue = null;
        try {
            if (index == 0) buildFotuToneGroup();
            else if (index == 1) buildFotuColourGroup();
            else if (index == 2) buildFotuFilmGroup();
            else if (index == 3) buildFotuGrainGroup();
            else if (index == 4) buildFotuHalationGroup();
            else if (index == 5) buildFotuLensGroup();
            else buildFotuPaperGroup();
        } catch (Throwable t) {
            // **A page that cannot be built is a line of text, not a crash.**
            // This runs on the launch path, where an exception takes the whole
            // activity with it -- and the report then never leaves the device.
            fotuRefreshers.clear();
            fotuBody.removeAllViews();
            fotuBody.addView(label("这一页建不起来：" + t, 8f, UI_INK, tfHan));
            try {
                DebugSink.text("fotupanel", "group " + index + ": " + t + "\n"
                        + android.util.Log.getStackTraceString(t));
            } catch (Throwable ignored) { }
        }
        // **The body was rebuilt in place -- same view, new children.** So this
        // is one of the two callers that has to force the entrance: `fotuBody`
        // is never hidden, and the "already on screen" guard would skip it.
        if (moved) {
            fotuBody.animate().cancel();
            fotuBody.setAlpha(1f);
            fotuBody.setTranslationY(0f);
            componentArrival(fotuBody);
            // **The height that visibly changes is the scroll's.** `fotuBody`
            // lives inside a `CappedScroll`, so `enterPanel(fotuBody, ...)` was
            // travelling a height nobody can see: the box stayed pinned at its
            // cap and 影调 -> 色彩 arrived with no height animation at all.
            // Both ends are capped first, then the box travels between them, and
            // the canvas above breathes like it does on every other page.
            final View box = fotuBody.getParent() instanceof View
                    ? (View) fotuBody.getParent() : null;
            final int cap = box instanceof CappedScroll
                    ? ((CappedScroll) box).cap() : Integer.MAX_VALUE;
            final int w = fotuBody.getWidth() > 0 ? fotuBody.getWidth()
                    : (box != null ? box.getWidth() : 0);
            final int was = box != null ? box.getHeight() : 0;
            final int want = w > 0 ? Math.min(naturalHeight(fotuBody, w), cap) : 0;
            if (box != null && want > 0 && was > 0 && want != was) {
                animateHeightTo(box, was, want);
            }
        }
        refreshFotuPush();
    }

    /** Whether the sheet in use is the digital reference, asked safely. */
    private boolean fotuScreenMedium() {
        try {
            return FotuFilm.SCREEN.equals(fotuMedium());
        } catch (Throwable t) {
            return false;
        }
    }

    /**
     * The grain rows that only answer while the tile model is on.
     *
     * <p>**A knob that moves and changes nothing is worse than one that refuses.**
     * 彩色颗粒, 扫描柔度 and the three layer shares are slots the host reads only
     * when it is sampling a tile bank it has laid out itself; on the default
     * clump model they were five sliders that slid for nothing -- which reads as
     * a broken page, not as a switch that has to come on first. They are greyed
     * and their touches refused until 「胶片颗粒模型」 is on, and the line under
     * the switch says so.
     */
    private final java.util.List<View> grainGated = new java.util.ArrayList<>();
    private TextView fotuGrainNote;

    private void gateGrain(View[] row) {
        if (row == null) return;
        for (View v : row) if (v != null) grainGated.add(v);
    }

    private void refreshGrainGates() {
        final boolean on = fotuFilmGrain;
        for (View v : grainGated) {
            // `setEnabledDeep` is the app's one answer to "dimmed is not the same
            // as disabled": it writes the alpha and the flag all the way down, so
            // the DialBar's own `isEnabled()` gate refuses the drag and the number
            // stops opening the keypad.
            setEnabledDeep(v, on);
        }
        if (fotuGrainNote != null) {
            fotuGrainNote.setText(on
                    ? "真胶片颗粒：下面五项（彩色颗粒 / 扫描柔度 / 三层分量）现在有效"
                    : "彩色颗粒 · 扫描柔度 · 三层分量要开了上面这一项才有效 —— 已置灰");
        }
    }

    /** 影调: what the print's tone curve does, including the region switch. */
    private void buildFotuToneGroup() {
        fotuRow(fotuBody, "曝光", -2f, 2f, () -> fotuEv, v -> fotuEv = v,
                "fotufilm 的曝光在这里：改的是底片的受光量，密度和色彩都跟着变。"
                + "光学页的「曝光」是冲印之后的推拉，拉不回已经到白的高光", 0f);
        // **Only the screen medium has one.** The styles are how a
        // negative becomes a *picture* rather than a print, and the host
        // consults them only when it is building the screen tables -- on
        // paper they change nothing, so offering them there is a switch
        // that does not move.
        if (fotuScreenMedium()) {
            fotuChoiceRow(fotuBody, "数字参考风格", "Digital Reference 怎么把负片变成画面：自动定标、分级打印，还是固定的校准曝光",
                    new String[]{"", "graded-print", "reference-exposure"},
                    new String[]{"自动定标（默认）", "分级打印", "固定校准曝光"},
                    () -> fotuDigitalRef == null ? "" : fotuDigitalRef, v -> fotuDigitalRef = v);
        }
        fotuRow(fotuBody, "高光", -1f, 1f, () -> fotuHighlights, v -> fotuHighlights = v, "往右收高光", 0f);
        fotuRow(fotuBody, "阴影", -1f, 1f, () -> fotuShadows, v -> fotuShadows = v, "往右提阴影", 0f);
        // It is the *region* switch for the two sliders below it: with
        // both at zero the host never reads it, which is why it sat at
        // the top of the panel doing nothing.
        // **The mark is made here, not held from some earlier build.** It used
        // to be a field assigned once, back when this page was one flat column;
        // the pages rebuild, so the field has to follow the square that is
        // actually in the hierarchy. Leaving it null is an NPE inside
        // `toggleRow` on the launch path -- the app did not open.
        fotuLocalToneMark = new Square(this, UI_BLUE, uiToggleOff());
        fotuBody.addView(toggleRow("目标色调（区域定标 · 管高光/阴影）", fotuLocalToneMark, () -> fotuLocalTone > 0.5f, on -> {
            fotuLocalTone = on ? 1f : 0f;
            renderImage();
        }));
        fotuRow(fotuBody, "提暗部", 0f, 1f, () -> fotuShadowDetail, v -> fotuShadowDetail = v,
                "把相纸肩部的黑提起来：暗部打开，黑仍是黑（改的是印相的光，不是加灰）", 0f);
        fotuRow(fotuBody, "收高光", 0f, 1f, () -> fotuHighlightDetail, v -> fotuHighlightDetail = v,
                "把趾部之外的曝光往白里卷：高光保住层次，不会剪成一片白", 0f);
        fotuRow(fotuBody, "印相校正", 0f, 1f, () -> fotuPrintCorrection, v -> fotuPrintCorrection = v,
                "相纸的染层平衡：往右把偏色收到中性，0 是相纸标定的原样", 0f);
        fotuRow(fotuBody, "黑点", 0f, 0.5f, () -> fotuBlackPoint, v -> fotuBlackPoint = v,
                "把黑抬成灰：相纸的暗部整体提亮，不裁切；0 是黑到底", 0f);
        fotuRow(fotuBody, "白点", 0.5f, 1f, () -> fotuWhitePoint, v -> fotuWhitePoint = v,
                "把白压暗：整体变暗并留出高光余量；1 是白到底", 1.0f);
    }

